/* Exact production QuizBot static files from GitHub main, for Cloudflare Workers. */
export const ASSETS = {"/activity-tracker.js":"/* Track activity exclusively inside the QuizBot Mini App.\n   Telegram ID/username are NEVER taken from JavaScript fields for storage:\n   the Netlify API extracts them only after verifying signed Telegram initData.\n   We don't track Telegram's global presence or activity outside this app. */\n(function(){\n  'use strict';\n  let opened=false;\n  let sending=false;\n  let lastOk=0;\n  let lastInteraction=Date.now();\n\n  function initData(){\n    try{return String(window.Telegram?.WebApp?.initData||'')}\n    catch{return ''}\n  }\n  async function heartbeat(){\n    if(sending||document.hidden)return;\n    // A visible but abandoned Mini App must not appear continuously active.\n    if(opened&&Date.now()-lastInteraction>130000)return;\n    const data=initData();\n    if(!data)return;\n    const now=Date.now();\n    if(opened&&now-lastOk<70000)return;\n    sending=true;\n    try{\n      const response=await fetch('/api/activity',{\n        method:'POST',\n        cache:'no-store',\n        credentials:'same-origin',\n        headers:{'Content-Type':'application/json','X-Telegram-Init-Data':data},\n        body:JSON.stringify({event:opened?'heartbeat':'open'})\n      });\n      if(response.ok){\n        opened=true;\n        lastOk=Date.now();\n      }\n    }catch(e){\n      // Tracking errors must never prevent the quiz from working.\n    }finally{sending=false}\n  }\n  // A user is considered active only while their Mini App is visible.\n  setTimeout(heartbeat,1200);\n  setInterval(heartbeat,90000);\n  function markInteraction(){\n    lastInteraction=Date.now();\n    if(opened&&Date.now()-lastOk>=70000)heartbeat();\n  }\n  ['pointerdown','touchstart','keydown','scroll'].forEach(name=>{\n    document.addEventListener(name,markInteraction,{passive:true});\n  });\n  document.addEventListener('visibilitychange',()=>{\n    if(!document.hidden){\n      lastInteraction=Date.now();\n      heartbeat();\n    }\n  });\n  window.addEventListener('focus',()=>{\n    lastInteraction=Date.now();\n    heartbeat();\n  });\n})();\n","/admin-embed.js":"/* Owner-only embedded administration for the existing Netlify-based quiz.\n   Visibility and backend permissions require a VALIDATED, SIGNED Telegram session.\n   initDataUnsafe is only a hint to avoid unnecessary verification requests. */\n(function(){\n  'use strict';\n\n  const OWNER_ID='5305261101';\n  const AUTH_ENDPOINT='/api/admin/me';\n  let authorized=false;\n  let installed=false;\n  let checking=false;\n  let checkedData='';\n  let observer=null;\n  let nextCheckAt=0;\n\n  function telegramApp(){\n    try{return window.Telegram?.WebApp||null}\n    catch{return null}\n  }\n  function telegramInitData(){\n    try{return String(telegramApp()?.initData||'')}\n    catch{return ''}\n  }\n  function displayId(){\n    // Not an authentication mechanism. This hint never causes admin UI to appear.\n    try{\n      const app=telegramApp();\n      const raw=app?.initDataUnsafe?.user?.id;\n      if(raw)return String(raw);\n      const user=new URLSearchParams(app?.initData||'').get('user');\n      return user?String(JSON.parse(user).id||''):'';\n    }catch{return ''}\n  }\n\n  // This is a troubleshooting notice, NOT an admin menu. It never grants access.\n  // It is displayed only if Telegram's local identity hint matches the owner;\n  // Netlify's signed verification is still mandatory for admin permissions.\n  function describeAuthError(code){\n    const reasons={\n      TELEGRAM_SESSION_MISSING:'Telegram не передал данные входа. Откройте Mini App кнопкой бота.',\n      TELEGRAM_BOT_NOT_CONFIGURED:'В Netlify не настроен токен бота для Mini App.',\n      TELEGRAM_SIGNATURE_INVALID:'Ни токен Netlify, ни публичная подпись Telegram не подтвердили запуск нужным ботом.',\n      TELEGRAM_PUBLIC_SIGNATURE_MISSING:'Telegram не передал публичную подпись. Проверьте токен Mini App в Netlify.',\n      NOT_ADMIN_OWNER:'Сервер подтвердил другого Telegram-пользователя.',\n      HTTP_404:'Netlify не нашёл серверный маршрут /api/admin/me.',\n      HTTP_502:'Netlify не смог выполнить серверную функцию.',\n      HTTP_503:'Серверная функция временно недоступна.',\n      NETWORK_ERROR:'Не удалось связаться с Netlify. Проверьте подключение.',\n      INVALID_RESPONSE:'Сервер вернул ответ неверного формата.',\n      INITDATA_EMPTY:'У Mini App нет подписанных данных Telegram. Откройте приложение кнопкой бота.'\n    };\n    return reasons[code]||'Проверка Telegram-авторизации на Netlify не прошла.';\n  }\n  function clearDiagnostic(){\n    document.getElementById('owner-auth-diagnostic')?.remove();\n  }\n  function showDiagnostic(code){\n    if(authorized||displayId()!==OWNER_ID)return;\n    const drawer=document.querySelector('#side-drawer .drawer-list');\n    if(!drawer)return;\n    let notice=document.getElementById('owner-auth-diagnostic');\n    if(!notice){\n      notice=document.createElement('div');\n      notice.id='owner-auth-diagnostic';\n      notice.className='drawer-section';\n      notice.style.cssText='border:1px solid rgba(251,191,36,.3);border-radius:15px;padding:12px;margin-top:14px;background:rgba(120,53,15,.12)';\n      const heading=document.createElement('div');\n      heading.className='drawer-section-title';\n      heading.textContent='ПРОВЕРКА ДОСТУПА';\n      const explanation=document.createElement('div');\n      explanation.id='owner-auth-error-text';\n      explanation.style.cssText='font-size:12px;line-height:1.6;opacity:.9;overflow-wrap:anywhere;margin:9px 0';\n      const retry=document.createElement('button');\n      retry.type='button';\n      retry.className='drawer-item';\n      retry.style.cssText='font-size:13px;min-height:42px;width:100%;cursor:pointer';\n      retry.textContent='↻ Проверить ещё раз';\n      retry.addEventListener('click',()=>checkOwner(true));\n      notice.append(heading,explanation,retry);\n      drawer.appendChild(notice);\n    }\n    const message=document.getElementById('owner-auth-error-text');\n    if(message)message.textContent=describeAuthError(code)+' Код: '+String(code||'UNKNOWN').slice(0,48);\n  }\n\n  function hideSubjectOnAdmin(){\n    const admin=document.getElementById('admin-screen');\n    document.body.classList.toggle('owner-admin-active',!!admin&&!admin.classList.contains('hidden'));\n  }\n\n  function makeScreen(){\n    const existing=document.getElementById('admin-screen');\n    if(existing)return existing;\n    const app=document.querySelector('.app');\n    if(!app)return null;\n    const style=document.createElement('style');\n    style.textContent=[\n      '#admin-screen{padding:0!important;border:0!important;background:transparent!important;box-shadow:none!important}',\n      '.owner-admin-header{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:4px 0 12px}',\n      '.owner-admin-header h2{margin:0;font-size:19px;color:var(--txt)}',\n      '.owner-admin-frame{display:block;width:100%;height:calc(100dvh - 150px);min-height:420px;border:1px solid var(--line);border-radius:16px;background:#0b1424}',\n      '.owner-admin-active .subject-switch-wrap{display:none!important}',\n      'body:has(#admin-screen:not(.hidden)) .subject-switch-wrap{display:none!important}',\n      '#owner-admin-link{width:100%;cursor:pointer;text-align:left}',\n      '@media(max-width:560px){.owner-admin-frame{height:calc(100dvh - 142px);min-height:370px;border-radius:13px}.owner-admin-header h2{font-size:16px}}'\n    ].join('\\n');\n    document.head.appendChild(style);\n\n    const section=document.createElement('section');\n    section.id='admin-screen';\n    section.className='screen hidden';\n    section.setAttribute('aria-label','Панель владельца');\n    const header=document.createElement('div');\n    header.className='owner-admin-header';\n    const heading=document.createElement('h2');\n    heading.textContent='⚙️ Админ-панель';\n    const back=document.createElement('button');\n    back.type='button';\n    back.className='btn btn-gray btn-small';\n    back.textContent='← В меню';\n    back.onclick=()=>{\n      if(typeof window.backToMenu==='function')window.backToMenu();\n      else if(typeof window.showScreen==='function')window.showScreen('start-screen');\n      hideSubjectOnAdmin();\n    };\n    header.append(heading,back);\n    const frame=document.createElement('iframe');\n    frame.id='owner-admin-frame';\n    frame.className='owner-admin-frame';\n    frame.title='Управление Premium, банами и вопросами';\n    frame.setAttribute('referrerpolicy','same-origin');\n    section.append(header,frame);\n    app.appendChild(section);\n\n    if(typeof MutationObserver==='function'){\n      const watch=new MutationObserver(hideSubjectOnAdmin);\n      watch.observe(section,{attributes:true,attributeFilter:['class']});\n    }\n    return section;\n  }\n\n  function openAdmin(){\n    if(!authorized)return;\n    const section=makeScreen();\n    if(!section||typeof window.showScreen!=='function')return;\n    window.showScreen('admin-screen');\n    hideSubjectOnAdmin();\n    const iframe=document.getElementById('owner-admin-frame');\n    if(iframe&&!iframe.getAttribute('src'))iframe.src='/admin/index.html?embedded=1&v=5';\n  }\n\n  function insertMenu(){\n    if(!authorized)return;\n    clearDiagnostic();\n    makeScreen();\n    const drawer=document.querySelector('#side-drawer .drawer-list');\n    if(!drawer)return;\n    if(!document.getElementById('owner-admin-link')){\n      const group=document.createElement('div');\n      group.className='drawer-section owner-admin-group';\n      const heading=document.createElement('div');\n      heading.className='drawer-section-title';\n      heading.textContent='УПРАВЛЕНИЕ';\n      const button=document.createElement('button');\n      button.id='owner-admin-link';\n      button.type='button';\n      button.className='drawer-item drawer-owner';\n      const ico=document.createElement('span');\n      ico.textContent='⚙️';\n      const title=document.createElement('span');\n      title.textContent='Панель администратора';\n      button.append(ico,title);\n      button.addEventListener('click',openAdmin);\n      group.append(heading,button);\n      drawer.append(group);\n    }\n    installed=true;\n    if(!observer && typeof MutationObserver==='function'){\n      observer=new MutationObserver(()=>{\n        if(authorized&&!document.getElementById('owner-admin-link'))insertMenu();\n      });\n      observer.observe(drawer,{childList:true});\n    }\n  }\n\n  function removeMenu(){\n    document.querySelector('.owner-admin-group')?.remove();\n    document.getElementById('admin-screen')?.remove();\n    document.body.classList.remove('owner-admin-active');\n    authorized=false;\n    installed=false;\n  }\n\n  async function checkOwner(force=false){\n    if(checking)return;\n    const initData=telegramInitData();\n    const id=displayId();\n    if(id!==OWNER_ID){\n      if(authorized)removeMenu();\n      clearDiagnostic();\n      return;\n    }\n    if(!initData){\n      showDiagnostic('INITDATA_EMPTY');\n      return;\n    }\n    if(authorized&&checkedData===initData){if(!installed)insertMenu();return}\n    if(!force&&Date.now()<nextCheckAt)return;\n    checking=true;\n    nextCheckAt=Date.now()+5000;\n    try{\n      const response=await fetch(AUTH_ENDPOINT,{\n        method:'GET',\n        headers:{'X-Telegram-Init-Data':initData},\n        cache:'no-store',credentials:'same-origin'\n      });\n      const result=await response.json().catch(()=>null);\n      const allowed=response.ok&&result?.ok===true&&result?.admin===true;\n      if(!allowed){\n        checkedData='';\n        if(authorized)removeMenu();\n        const code=String(result?.code||('HTTP_'+response.status));\n        showDiagnostic(code);\n        // This diagnostic does not reveal admin controls or accept client IDs.\n        return;\n      }\n      checkedData=initData;\n      authorized=true;\n      clearDiagnostic();\n      insertMenu();\n    }catch(e){\n      if(authorized)removeMenu();\n      showDiagnostic('NETWORK_ERROR');\n      console.warn('Owner authorization check unavailable');\n    }finally{checking=false}\n  }\n\n  // Telegram WebApp may finish initialization after this script is evaluated.\n  // Wait for it but do not show an admin button until the backend confirms identity.\n  checkOwner();\n  let retries=0;\n  const timer=setInterval(()=>{\n    checkOwner();\n    if(++retries>=90||authorized)clearInterval(timer);\n  },650);\n  document.addEventListener('visibilitychange',()=>{\n    if(!document.hidden)checkOwner();\n  });\n  window.addEventListener('focus',checkOwner);\n})();\n","/eco-final-patch.css":"/* Final UX + access policy patch */\n.premium-badge.ordinary{\n  background:linear-gradient(135deg,#e2e8f0,#cbd5e1)!important;\n  color:#0f172a!important;\n  box-shadow:0 8px 20px rgba(148,163,184,.22)!important;\n}\n.premium-badge.ordinary::before{content:\"👤\"!important;margin-right:4px;}\n@media(max-width:420px){\n  .premium-badge.ordinary::before{margin-right:0!important;}\n}\n#usage-limit-note{\n  margin:10px 0 0;\n  padding:12px 14px;\n  border-radius:18px;\n  font-size:13px;\n  font-weight:900;\n  line-height:1.38;\n  border:1px solid rgba(148,163,184,.28);\n  background:rgba(255,255,255,.56);\n  color:var(--txt);\n}\nbody:not(.light) #usage-limit-note{\n  background:rgba(15,23,42,.48);\n  border-color:rgba(71,85,105,.55);\n}\n#usage-limit-note.limit-lock{\n  border-color:rgba(239,68,68,.34);\n  background:rgba(254,242,242,.94);\n  color:#991b1b;\n}\nbody:not(.light) #usage-limit-note.limit-lock{\n  background:rgba(127,29,29,.22);\n  color:#fecaca;\n}\n#usage-limit-note.limit-premium{\n  border-color:rgba(245,158,11,.26);\n  background:rgba(255,251,235,.9);\n  color:#92400e;\n}\nbody:not(.light) #usage-limit-note.limit-premium{\n  background:rgba(120,53,15,.22);\n  color:#fde68a;\n}\nbody.inner-section-open .chip,\nbody.inner-section-open #premium-badge{\n  opacity:0!important;\n  visibility:hidden!important;\n  pointer-events:none!important;\n  width:0!important;\n  min-width:0!important;\n  max-width:0!important;\n  padding:0!important;\n  margin:0!important;\n  overflow:hidden!important;\n  border-width:0!important;\n}\nbody.inner-section-open .topbar{gap:8px!important;}\n#real-sticky-actions{\n  display:grid;\n  grid-template-columns:1fr;\n  gap:8px;\n  margin-top:10px;\n}\n#real-sticky-actions .btn{\n  min-height:44px!important;\n  border-radius:16px!important;\n}\nbody.usage-locked .app #start-screen .menu-main-btn{\n  opacity:.45!important;\n  filter:grayscale(.55)!important;\n}\nbody.usage-locked .app #start-screen .menu-main-btn::after{\n  content:\"\";\n}\nbody.usage-locked .app #start-screen::after{\n  content:\"Лимит использован\";\n  display:block;\n  margin-top:10px;\n  text-align:center;\n  font-size:12px;\n  font-weight:1000;\n  color:var(--muted);\n}\n\n\n/* Final fix: do not show full question map while solving */\n#q-map,.q-map{display:none!important;}\n\n/* Final fix: completely prevent old settings-collapse from flashing */\n#settings-collapse{display:none!important;}\n\n/* Real exam fixed top control panel — uses fixed, not sticky */\n#real-fixed-top{\n  position:fixed!important;\n  left:50%!important;\n  top:calc(8px + env(safe-area-inset-top,0px))!important;\n  transform:translateX(-50%)!important;\n  width:min(560px, calc(100vw - 16px))!important;\n  z-index:9997!important;\n  padding:10px 12px 11px!important;\n  border-radius:24px!important;\n  background:rgba(255,255,255,.94)!important;\n  border:1px solid rgba(226,232,240,.95)!important;\n  box-shadow:0 16px 42px rgba(15,23,42,.20)!important;\n  backdrop-filter:blur(18px)!important;\n  -webkit-backdrop-filter:blur(18px)!important;\n}\nbody:not(.light) #real-fixed-top{\n  background:rgba(15,23,42,.95)!important;\n  border-color:rgba(71,85,105,.72)!important;\n  box-shadow:0 18px 46px rgba(0,0,0,.38)!important;\n}\n.real-fixed-row{\n  display:grid!important;\n  grid-template-columns:1fr auto!important;\n  align-items:center!important;\n  gap:10px!important;\n}\n.real-fixed-title{\n  font-size:12px!important;\n  font-weight:1000!important;\n  color:var(--muted)!important;\n  line-height:1.15!important;\n}\n.real-fixed-time{\n  margin-top:2px!important;\n  font-size:23px!important;\n  font-weight:1000!important;\n  color:var(--cyan)!important;\n  letter-spacing:.4px!important;\n  line-height:1.05!important;\n}\n.real-fixed-finish{\n  min-height:42px!important;\n  padding:9px 13px!important;\n  border-radius:16px!important;\n  white-space:nowrap!important;\n  font-size:13px!important;\n}\n.real-fixed-line{\n  height:8px!important;\n  margin-top:9px!important;\n  border-radius:999px!important;\n  overflow:hidden!important;\n  background:rgba(148,163,184,.24)!important;\n}\n.real-fixed-fill{\n  height:100%!important;\n  width:100%;\n  border-radius:999px!important;\n  background:linear-gradient(90deg,#22c55e,#38bdf8,#6366f1)!important;\n  transition:width .25s linear!important;\n}\nbody.real-exam-fixed-on #real-exam-screen{\n  padding-top:112px!important;\n}\nbody.real-exam-fixed-on .topbar{\n  opacity:0!important;\n  pointer-events:none!important;\n}\nbody.real-exam-fixed-on #real-exam-screen .real-head{\n  position:relative!important;\n  top:auto!important;\n  z-index:1!important;\n  margin-top:0!important;\n}\nbody.real-exam-fixed-on #real-exam-screen .real-head #real-sticky-actions,\nbody.real-exam-fixed-on #real-exam-screen .real-head .real-top,\nbody.real-exam-fixed-on #real-exam-screen .real-head .real-line{\n  display:none!important;\n}\n#real-fixed-top.hidden{\n  display:none!important;\n}\n@media(max-width:430px){\n  #real-fixed-top{\n    width:calc(100vw - 14px)!important;\n    padding:9px 10px 10px!important;\n    border-radius:22px!important;\n  }\n  .real-fixed-time{font-size:21px!important;}\n  .real-fixed-finish{font-size:12px!important;padding:8px 11px!important;}\n  body.real-exam-fixed-on #real-exam-screen{\n    padding-top:104px!important;\n  }\n}\n\n\n/* Final compact limit/offerta polish */\n#usage-limit-note{\n  margin:10px 0 12px!important;\n  padding:10px 12px!important;\n  border-radius:18px!important;\n  text-align:center!important;\n  font-size:14px!important;\n  line-height:1.25!important;\n}\n#usage-limit-note.limit-premium{\n  display:none!important;\n}\n#usage-limit-note.limit-compact{\n  display:block!important;\n  border-color:rgba(59,130,246,.35)!important;\n  background:rgba(37,99,235,.10)!important;\n  color:#dbeafe!important;\n}\nbody.light #usage-limit-note.limit-compact{\n  color:#1e3a8a!important;\n  background:rgba(219,234,254,.86)!important;\n}\n#usage-limit-note.limit-compact b{\n  font-size:18px!important;\n  letter-spacing:.2px!important;\n}\n#usage-limit-note.limit-lock{\n  display:block!important;\n}\n.offer-modal{\n  position:fixed!important;\n  inset:0!important;\n  z-index:10020!important;\n  display:flex!important;\n  align-items:center!important;\n  justify-content:center!important;\n  padding:16px!important;\n  background:rgba(2,6,23,.62)!important;\n  backdrop-filter:blur(8px)!important;\n  -webkit-backdrop-filter:blur(8px)!important;\n}\n.offer-modal.hidden{display:none!important;}\n.offer-box{\n  width:min(520px,100%)!important;\n  max-height:84vh!important;\n  overflow:auto!important;\n  border-radius:28px!important;\n  padding:16px!important;\n  background:rgba(255,255,255,.96)!important;\n  border:1px solid rgba(226,232,240,.95)!important;\n  box-shadow:0 24px 70px rgba(0,0,0,.32)!important;\n  color:#0f172a!important;\n}\nbody:not(.light) .offer-box{\n  background:rgba(15,23,42,.97)!important;\n  border-color:rgba(71,85,105,.75)!important;\n  color:#f8fafc!important;\n}\n.offer-head{\n  display:flex!important;\n  justify-content:space-between!important;\n  align-items:center!important;\n  gap:12px!important;\n  margin-bottom:10px!important;\n}\n.offer-title{\n  font-size:20px!important;\n  font-weight:1000!important;\n}\n.offer-close{\n  width:42px!important;\n  height:42px!important;\n  border-radius:14px!important;\n  border:1px solid var(--line)!important;\n  background:transparent!important;\n  color:inherit!important;\n  font-size:25px!important;\n  font-weight:900!important;\n}\n.offer-body{\n  display:grid!important;\n  gap:10px!important;\n  font-size:14px!important;\n  line-height:1.45!important;\n  font-weight:850!important;\n}\n.offer-card{\n  border-radius:18px!important;\n  padding:12px!important;\n  border:1px solid rgba(148,163,184,.30)!important;\n  background:rgba(248,250,252,.86)!important;\n}\nbody:not(.light) .offer-card{\n  background:rgba(30,41,59,.74)!important;\n  border-color:rgba(71,85,105,.65)!important;\n}\n.offer-card b{display:block!important;margin-bottom:5px!important;}\n.offer-card ul{margin:7px 0 0 18px!important;padding:0!important;}\n.offer-card li{margin:4px 0!important;}\n\n/* Stable no-flicker limit display */\n#usage-limit-note{transition:none!important;animation:none!important}\n#usage-limit-note:not(.limit-ready){visibility:hidden!important;height:0!important;min-height:0!important;margin:0!important;padding:0!important;border:0!important;overflow:hidden!important}\n#usage-limit-note.limit-ready.limit-premium{display:none!important}\n#usage-limit-note.limit-ready.limit-compact,#usage-limit-note.limit-ready.limit-lock{display:block!important;visibility:visible!important;margin:10px 0 12px!important;padding:10px 12px!important;border-radius:18px!important;text-align:center!important;font-size:14px!important;line-height:1.25!important}\n#usage-limit-note.limit-ready.limit-compact{border:1px solid rgba(59,130,246,.35)!important;background:rgba(37,99,235,.10)!important;color:#dbeafe!important}\nbody.light #usage-limit-note.limit-ready.limit-compact{color:#1e3a8a!important;background:rgba(219,234,254,.86)!important}\n#usage-limit-note.limit-ready.limit-lock{border:1px solid rgba(239,68,68,.34)!important;background:rgba(127,29,29,.22)!important;color:#fecaca!important}\nbody.light #usage-limit-note.limit-ready.limit-lock{background:rgba(254,242,242,.94)!important;color:#991b1b!important}\n#usage-limit-note.limit-ready b{font-size:18px!important;letter-spacing:.2px!important}\n#config-error.limit-auto-message{display:none!important}\nbody.usage-locked #config-error:not(.manual-error){display:none!important}\n\n/* unified subscription + stable drawer grouping */\n.premium-badge.ordinary{background:linear-gradient(135deg,#64748b,#334155)!important;color:#fff!important;box-shadow:0 8px 20px rgba(51,65,85,.20)!important}\n.premium-badge.ordinary::before{content:\"👤\"!important}\n.drawer-list{gap:14px!important;align-content:start;overflow:auto;max-height:calc(100vh - 118px);padding-right:2px}\n.drawer-section{display:grid;gap:8px;padding:10px;border:1px solid rgba(148,163,184,.24);border-radius:20px;background:rgba(248,250,252,.72)}\nbody:not(.light) .drawer-section{background:rgba(15,23,42,.42);border-color:rgba(71,85,105,.55)}\n.drawer-section-title{font-size:11px;font-weight:1000;text-transform:uppercase;letter-spacing:1.2px;color:var(--muted);padding:0 4px 1px}\n.drawer-item{text-decoration:none!important;position:relative;overflow:hidden;min-height:50px;border-radius:16px!important;border:1px solid transparent!important;box-shadow:0 8px 18px rgba(15,23,42,.08);line-height:1.25;justify-content:flex-start}\n.drawer-item span{display:block;min-width:0}.drawer-item:active{transform:scale(.985)}\n.drawer-learn{background:linear-gradient(135deg,rgba(37,99,235,.14),rgba(14,165,233,.12))!important;border-color:rgba(37,99,235,.25)!important;color:#1d4ed8!important}\n.drawer-star{background:linear-gradient(135deg,rgba(245,158,11,.18),rgba(251,191,36,.12))!important;border-color:rgba(245,158,11,.28)!important;color:#92400e!important}\n.drawer-error{background:linear-gradient(135deg,rgba(239,68,68,.16),rgba(244,63,94,.10))!important;border-color:rgba(239,68,68,.24)!important;color:#b91c1c!important}\n.drawer-history{background:linear-gradient(135deg,rgba(124,58,237,.16),rgba(168,85,247,.10))!important;border-color:rgba(124,58,237,.24)!important;color:#6d28d9!important}\n.drawer-premium{background:linear-gradient(135deg,#fbbf24,#f59e0b)!important;border-color:rgba(245,158,11,.55)!important;color:#111827!important;box-shadow:0 12px 26px rgba(245,158,11,.22)!important}\n.drawer-rules{background:linear-gradient(135deg,rgba(20,184,166,.16),rgba(34,211,238,.10))!important;border-color:rgba(20,184,166,.24)!important;color:#0f766e!important}\n.drawer-admin{background:linear-gradient(135deg,rgba(56,189,248,.16),rgba(59,130,246,.10))!important;border-color:rgba(56,189,248,.25)!important;color:#0369a1!important}\nbody:not(.light) .drawer-learn{color:#bfdbfe!important}body:not(.light) .drawer-star{color:#fde68a!important}body:not(.light) .drawer-error{color:#fecaca!important}body:not(.light) .drawer-history{color:#ddd6fe!important}body:not(.light) .drawer-rules{color:#99f6e4!important}body:not(.light) .drawer-admin{color:#bae6fd!important}\n.limit-inline-btn,.limit-sub-btn{border:0;border-radius:999px;padding:7px 10px;margin-left:6px;font-weight:1000;cursor:pointer;color:#111827;background:linear-gradient(135deg,#fbbf24,#f59e0b)}\n.limit-sub-btn{display:inline-flex;margin:8px 0 0;min-height:36px;align-items:center;justify-content:center}.paybox .btn{text-decoration:none}.pay-value{word-break:break-word}\n@media(max-width:420px){.drawer-list{max-height:calc(100vh - 108px);gap:11px}.drawer-section{padding:8px;border-radius:18px}.drawer-item{min-height:48px;font-size:14px;padding:12px!important}.limit-inline-btn{display:inline-flex;margin:7px 0 0}}\n@media(max-width:520px){.card,.real-head,.real-actions,.sticky-list-head{backdrop-filter:none!important}.drawer-backdrop{backdrop-filter:none!important}.side-drawer{backdrop-filter:none!important}}\n\n/* 2026 terminal activation cleanup */\n#usage-limit-note{display:none!important}\n@media(max-width:420px){\n  .premium-badge{font-size:11px!important;padding:7px 10px!important;min-width:auto!important;max-width:190px!important;overflow:hidden;text-overflow:ellipsis}\n  .premium-badge::before{font-size:14px!important;margin-right:4px!important}\n}\n","/eco-final-patch.js":"(function(){\n  'use strict';\n  const ADMIN='nurislombekm';\n  const ADMIN_URL='https://t.me/'+ADMIN;\n  const DAY=86400000;\n  const LIMIT=3;\n  const USAGE_KEY='macro_daily_limit_v2';\n  const $=(s,r=document)=>r.querySelector(s);\n  const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));\n  const ready=fn=>document.readyState==='loading'?document.addEventListener('DOMContentLoaded',fn):fn();\n  const pad=n=>String(n).padStart(2,'0');\n  const fmt=ts=>{const d=new Date(ts);return `${pad(d.getDate())}.${pad(d.getMonth()+1)}.${d.getFullYear()}, ${pad(d.getHours())}:${pad(d.getMinutes())}`};\n  const esc=s=>String(s??'').replace(/[&<>\\\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\\\"':'&quot;'}[m]||m));\n  let accessPromise=null;\n\n  function tgId(){try{return typeof cleanUserId==='function'?cleanUserId(tgUserId):String(window.tgUserId||'').replace(/\\D+/g,'')}catch(e){return ''}}\n  function premiumRec(id){\n    id=String(id||'').replace(/\\D+/g,'');\n    const primary=window.accessLists?.premium;\n    const access=window.accessLists?.access;\n    if((!primary && !access) || !id)return null;\n    const sources=[];\n    function pushList(list){ if(!list)return; sources.push(list.users, list.premium_users, list.premium, list.user_ids, list.telegram_ids, list); }\n    pushList(primary);\n    pushList(access);\n    if(access&&access.keys&&typeof access.keys==='object'){\n      for(const [key,rec] of Object.entries(access.keys)){\n        const uid=String(rec&&typeof rec==='object'?(rec.uid||rec.user_id||rec.telegram_id):'').replace(/\\D+/g,'');\n        if(uid===id)return {...rec,key};\n      }\n    }\n    for(const u of sources){\n      if(!u)continue;\n      if(Array.isArray(u)){\n        const found=u.find(x=>String(typeof x==='object'?(x.id||x.user_id||x.telegram_id):x).replace(/\\D+/g,'')===id);\n        if(found)return typeof found==='object'?found:{active:true};\n      }\n      if(typeof u==='object'){\n        const direct=u[id]||u[String(id)];\n        if(direct)return direct;\n        const found=Object.entries(u).find(([k,v])=>String(k).replace(/\\D+/g,'')===id);\n        if(found)return found[1];\n      }\n    }\n    return null;\n  }\n  function activeRec(rec){\n    if(!rec)return false;\n    if(rec===true)return true;\n    if(typeof rec==='object'){\n      if(rec.active===false || rec.status==='inactive' || rec.status==='blocked')return false;\n      const until=rec.until||rec.exp||rec.expires;\n      if(until && Date.now()>new Date(String(until).includes('T')?until:until+'T23:59:59').getTime())return false;\n      return true;\n    }\n    return false;\n  }\n  function recDeviceReason(rec){\n    if(!rec || typeof rec!=='object')return '';\n    const expected=String(rec.device||rec.fingerprint||rec.fp||'').trim().toUpperCase();\n    if(!expected)return '';\n    const current=(typeof getDeviceFingerprint==='function'?getDeviceFingerprint():'').toUpperCase();\n    if(current && expected!==current)return rec.reason||`Подписка привязана к другому устройству. Ваше устройство: ${current}`;\n    return '';\n  }\n  function isPremium(){\n    const id=tgId();\n    if(!id)return false;\n    const rec=premiumRec(id);\n    if(!activeRec(rec))return false;\n    if(recDeviceReason(rec))return false;\n    try{if(typeof banReason==='function' && banReason(id))return false}catch(e){}\n    try{if(typeof deviceLockReason==='function' && deviceLockReason(id))return false}catch(e){}\n    return true;\n  }\n  function updateBadge(){\n    const el=$('#premium-badge');\n    if(!el)return;\n    const p=isPremium();\n    el.classList.remove('hidden');\n    el.classList.toggle('ordinary',!p);\n    el.textContent=p?'PRO':'Free';\n    el.setAttribute('aria-label',p?'Премиум пользователь':'Обычный пользователь');\n    el.title=p?'Premium активен':'Бесплатный доступ';\n  }\n  function usageRecords(){\n    let a=[];try{a=JSON.parse(localStorage.getItem(USAGE_KEY)||'[]')}catch(e){}\n    const now=Date.now();\n    a=(Array.isArray(a)?a:[]).map(Number).filter(x=>Number.isFinite(x)&&now-x<DAY).sort((a,b)=>a-b);\n    try{localStorage.setItem(USAGE_KEY,JSON.stringify(a))}catch(e){}\n    return a;\n  }\n  function setUsage(a){try{localStorage.setItem(USAGE_KEY,JSON.stringify(a))}catch(e){}}\n  function limitInfo(){\n    const p=isPremium();\n    const records=p?[]:usageRecords();\n    const used=records.length;\n    const left=p?Infinity:Math.max(0,LIMIT-used);\n    return {premium:p,used,left,locked:!p&&left<=0,resetAt:records[0]?records[0]+DAY:null};\n  }\n  function ensureLimitNote(){\n    let n=$('#usage-limit-note');\n    if(n)return n;\n    n=document.createElement('div');n.id='usage-limit-note';\n    const anchor=$('#resume-card')||$('#start-screen .center')||$('#start-screen');\n    if(anchor)anchor.insertAdjacentElement('afterend',n);\n    return n;\n  }\n  function renderLimit(){\n    updateBadge();\n    const info=limitInfo();\n    try{ if(typeof updateMainLimitBadge==='function') updateMainLimitBadge(info); }catch(e){}\n    const startVisible=!!($('#start-screen') && !$('#start-screen').classList.contains('hidden'));\n    document.body.classList.toggle('usage-locked',info.locked && startVisible);\n    const n=$('#usage-limit-note');\n    if(n){n.style.display='none';n.innerHTML='';n.className='limit-ready';}\n    const err=$('#config-error');\n    if(err && /лимит/i.test(err.textContent||'')){err.textContent='';err.classList.add('hidden');}\n    return info;\n  }\n  window.registerCompletedTest=function(){\n    const info=limitInfo();\n    if(info.premium)return info;\n    const a=usageRecords();a.push(Date.now());setUsage(a);return renderLimit();\n  };\n  window.hasAnyFullAccessNow=function(){return isPremium()};\n  window.refreshPremiumBadge=async function(){\n    if(typeof loadLists==='function'){\n      try{ if(!accessPromise)accessPromise=loadLists().finally(()=>setTimeout(()=>{accessPromise=null},30000)); await accessPromise; }catch(e){}\n    }\n    updateBadge();renderLimit();\n  };\n  window.updatePremiumBadge=function(){updateBadge()};\n\n  function subscriptionText(){\n    const fp=typeof getDeviceFingerprint==='function'?getDeviceFingerprint():'-';\n    const summary=typeof getDeviceSummary==='function'?getDeviceSummary():'';\n    return `Здравствуйте! Хочу активировать премиум-доступ.\\nСумма оплаты: 30 000 сум\\nКарта: 5614 6805 7717 0398\\nОплату отправил(а). Чек прикрепляю.\\nTelegram ID: ${tgId()||'-'}\\nID устройства: ${fp}\\n${summary}`;\n  }\n  window.copyDeviceId=function(){navigator.clipboard?.writeText(String(typeof getDeviceFingerprint==='function'?getDeviceFingerprint():''));};\nwindow.copyCardNumber=function(){navigator.clipboard?.writeText('5614 6805 7717 0398');const e=$('#pay-error');if(e){e.style.color='#38bdf8';e.textContent='Номер карты скопирован: 5614 6805 7717 0398';}};\n  window.copySubscriptionData=function(){navigator.clipboard?.writeText(subscriptionText());const e=$('#pay-error');if(e){e.style.color='#38bdf8';e.textContent='Данные скопированы. Отправьте их вместе с чеком @'+ADMIN+'.';}};\n  window.openSubscriptionModal=function(){\n    const uid=$('#pay-user-id');if(uid)uid.textContent=tgId()||'Откройте через Telegram Mini App';\n    const dev=$('#pay-device-id');if(dev)dev.textContent=typeof getDeviceFingerprint==='function'?getDeviceFingerprint():'-';\n    const pay=$('#paywall');if(pay)pay.classList.remove('hidden');\n    const err=$('#pay-error');if(err){err.style.color='#f87171';err.textContent='Оплатите 30 000 сум на карту 5614 6805 7717 0398, затем отправьте чек, Telegram ID и ID устройства @'+ADMIN+'.';}\n  };\n  window.showPaywall=function(msg=''){\n    window.openSubscriptionModal();\n    const e=$('#pay-error');if(e&&msg){e.style.color='#f87171';e.textContent=msg;}\n  };\n  window.hidePaywall=function(){ $('#paywall')?.classList.add('hidden'); };\n  window.activateAccessCode=function(){ window.openSubscriptionModal(); };\n  window.checkAccess=async function(showMsg=true){\n    if(typeof loadLists==='function'){\n      try{ if(!accessPromise)accessPromise=loadLists().finally(()=>setTimeout(()=>{accessPromise=null},30000)); await accessPromise; }catch(e){}\n    }\n    const id=tgId();\n    if(!id){updateBadge();if(showMsg)showPaywall('Откройте сайт через Telegram Mini App, чтобы получить Telegram ID.');return false;}\n    try{const b=typeof banReason==='function'?banReason(id):'';if(b){updateBadge();if(typeof clearLocalCode==='function')clearLocalCode();if(showMsg)showPaywall(b);return false;}}catch(e){}\n    const rec=premiumRec(id);\n    if(!rec){\n      window.unlocked=false;updateBadge();renderLimit();\n      if(showMsg)showPaywall('Подписка не найдена для ID '+id+'. Проверьте доступ в закрытом backend и обновите сайт.');\n      return false;\n    }\n    if(!activeRec(rec)){\n      window.unlocked=false;updateBadge();renderLimit();\n      const until=(rec&&typeof rec==='object')?(rec.expires||rec.exp||rec.until||''):'';\n      if(showMsg)showPaywall('Подписка для ID '+id+' не активна'+(until?' или срок истёк: '+until:'')+'. Для продления оплатите 30 000 сум на карту 5614 6805 7717 0398 и отправьте чек @'+ADMIN+'.');\n      return false;\n    }\n    const devReason=recDeviceReason(rec) || (typeof deviceLockReason==='function'?deviceLockReason(id):'');\n    if(devReason){updateBadge();if(showMsg)showPaywall(devReason);return false;}\n    window.unlocked=true;hidePaywall();renderLimit();return true;\n  };\n  window.debugSubscriptionInfo=async function(){\n    if(typeof loadLists==='function')await loadLists();\n    const id=tgId();\n    const fp=typeof getDeviceFingerprint==='function'?getDeviceFingerprint():'';\n    const rec=premiumRec(id);\n    const info={detectedTelegramId:id, fingerprint:fp, premiumRecord:rec, active:activeRec(rec), deviceReason:recDeviceReason(rec), premiumAccessFromBackend:window.accessLists?.premium};\n    console.log('SUBSCRIPTION DEBUG', info);\n    alert('ID сайта: '+(id||'-')+'\\nУстройство: '+(fp||'-')+'\\nЗапись найдена: '+(rec?'да':'нет')+'\\nАктивна: '+(activeRec(rec)?'да':'нет')+'\\nПричина устройства: '+(recDeviceReason(rec)||'-'));\n    return info;\n  };\n  window.guardedAction=async function(fn){try{buttonPop(event)}catch(e){};const ok=await (typeof withOneSecondLoader==='function'?withOneSecondLoader(()=>checkAccess(true)):checkAccess(true));if(ok && !renderLimit().locked)fn();};\n  window.guardedStart=async function(mode){\n    try{buttonPop(event)}catch(e){}\n    if(typeof loadLists==='function'){try{ if(!accessPromise)accessPromise=loadLists().finally(()=>setTimeout(()=>{accessPromise=null},30000)); await accessPromise; }catch(e){}}\n    const id=tgId();\n    try{const b=typeof banReason==='function'?banReason(id):'';if(b){updateBadge();if(typeof showBlockedPaywall==='function')showBlockedPaywall(b);else showPaywall(b);return;}}catch(e){}\n    const info=renderLimit();\n    if(info.locked){\n      const reset=info.resetAt?new Date(info.resetAt).toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'}):'позже';\n      if(typeof showConfigError==='function')showConfigError(`Лимит бесплатных тестов исчерпан (${LIMIT}/${LIMIT}). Сброс в ${reset}. Активируйте подписку, чтобы решать без лимита.`);\n      if(typeof openSubscriptionModal==='function')openSubscriptionModal();\n      return;\n    }\n    startTest(mode);\n    if(!info.premium){const a=usageRecords();a.push(Date.now());setUsage(a);renderLimit();}\n  };\n\n  function makeDrawerSection(title,items){\n    return `<div class=\"drawer-section\"><div class=\"drawer-section-title\">${title}</div>${items.join('')}</div>`;\n  }\n  function improveDrawer(){\n    const list=$('.drawer-list');\n    if(!list || list.dataset.grouped==='1')return;\n    list.dataset.grouped='1';\n    list.innerHTML=makeDrawerSection('Обучение',[`<button class=\"drawer-item drawer-learn\" onclick=\"closeDrawer();guardedAction(initStudy)\">📖 <span>Изучить тесты</span></button>`,`<button class=\"drawer-item drawer-star\" onclick=\"closeDrawer();guardedAction(showFavorites)\">⭐ <span>Избранные вопросы</span></button>`,`<button class=\"drawer-item drawer-error\" onclick=\"closeDrawer();guardedAction(()=>showMistakeList())\">❗ <span>Изучить ошибки</span></button>`])+\n      makeDrawerSection('Результаты',[`<button class=\"drawer-item drawer-history\" onclick=\"closeDrawer();guardedAction(showHistory)\">🕘 <span>История результатов</span></button>`])+\n      makeDrawerSection('Подписка',[`<button id=\"activate-sub-drawer\" class=\"drawer-item drawer-premium\" onclick=\"closeDrawer();openSubscriptionModal()\">👑 <span>Получить подписку</span></button>`])+\n      makeDrawerSection('Помощь',[`<button id=\"offer-drawer-btn\" class=\"drawer-item drawer-rules\" onclick=\"openOfferModal()\">📄 <span>Оферта и правила</span></button>`,`<a class=\"drawer-item drawer-admin\" href=\"${ADMIN_URL}\" target=\"_blank\" onclick=\"closeDrawer()\">💬 <span>Написать @${ADMIN}</span></a>`]);\n  }\n  function ensureOfferModal(){\n    let modal=$('#offer-modal');if(modal)return modal;\n    modal=document.createElement('div');modal.id='offer-modal';modal.className='offer-modal hidden';\n    modal.innerHTML=`<div class=\"offer-box\" role=\"dialog\" aria-modal=\"true\"><div class=\"offer-head\"><div class=\"offer-title\">📄 Оферта и правила</div><button type=\"button\" class=\"offer-close\" onclick=\"closeOfferModal()\">×</button></div><div class=\"offer-body\"><div class=\"offer-card\"><b>1. Доступ</b> Подписка активируется только администратором через Termux: доступ добавляется только в закрытом backend.</div><div class=\"offer-card\"><b>2. Устройство</b> Доступ может быть привязан к одному устройству. Передавать аккаунт другому человеку запрещено.</div><div class=\"offer-card\"><b>3. Лимит</b> Без премиума доступно ${LIMIT} теста за 24 часа. Премиум снимает лимит.</div><div class=\"offer-card\"><b>4. Администратор</b> По вопросам подписки пишите <a href=\"${ADMIN_URL}\" target=\"_blank\">@${ADMIN}</a>.</div><div class=\"offer-card\"><b>5. Активность QuizBot.</b> Для панели управления сохраняются Telegram ID, имя, username, время открытия и последнего использования этого мини-приложения. Данные из Telegram о присутствии в сети не собираются.</div></div></div>`;\n    modal.addEventListener('click',e=>{if(e.target===modal)window.closeOfferModal();});document.body.appendChild(modal);return modal;\n  }\n  window.openOfferModal=function(){ensureOfferModal().classList.remove('hidden');try{closeDrawer()}catch(e){}};\n  window.closeOfferModal=function(){$('#offer-modal')?.classList.add('hidden')};\n\n  function patchScreenHooks(){\n    if(window.__ecoStableHooks)return;window.__ecoStableHooks=true;\n    const oldShow=window.showScreen;\n    if(typeof oldShow==='function')window.showScreen=function(id){const r=oldShow.apply(this,arguments);document.body.classList.toggle('inner-section-open',id!=='start-screen');requestAnimationFrame(syncRealBar);if(id==='start-screen')setTimeout(renderLimit,0);return r};\n    const oldFinish=window.finishTest;\n    if(typeof oldFinish==='function')window.finishTest=function(){return oldFinish.apply(this,arguments)};\n    const oldFinishReal=window.finishRealExam;\n    if(typeof oldFinishReal==='function')window.finishRealExam=function(){const r=oldFinishReal.apply(this,arguments);requestAnimationFrame(syncRealBar);return r};\n    const oldRenderReal=window.renderRealExam;\n    if(typeof oldRenderReal==='function')window.renderRealExam=function(){const r=oldRenderReal.apply(this,arguments);requestAnimationFrame(syncRealBar);return r};\n    const oldSelectReal=window.selectRealAnswer;\n    if(typeof oldSelectReal==='function')window.selectRealAnswer=function(qi,oi){\n      if(window.realExamFinished)return;\n      // For reliability keep original render, but delay visual sync to one frame.\n      const r=oldSelectReal.apply(this,arguments);requestAnimationFrame(syncRealBar);return r;\n    };\n  }\n  function ensureRealBar(){\n    let bar=$('#real-fixed-top');if(bar)return bar;\n    bar=document.createElement('div');bar.id='real-fixed-top';bar.className='hidden';\n    bar.innerHTML='<div class=\"real-fixed-row\"><div><div class=\"real-fixed-title\">Реальный тест</div><div id=\"real-fixed-time\" class=\"real-fixed-time\">30:00</div></div><button type=\"button\" id=\"real-fixed-finish\" class=\"btn btn-green real-fixed-finish\">Завершить</button></div><div class=\"real-fixed-line\"><div id=\"real-fixed-fill\" class=\"real-fixed-fill\"></div></div>';\n    document.body.appendChild(bar);\n    $('#real-fixed-finish',bar).onclick=()=>{const finish=$('#real-finish-btn'),back=$('#real-back-btn');if(finish&&!finish.classList.contains('hidden'))finish.click();else if(back&&!back.classList.contains('hidden'))back.click();};\n    return bar;\n  }\n  function syncRealBar(){\n    const bar=ensureRealBar();const screen=$('#real-exam-screen');const active=!!(screen&&!screen.classList.contains('hidden'));\n    bar.classList.toggle('hidden',!active);document.body.classList.toggle('real-exam-fixed-on',active);if(!active)return;\n    const t=$('#real-fixed-time');if(t)t.textContent=$('#real-timer')?.textContent||'30:00';\n    const f=$('#real-fixed-fill');if(f)f.style.width=$('#real-line-fill')?.style?.width||'100%';\n    const finish=$('#real-finish-btn'),back=$('#real-back-btn'),btn=$('#real-fixed-finish');\n    if(btn){const done=finish&&finish.classList.contains('hidden')&&back&&!back.classList.contains('hidden');btn.textContent=done?'В меню':'Завершить';btn.classList.toggle('btn-primary',done);btn.classList.toggle('btn-green',!done);}\n  }\n\n  function patchRealExamTimerLive(){\n    const oldStart=window.startRealExamTimer;\n    if(typeof oldStart!=='function'||oldStart.__livePatched)return;\n    window.startRealExamTimer=function(){\n      clearInterval(window.realExamTimer);\n      const tick=()=>{\n        if(window.realExamFinished){clearInterval(window.realExamTimer);return}\n        const left=Number(window.realExamTimeLeft||0);\n        const total=Number(window.realExamTotalSeconds||1800);\n        const m=Math.floor(left/60),s=left%60;\n        const txt=`${m}:${s<10?'0'+s:s}`;\n        const rt=$('#real-timer');if(rt)rt.textContent=txt;\n        const pct=Math.max(0,left/total*100);\n        const line=$('#real-line-fill');if(line)line.style.width=pct+'%';\n        const ft=$('#real-fixed-time');if(ft)ft.textContent=txt;\n        const ff=$('#real-fixed-fill');if(ff)ff.style.width=pct+'%';\n        if(left<=0){window.finishRealExam(true);return}\n        window.realExamTimeLeft=left-1;\n      };\n      tick();\n      window.realExamTimer=setInterval(tick,1000);\n    };\n    window.startRealExamTimer.__livePatched=true;\n  }\n\n  function patchSearch(){\n    if(window.__ecoSearchStable)return;window.__ecoSearchStable=true;\n    const oldFilter=window.filterList;\n    let timer=null;\n    if(typeof oldFilter==='function')window.filterList=function(){clearTimeout(timer);timer=setTimeout(()=>oldFilter(),180)};\n  }\n  function boot(){\n    ensureOfferModal();improveDrawer();patchScreenHooks();patchSearch();renderLimit();\n    window.refreshPremiumBadge();\n    [80,300,900].forEach(t=>setTimeout(()=>{improveDrawer();renderLimit();syncRealBar()},t));\n    window.addEventListener('storage',e=>{if(e.key===USAGE_KEY)renderLimit()});\n    window.addEventListener('resize',()=>requestAnimationFrame(syncRealBar),{passive:true});\n  }\n  ready(boot);\n})();\n","/eco-upgrade.css":"/* Economy Pro UI/UX Upgrade — keeps all old functions */\n:root{\n  --radius-xl:28px;\n  --radius-lg:22px;\n  --radius-md:18px;\n  --glass:rgba(255,255,255,.82);\n  --glass-dark:rgba(15,23,42,.78);\n}\nhtml{scroll-behavior:smooth;background:#0f172a;}\nbody{\n  padding:calc(12px + env(safe-area-inset-top,0px)) 10px calc(26px + env(safe-area-inset-bottom,0px))!important;\n  background:\n    radial-gradient(circle at 12% -8%,rgba(59,130,246,.34),transparent 32%),\n    radial-gradient(circle at 100% 12%,rgba(168,85,247,.28),transparent 34%),\n    radial-gradient(circle at 50% 100%,rgba(14,165,233,.16),transparent 34%),\n    linear-gradient(160deg,#eef2ff 0%,#dbeafe 48%,#ede9fe 100%)!important;\n}\nbody:not(.light){\n  background:\n    radial-gradient(circle at 12% -8%,rgba(37,99,235,.30),transparent 32%),\n    radial-gradient(circle at 100% 12%,rgba(124,58,237,.25),transparent 34%),\n    radial-gradient(circle at 50% 100%,rgba(14,165,233,.12),transparent 34%),\n    linear-gradient(160deg,#020617 0%,#0f172a 58%,#111827 100%)!important;\n}\n.app{max-width:560px!important;}\n.topbar{position:sticky;top:calc(6px + env(safe-area-inset-top,0px));z-index:80;margin-bottom:10px!important;}\n.menu-toggle,.icon-btn,.card,.panel,.setting-card,.side-drawer,.drawer-item,.paybox,.pay-card,.option,.item,.review-item,.real-question-card,.real-result-box,.loading-screen .loader-card{\n  border-radius:var(--radius-lg)!important;\n}\n.menu-toggle,.icon-btn{backdrop-filter:blur(14px);}\n.card{\n  border-radius:var(--radius-xl)!important;\n  overflow:hidden;\n  box-shadow:0 22px 55px rgba(15,23,42,.16)!important;\n}\nbody:not(.light) .card{box-shadow:0 22px 55px rgba(0,0,0,.36)!important;}\n.title{font-size:26px!important;letter-spacing:-.5px;}\n.welcome-subject{font-size:18px!important;color:#4f46e5;}\nbody:not(.light) .welcome-subject{color:#93c5fd;}\n.mode-tabs,.seg,.settings-grid{gap:9px!important;}\n.mode-tab,.seg button,.quick button,.simple-input,.search,.study-toggle,.btn{border-radius:18px!important;}\n.mode-tab.active,.seg button.active,.quick button.active,.menu-main-btn,.btn-primary{\n  box-shadow:0 13px 28px rgba(79,70,229,.24)!important;\n}\n.menu-main-btn{min-height:56px!important;font-size:17px!important;}\n.progress-card{display:none!important;border-radius:20px!important;}\n.progress-bar{height:10px!important;}\n.upgrade-dashboard{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0 8px;}\n.upgrade-stat{border:1px solid rgba(148,163,184,.35);background:rgba(255,255,255,.58);border-radius:20px;padding:10px 7px;text-align:center;min-height:70px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;}\nbody:not(.light) .upgrade-stat{background:rgba(15,23,42,.42);border-color:rgba(71,85,105,.55);}\n.upgrade-stat b{font-size:18px;line-height:1;color:var(--txt);}\n.upgrade-stat span{font-size:10.5px;font-weight:1000;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;}\n.upgrade-coach{margin:9px 0 5px;padding:12px;border:1px solid rgba(99,102,241,.24);background:linear-gradient(135deg,rgba(99,102,241,.10),rgba(14,165,233,.10));border-radius:22px;font-size:13px;font-weight:900;color:var(--txt);line-height:1.35;}\n.upgrade-quick{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0 2px;}\n.upgrade-quick .btn{min-height:44px;font-size:13px;}\n.q-map{display:grid;grid-template-columns:repeat(10,1fr);gap:5px;margin:10px 0 12px;}\n.q-dot{border:1px solid var(--line);background:var(--card2);color:var(--muted);border-radius:999px;height:24px;font-size:11px;font-weight:1000;display:flex;align-items:center;justify-content:center;cursor:pointer;padding:0;}\n.q-dot.current{background:linear-gradient(135deg,#6366f1,#0ea5e9);color:white;border-color:transparent;}\n.q-dot.done{color:#16a34a;border-color:rgba(22,163,74,.45);}\n.q-dot.wrongish{color:#f97316;border-color:rgba(249,115,22,.45);}\n.question{font-size:19px!important;letter-spacing:-.15px;}\n.option{border-radius:21px!important;padding:14px 14px!important;}\n.option:hover{transform:translateY(-1px);}\n.question-actions{gap:8px!important;}\n/* Stable list header: no fixed left/transform jump while scrolling */\n#list-screen{width:100%!important;padding:0!important;overflow:visible!important;}\n.sticky-list-head{\n  position:sticky!important;\n  top:calc(8px + env(safe-area-inset-top,0px))!important;\n  left:auto!important;\n  transform:none!important;\n  width:100%!important;\n  max-width:100%!important;\n  z-index:75!important;\n  border-radius:26px!important;\n  padding:13px!important;\n  margin:0 0 14px!important;\n  background:rgba(255,255,255,.92)!important;\n  border:1px solid rgba(226,232,240,.9)!important;\n  box-shadow:0 14px 34px rgba(15,23,42,.14)!important;\n  backdrop-filter:blur(16px)!important;\n}\nbody:not(.light) .sticky-list-head{background:rgba(15,23,42,.92)!important;border-color:rgba(71,85,105,.65)!important;}\n.list-title-row{display:grid!important;grid-template-columns:1fr auto!important;align-items:center!important;gap:10px!important;margin:0 0 10px!important;}\n.list-title-row h2{text-align:left!important;min-width:0!important;}\n.list-title-row .btn{min-width:88px!important;margin:0!important;border-radius:18px!important;}\n.search{height:46px!important;margin:0!important;}\n.study-toggle{margin-top:8px!important;padding:10px 12px!important;background:rgba(99,102,241,.08);border:1px solid rgba(99,102,241,.18);display:flex!important;align-items:center;gap:8px;font-size:13px;font-weight:1000;}\n.study-toggle.hidden{display:none!important;}\n.search-tools{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;margin-top:8px;}\n.search-counter{font-size:12px;font-weight:1000;color:var(--muted);}\n.clear-search{min-height:34px;border-radius:14px;border:1px solid var(--line);background:var(--card2);color:var(--txt);font-size:12px;font-weight:1000;padding:6px 10px;}\n.item{border-radius:25px!important;margin-bottom:9px!important;}\n.drawer-stats{grid-template-columns:1fr 1fr!important;}\n.drawer-list{gap:9px!important;}\n.drawer-item:hover,.btn:hover,.mode-tab:hover,.seg button:hover,.quick button:hover{transform:translateY(-1px);}\n.toast-upgrade{position:fixed;left:50%;bottom:calc(18px + env(safe-area-inset-bottom,0px));transform:translateX(-50%) translateY(120%);background:rgba(15,23,42,.92);color:white;border:1px solid rgba(255,255,255,.16);box-shadow:0 18px 40px rgba(0,0,0,.22);border-radius:999px;padding:11px 16px;font-size:13px;font-weight:1000;z-index:10000;opacity:0;transition:.22s;pointer-events:none;max-width:calc(100% - 24px);text-align:center;}\n.toast-upgrade.show{opacity:1;transform:translateX(-50%) translateY(0);}\n.scroll-top-upgrade{position:fixed;right:14px;bottom:calc(16px + env(safe-area-inset-bottom,0px));width:46px;height:46px;border-radius:999px!important;border:1px solid rgba(255,255,255,.25);background:linear-gradient(135deg,#6366f1,#0ea5e9);color:white;box-shadow:0 16px 34px rgba(37,99,235,.26);z-index:79;display:none;align-items:center;justify-content:center;font-weight:1000;}\n.scroll-top-upgrade.show{display:flex;}\n@media(max-width:430px){\n  body{padding-left:8px!important;padding-right:8px!important;}\n  .upgrade-dashboard{grid-template-columns:repeat(2,1fr);}\n  .upgrade-stat{min-height:62px;}\n  .upgrade-quick{grid-template-columns:1fr;}\n  .q-map{grid-template-columns:repeat(8,1fr);}\n  .title{font-size:24px!important;}\n  .question{font-size:18px!important;}\n  .sticky-list-head{border-radius:23px!important;padding:12px!important;top:calc(6px + env(safe-area-inset-top,0px))!important;}\n}\n@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important;}}\n\n/* Cleaner main menu */\n#start-screen .center{margin-bottom:10px!important;}\n#start-screen .title{font-size:24px!important;margin-bottom:2px!important;}\n#start-screen .welcome-subject{font-size:16px!important;}\n.settings-collapse{margin-top:9px;border:1px solid rgba(148,163,184,.28);background:rgba(255,255,255,.42);border-radius:22px;overflow:hidden;}\nbody:not(.light) .settings-collapse{background:rgba(15,23,42,.32);border-color:rgba(71,85,105,.55);}\n.settings-collapse summary{list-style:none;cursor:pointer;padding:13px 14px;font-weight:1000;color:var(--txt);display:flex;align-items:center;justify-content:space-between;gap:8px;}\n.settings-collapse summary::-webkit-details-marker{display:none;}\n.settings-collapse summary span{font-size:11px;color:var(--muted);font-weight:900;}\n.settings-collapse .settings-grid{padding:0 10px 10px!important;}\n.simple-start-hint{margin:10px 0 0;text-align:center;font-size:12px;font-weight:900;color:var(--muted);}\n.upgrade-dashboard,.upgrade-coach,.upgrade-quick{display:none!important;}\n","/eco-upgrade.js":"(function(){\n  'use strict';\n  const $=(s,r=document)=>r.querySelector(s);\n  const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));\n  const safeCall=(fn,fallback)=>{try{return fn()}catch(e){return fallback}};\n  let toastTimer=null;\n\n  function toast(msg){\n    let el=$('#upgrade-toast');\n    if(!el){el=document.createElement('div');el.id='upgrade-toast';el.className='toast-upgrade';document.body.appendChild(el)}\n    el.textContent=msg;\n    el.classList.add('show');\n    clearTimeout(toastTimer);\n    toastTimer=setTimeout(()=>el.classList.remove('show'),1800);\n  }\n  window.ecoToast=toast;\n\n  function percent(n,d){return d?Math.round(n*100/d):0}\n  function refreshDashboard(){\n    // Главное меню должно быть лёгким: статистику оставляем в боковом меню,\n    // а старые перегруженные блоки, если они уже были добавлены, убираем.\n    ['#upgrade-dashboard','#upgrade-coach','#upgrade-quick'].forEach(sel=>$(sel)?.remove());\n  }\n\n  function simplifyMainMenu(){\n    // Disabled in final build: settings must stay visible and must not appear/disappear on load.\n    document.querySelector('#settings-collapse')?.remove?.();\n    document.querySelector('#simple-start-hint')?.remove?.();\n  }\n\n  window.ecoQuickStart=function(type){\n    const select=$('#count-select');\n    if(!select)return;\n    select.value=type;\n    const custom=$('#count-custom'); if(custom) custom.value='';\n    const rangeFrom=$('#range-from'), rangeTo=$('#range-to');\n    if(rangeFrom)rangeFrom.value=''; if(rangeTo)rangeTo.value='';\n    setRunMode('normal');\n    setOrderMode('random');\n    guardedStart();\n  };\n\n  function addDrawerExtras(){\n    const list=$('.drawer-list');\n    if(!list || $('#upgrade-drawer-extra'))return;\n    const wrap=document.createElement('div');\n    wrap.id='upgrade-drawer-extra';\n    wrap.style.display='grid';\n    wrap.style.gap='9px';\n    wrap.innerHTML=`\n      <button class=\"drawer-item\" onclick=\"closeDrawer();ecoQuickStart('mistakes')\">🎯 Быстрый тест по ошибкам</button>\n      <button class=\"drawer-item\" onclick=\"closeDrawer();ecoResetFilters()\">🧹 Сбросить настройки теста</button>`;\n    list.appendChild(wrap);\n  }\n\n  window.ecoResetFilters=function(){\n    safeCall(()=>setRunMode('normal'));\n    safeCall(()=>setOrderMode('random'));\n    const ids=['time-custom','count-custom','range-from','range-to'];\n    ids.forEach(id=>{const el=$('#'+id); if(el)el.value=''});\n    const cs=$('#count-select');\n    if(cs)cs.value='all';\n    safeCall(()=>onTimeSelectChange());\n    toast('Настройки теста сброшены');\n  };\n\n  function renderQuestionMap(){\n    // Disabled in final build: do not show the full list/map of questions during solving.\n    document.querySelector('#q-map')?.remove?.();\n  }\n\n  function enhanceSearchHead(){\n    const head=$('.sticky-list-head');\n    if(!head || $('#search-tools'))return;\n    const tools=document.createElement('div');\n    tools.id='search-tools';tools.className='search-tools';\n    tools.innerHTML='<div id=\"search-counter\" class=\"search-counter\">Готово</div><button type=\"button\" class=\"clear-search\" onclick=\"ecoClearSearch()\">Очистить</button>';\n    const toggle=$('#study-options-row');\n    if(toggle)toggle.insertAdjacentElement('afterend',tools); else head.appendChild(tools);\n  }\n  window.ecoClearSearch=function(){const s=$('#search-box'); if(s){s.value=''; filterList(); s.focus();}};\n  function updateSearchCounter(n){const c=$('#search-counter'); if(c)c.textContent=typeof n==='number'?`Найдено: ${n}`:'Готово';}\n\n  function addScrollTop(){\n    if($('#scroll-top-upgrade'))return;\n    const b=document.createElement('button');\n    b.id='scroll-top-upgrade';b.className='scroll-top-upgrade';b.type='button';b.textContent='↑';\n    b.onclick=()=>window.scrollTo({top:0,behavior:'smooth'});\n    document.body.appendChild(b);\n    window.addEventListener('scroll',()=>b.classList.toggle('show',window.scrollY>450),{passive:true});\n  }\n\n  function bindHotkeys(){\n    if(window.__ecoHotkeys)return; window.__ecoHotkeys=true;\n    document.addEventListener('keydown',e=>{\n      const tag=(e.target&&e.target.tagName||'').toLowerCase();\n      if(['input','textarea','select'].includes(tag))return;\n      if(!$('#test-screen') || $('#test-screen').classList.contains('hidden'))return;\n      if(e.key>='1'&&e.key<='9'){\n        const idx=Number(e.key)-1;\n        const opts=$$('#options .option');\n        if(opts[idx]){opts[idx].click();toast('Выбран вариант '+e.key)}\n      }else if(e.key==='Enter'){\n        const btn=$('#accept-btn'); if(btn && !btn.classList.contains('hidden'))btn.click();\n      }else if(e.key==='ArrowRight'){\n        const btn=$('#next-btn'); if(btn && !btn.classList.contains('hidden'))btn.click();\n      }else if(e.key==='ArrowLeft'){\n        const btn=$('#prev-btn'); if(btn && !btn.classList.contains('hidden'))btn.click();\n      }\n    });\n  }\n\n  function monkeyPatch(){\n    if(window.__ecoPatched)return; window.__ecoPatched=true;\n    const oldRender=renderQuestion;\n    renderQuestion=function(){oldRender.apply(this,arguments);renderQuestionMap();};\n    const oldUpdate=updateProgressUI;\n    updateProgressUI=function(){oldUpdate.apply(this,arguments);refreshDashboard();};\n    const oldShowList=showListScreen;\n    showListScreen=function(title,data,withSearch){oldShowList.apply(this,arguments);enhanceSearchHead();updateSearchCounter(Array.isArray(data)?data.length:0);};\n    const oldRenderList=renderDataList;\n    renderDataList=function(data){oldRenderList.apply(this,arguments);enhanceSearchHead();updateSearchCounter(Array.isArray(data)?data.length:0);};\n    const oldCopyCard=copyCard;\n    copyCard=function(){oldCopyCard.apply(this,arguments);toast('Номер карты скопирован');};\n    const oldCopyUser=copyUserId;\n    copyUserId=function(){oldCopyUser.apply(this,arguments);toast('Telegram ID скопирован');};\n  }\n\n  function boot(){\n    safeCall(monkeyPatch);\n    simplifyMainMenu();\n    addDrawerExtras();\n    addScrollTop();\n    bindHotkeys();\n    refreshDashboard();\n    setTimeout(()=>{simplifyMainMenu();refreshDashboard();},800);\n    setTimeout(()=>{simplifyMainMenu();refreshDashboard();},1800);\n  }\n  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot); else boot();\n})();\n","/env.js":"// env.js\n// Netlify version: backend is on the same site via /api/* redirects.\nwindow.__APP_ENV = {\n  BACKEND_URL: \"\"\n};\n","/index.html":"<!DOCTYPE html>\n<html lang=\"ru\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no\"/>\n  <title>Economy Pro · Макроэкономика</title>\n  <script src=\"https://telegram.org/js/telegram-web-app.js\" async></script>\n  <script src=\"./env.js?v=300260619-3\"></script>\n  <script src=\"./tele-secure.js?v=16\"></script>\n  <style>\n    :root{--bg:#07111f;--bg2:#0d1728;--card:#111c2e;--card2:#0b1424;--line:#26374f;--txt:#f8fafc;--muted:#9aaac0;--blue:#2563eb;--cyan:#38bdf8;--green:#16a34a;--red:#dc2626;--amber:#f59e0b;--purple:#8b5cf6;--shadow:0 18px 48px rgba(0,0,0,.34);--r:18px}\n    body.light{--bg:#f3f6fb;--bg2:#ffffff;--card:#ffffff;--card2:#f8fafc;--line:#d9e2ee;--txt:#0f172a;--muted:#64748b;--shadow:0 16px 40px rgba(15,23,42,.10)}\n    *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\n    html,body{margin:0;min-height:100%;font-family:Inter,\"Segoe UI\",Roboto,Arial,sans-serif;color:var(--txt);background:radial-gradient(circle at 10% 0%,rgba(99,102,241,.20),transparent 28%),radial-gradient(circle at 100% 100%,rgba(168,85,247,.18),transparent 30%),linear-gradient(180deg,#8190ee,#885dc8);transition:background .25s,color .25s}\n    body{padding:14px 10px 24px}\n    button,input,select{font:inherit}\n    .hidden{display:none!important}\n    .app{width:100%;max-width:520px;margin:0 auto}\n    /* Topbar */\n    .topbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 4px 8px}\n    .menu-toggle{width:50px;height:50px;border-radius:16px;border:1px solid rgba(255,255,255,.38);background:rgba(255,255,255,.88);color:#1f2937;font-size:27px;font-weight:1000;cursor:pointer;box-shadow:0 10px 24px rgba(17,24,39,.16)}\n    .chip{display:inline-flex;align-items:center;justify-content:center;border:1px solid var(--line);background:rgba(255,255,255,.18);color:#fff;border-radius:999px;min-height:34px;padding:7px 12px;font-size:13px;font-weight:1000;backdrop-filter:blur(10px)}\n    .subject-switch-wrap{position:relative;min-width:135px;max-width:210px;flex:0 1 210px}\n    .subject-select{width:100%;height:50px;border:1px solid rgba(255,255,255,.30);background:rgba(15,23,42,.50);color:#fff;border-radius:999px;padding:0 34px 0 16px;font-size:14px;font-weight:1000;outline:0;appearance:none;-webkit-appearance:none;box-shadow:0 10px 24px rgba(17,24,39,.14);backdrop-filter:blur(10px)}\n    .subject-switch-wrap:after{content:'⌄';position:absolute;right:14px;top:50%;transform:translateY(-55%);font-size:21px;font-weight:1000;color:#fff;pointer-events:none;opacity:.92}\n    body.light .subject-select{background:rgba(255,255,255,.88);color:#111827;border-color:rgba(226,232,240,.85)}\n    body.light .subject-switch-wrap:after{color:#64748b}\n    .icon-btn{border:1px solid rgba(255,255,255,.28);background:rgba(15,23,42,.55);color:#fff;border-radius:15px;min-width:44px;min-height:44px;font-weight:1000;cursor:pointer;box-shadow:0 6px 15px rgba(0,0,0,.14)}\n    .top-right{display:flex;align-items:center;gap:8px}\n    /* Premium badge */\n    .premium-badge{display:inline-flex;align-items:center;justify-content:center;gap:4px;min-height:27px;max-width:92px;padding:4px 8px;border-radius:999px;background:linear-gradient(135deg,#fbbf24,#f59e0b);color:#111827;font-size:11px;font-weight:900;box-shadow:0 4px 12px rgba(245,158,11,.18);white-space:nowrap;letter-spacing:.15px;flex-shrink:0}\n    .premium-badge::before{content:\"💎\";font-size:12px;line-height:1}\n    .premium-badge.ordinary{background:#334155;color:#f1f5f9;box-shadow:none;border:1px solid rgba(203,213,225,.22)}\n    .premium-badge.ordinary::before{content:\"○\";font-size:11px}\n    @media(max-width:420px){.premium-badge{font-size:10px;min-width:0;padding:4px 7px;gap:3px}.premium-badge::before{font-size:11px}}\n    /* Card */\n    .card{background:rgba(255,255,255,.95);border:1px solid rgba(226,232,240,.9);border-radius:24px;box-shadow:0 16px 42px rgba(31,41,55,.14);padding:14px;width:100%;transition:.25s}\n    .light .card{background:rgba(255,255,255,.96)}\n    body:not(.light) .card{background:rgba(17,24,39,.92);border-color:rgba(71,85,105,.55)}\n    .center{text-align:center}\n    .title{font-size:23px;line-height:1.02;font-weight:1000;margin:2px 0 3px}\n    .muted{color:var(--muted)}\n    .profile-link{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;color:#38bdf8;background:rgba(56,189,248,.10);border:1px solid rgba(56,189,248,.32);border-radius:999px;padding:6px 12px;font-size:12px;font-weight:1000;letter-spacing:1px;text-transform:uppercase;margin-bottom:4px}\n    .welcome-subject{font-size:17px;font-weight:1000;margin-top:4px;margin-bottom:4px}\n    .user-badge{margin-top:6px;color:var(--muted);font-size:12px;font-weight:900}\n    .limit-badge-main{display:inline-flex;align-items:center;justify-content:center;margin-top:8px;padding:8px 13px;border-radius:999px;background:rgba(99,102,241,.10);border:1px solid rgba(129,140,248,.30);color:var(--txt);font-size:13px;font-weight:1000}\n    body:not(.light) .limit-badge-main{background:rgba(99,102,241,.16);border-color:rgba(129,140,248,.34);color:#f8fafc}\n\n    /* Stats row */\n    .stats-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0 4px}\n    .stat-pill{display:flex;align-items:center;justify-content:center;gap:7px;min-height:42px;padding:7px 10px;background:#f3f1ff;border:1px solid #ddd6fe;border-radius:999px;font-weight:1000;color:#4338ca;font-size:14px}\n    body:not(.light) .stat-pill{background:rgba(67,56,202,.18);border-color:rgba(129,140,248,.35);color:#c7d2fe}\n    /* Progress */\n    .progress-card{margin:10px 0;background:rgba(243,244,246,.88);border:1px solid rgba(203,213,225,.75);border-radius:16px;padding:10px}\n    body:not(.light) .progress-card{background:rgba(30,41,59,.84);border-color:rgba(71,85,105,.5)}\n    .progress-top{display:flex;justify-content:space-between;gap:10px;font-weight:1000;font-size:12.5px}\n    .progress-bar{height:8px;background:rgba(100,116,139,.22);border-radius:999px;overflow:hidden;margin-top:8px}\n    .progress-fill{height:100%;width:0;background:linear-gradient(90deg,#2563eb,#38bdf8);border-radius:999px;transition:width .35s}\n    /* Resume */\n    .panel{background:var(--card2);border:1px solid var(--line);border-radius:15px;padding:10px}\n    .panel.full{grid-column:span 2}\n    .resume{border-color:rgba(56,189,248,.55);background:linear-gradient(135deg,rgba(14,165,233,.14),rgba(37,99,235,.08));margin:10px 0}\n    .resume-title{font-weight:1000;font-size:16px;margin-bottom:4px}\n    .resume-text{font-size:13px;color:var(--muted);font-weight:800;line-height:1.35}\n    .quick{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}\n    .quick.two{grid-template-columns:1fr 1fr}\n    .quick button,.seg button{border:1px solid var(--line);background:var(--card);color:var(--txt);border-radius:12px;min-height:34px;padding:7px;font-size:12.5px;font-weight:1000;cursor:pointer;transition:.18s}\n    .quick button.active,.seg button.active{background:linear-gradient(135deg,#2563eb,#0ea5e9);border-color:transparent;color:white}\n    /* Config */\n    .simple-config{margin-top:6px}\n    .mode-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-bottom:8px}\n    .mode-tab{border:1px solid rgba(203,213,225,.9);background:#f8fafc;color:#6b7280;border-radius:15px;min-height:42px;padding:7px 8px;font-size:13px;font-weight:1000;cursor:pointer;transition:.18s;display:flex;align-items:center;justify-content:center;text-align:center}\n    body:not(.light) .mode-tab{background:rgba(15,23,42,.8);border-color:rgba(71,85,105,.55);color:#cbd5e1}\n    .mode-tab.active{background:linear-gradient(135deg,#6366f1,#7c3aed);border-color:transparent;color:#fff;box-shadow:0 12px 24px rgba(99,102,241,.22)}\n    .seg{display:grid;grid-template-columns:1fr 1fr;gap:6px}\n    .simple-group{margin-top:7px}\n    .settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}\n    .setting-card{display:grid;gap:7px;background:rgba(15,23,42,.04);border:1px solid rgba(203,213,225,.52);border-radius:17px;padding:9px}\n    body:not(.light) .setting-card{background:rgba(15,23,42,.32);border-color:rgba(71,85,105,.44)}\n    .setting-card.disabled-look{opacity:.58;filter:grayscale(.35);background:rgba(148,163,184,.12)!important;border-color:rgba(148,163,184,.35)!important;pointer-events:none}\n    .setting-card.disabled-look .simple-label{color:var(--muted)}\n    .setting-card.disabled-look .simple-input{background:rgba(148,163,184,.15)!important;color:var(--muted)!important;border-color:rgba(148,163,184,.35)!important}\n\n    .range-card{grid-column:1/-1}\n    .range-inputs{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n    .simple-label{font-size:14px;font-weight:1000;text-align:center;margin:8px 0 6px;color:#111827}\n    body:not(.light) .simple-label{color:#f8fafc}\n    .settings-grid .simple-label{margin:0;text-align:center;font-size:13px}\n    .simple-input{width:100%;height:46px;border:1px solid rgba(203,213,225,.9);background:#fff;color:#111827;border-radius:16px;padding:0 12px;font-size:15px;font-weight:900;outline:0}\n    body:not(.light) .simple-input{background:rgba(15,23,42,.88);border-color:rgba(71,85,105,.55);color:#f8fafc}\n    .simple-input::placeholder{color:var(--muted)}\n    .settings-grid .simple-input{height:43px;font-size:14px;border-radius:14px}\n    .select-wrap{position:relative}\n    .select-wrap:after{content:'⌄';position:absolute;right:15px;top:50%;transform:translateY(-53%);font-size:20px;font-weight:1000;color:var(--muted);pointer-events:none}\n    .simple-select{-webkit-appearance:none;appearance:none;padding-right:40px}\n    .mini-note{margin-top:8px;text-align:center;font-size:12px;font-weight:900;color:var(--muted)}\n    .compact-total{margin:6px 0 0;text-align:center;font-size:12px}\n    .menu-main-btn{margin-top:8px;min-height:52px;border-radius:18px;font-size:16px;background:linear-gradient(135deg,#6366f1,#5b63f0)}\n    .config-error{background:rgba(220,38,38,.12);border:1px solid rgba(248,113,113,.45);color:#fecaca;border-radius:13px;padding:10px 12px;font-weight:1000;line-height:1.35;text-align:center;margin:9px 0 0}\n    .light .config-error{color:#991b1b}\n    .disabled-look{opacity:.55}\n    /* Buttons */\n    .row{display:flex;gap:8px;align-items:center}\n    .btn{border:0;border-radius:14px;min-height:48px;padding:11px;color:white;font-weight:1000;font-size:14px;display:flex;align-items:center;justify-content:center;gap:7px;cursor:pointer;transition:transform .15s,filter .18s,opacity .18s}\n    .btn:hover{filter:brightness(1.04)}.btn:active{transform:scale(.97)}\n    .btn-full{grid-column:span 2;width:100%}\n    .btn-primary{background:linear-gradient(135deg,#2563eb,#1d4ed8)}\n    .btn-gray{background:#334155;color:#e2e8f0}\n    .btn-cyan{background:linear-gradient(135deg,#0284c7,#0ea5e9)}\n    .btn-amber{background:linear-gradient(135deg,#d97706,#f59e0b)}\n    .btn-green{background:linear-gradient(135deg,#159947,#16a34a)}\n    #accept-btn{margin-top:14px;margin-bottom:16px;min-height:58px;box-shadow:0 12px 24px rgba(22,163,74,.22)}\n    .question-actions .btn{min-height:54px}\n    .question-actions.one .btn,.question-actions.two .btn{border-radius:18px}\n    .btn-purple{background:linear-gradient(135deg,#7c3aed,#a855f7)}\n    .btn-red{background:linear-gradient(135deg,#b91c1c,#ef4444)}\n    .btn-small{min-height:39px;padding:9px 11px;border-radius:12px;font-size:13px}\n    .soft-btn{background:var(--card);border:1px solid var(--line);color:var(--txt)}\n    /* Paywall */\n    .paywall{position:fixed;inset:0;z-index:99999;background:radial-gradient(circle at top,rgba(56,189,248,.22),transparent 38%),rgba(2,6,23,.94);backdrop-filter:blur(10px);display:flex;align-items:flex-start;justify-content:center;overflow-y:auto;padding:max(14px,env(safe-area-inset-top)) 14px max(80px,env(safe-area-inset-bottom))}\n    .paybox{width:100%;max-width:440px;background:#0f172a;border:1px solid rgba(148,163,184,.28);border-radius:22px;box-shadow:0 25px 70px rgba(0,0,0,.65);padding:17px;margin:auto 0;color:#f8fafc;position:relative}\n    .pay-close{position:absolute;right:12px;top:12px;width:42px;height:42px;border-radius:14px;border:1px solid rgba(148,163,184,.32);background:rgba(15,23,42,.72);color:#f8fafc;font-size:22px;font-weight:1000;cursor:pointer}\n    .pay-icon{width:52px;height:52px;margin:0 auto 9px;border-radius:18px;background:linear-gradient(135deg,#2563eb,#38bdf8);display:flex;align-items:center;justify-content:center;font-size:28px}\n    .pay-title{text-align:center;font-size:21px;font-weight:1000;margin-bottom:6px}\n    .pay-sub{text-align:center;color:#a7b2c5;line-height:1.35;margin:0 0 11px;font-weight:800}\n    .pay-card{background:#0f172a;border:1px solid #334155;border-radius:14px;padding:11px;margin-bottom:8px}\n    .pay-label{color:#94a3b8;text-transform:uppercase;letter-spacing:1.4px;font-size:10px;font-weight:1000;margin-bottom:6px}\n    .pay-value{color:white;font-size:16px;font-weight:1000;word-break:break-all}\n    .pay-card-payment{border-color:rgba(251,191,36,.55);background:linear-gradient(180deg,rgba(251,191,36,.10),rgba(15,23,42,.98))}\n    .pay-price-box{border:1px solid rgba(251,191,36,.55);background:rgba(251,191,36,.12);border-radius:16px;padding:13px 10px;text-align:center;margin:7px 0 10px;box-shadow:0 10px 30px rgba(251,191,36,.10)}\n    .pay-price-title{font-size:13px;font-weight:1000;color:#fde68a;text-transform:uppercase;letter-spacing:.8px;margin-bottom:4px}\n    .pay-price{font-size:32px;line-height:1.05;font-weight:1000;color:#fff7ed;text-shadow:0 0 18px rgba(251,191,36,.35)}\n    .pay-transfer-text{text-align:center;color:#cbd5e1;font-size:15px;font-weight:900;margin:9px 0 7px}\n    .pay-card-number-row{display:flex;gap:8px;align-items:center;background:#020617;border:1px solid rgba(56,189,248,.45);border-radius:15px;padding:10px}\n    .pay-card-number{flex:1;text-align:center;color:#e0f2fe;font-size:22px;line-height:1.15;font-weight:1000;letter-spacing:1.2px;word-break:keep-all}\n    .pay-after-text{text-align:center;color:#cbd5e1;font-size:14px;font-weight:850;line-height:1.35;margin-top:10px}\n    .copy{border:1px solid #334155;background:#1e293b;color:#e2e8f0;border-radius:10px;padding:9px 11px;font-weight:1000;cursor:pointer;font-size:13px}\n    .copy-card{min-width:48px;min-height:44px;font-size:18px;background:linear-gradient(135deg,#0284c7,#2563eb);border-color:rgba(125,211,252,.5)}\n    .pay-input{width:100%;height:49px;border:1px solid #334155;background:#020617;color:#fff;border-radius:13px;outline:0;text-align:center;font-size:15px;font-weight:1000;letter-spacing:1px;margin:4px 0 9px}\n    .pay-input::placeholder{color:#475569}\n    .pay-error{min-height:19px;text-align:center;font-weight:1000;font-size:13px;color:#f87171}\n    .pay-success{min-height:19px;text-align:center;font-weight:1000;font-size:13px;color:#34d399}\n    .paywall.blocked-mode{background:radial-gradient(circle at top,rgba(248,113,113,.25),transparent 38%),rgba(2,6,23,.96)}\n    .paywall.blocked-mode .pay-icon{background:linear-gradient(135deg,#991b1b,#ef4444);box-shadow:0 18px 45px rgba(239,68,68,.22)}\n    .paywall.blocked-mode .pay-title{color:#fee2e2}\n    .paywall.blocked-mode .pay-sub{color:#fecaca;font-size:15px}\n    .paywall.blocked-mode .pay-card-payment{display:none}\n    .blocked-card{border-color:rgba(248,113,113,.55);background:linear-gradient(180deg,rgba(248,113,113,.10),rgba(15,23,42,.98));text-align:center}\n    .blocked-main-text{font-size:16px;line-height:1.45;font-weight:1000;color:#fee2e2;margin-bottom:10px}\n    .blocked-small-text{font-size:13px;line-height:1.4;font-weight:850;color:#cbd5e1;margin-bottom:10px}\n    .danger-note{text-align:center;color:#fbbf24;font-size:12px;font-weight:900;line-height:1.35;margin-top:5px}\n    /* Loading */\n    .loading-screen{position:fixed;inset:0;z-index:999999;display:flex;align-items:center;justify-content:center;background:rgba(2,6,23,.72);backdrop-filter:blur(10px)}\n    .loader-card{width:min(340px,calc(100%-28px));background:var(--card);border:1px solid var(--line);border-radius:22px;padding:22px;text-align:center;box-shadow:var(--shadow)}\n    .spinner{width:42px;height:42px;margin:0 auto 12px;border-radius:999px;border:4px solid rgba(148,163,184,.25);border-top-color:#38bdf8;animation:spin .8s linear infinite}\n    /* Splash */\n    .splash{position:fixed;inset:0;z-index:1000000;background:radial-gradient(circle at 50% 18%,rgba(56,189,248,.32),transparent 34%),linear-gradient(180deg,#101a2e,#020617);display:flex;align-items:center;justify-content:center;transition:.45s opacity,.45s transform}\n    .splash.hide{opacity:0;pointer-events:none;transform:scale(1.03)}\n    .splash-logo{text-align:center;animation:pop .9s ease both}\n    .splash-mark{width:78px;height:78px;margin:0 auto 14px;border-radius:25px;background:linear-gradient(135deg,#2563eb,#38bdf8);display:flex;align-items:center;justify-content:center;font-size:39px;box-shadow:0 20px 55px rgba(37,99,235,.42)}\n    .splash-title{font-size:25px;font-weight:1000;color:white}\n    .splash-sub{margin-top:5px;color:#bfdbfe;font-weight:900}\n    /* Screen */\n    .screen{animation:fadeUp .26s ease both}\n    /* Test screen */\n    .screen-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:11px}\n    .timer{font-size:25px;font-weight:1000;color:var(--cyan);letter-spacing:.5px}\n    .top-actions{display:flex;gap:7px;align-items:center}\n    .q-index{font-size:12.5px;color:var(--muted);font-weight:1000;margin-bottom:8px}\n    .question{font-size:18px;line-height:1.33;font-weight:1000;margin-bottom:13px}\n    .options{display:grid;gap:8px;margin:0 0 11px;padding:0;list-style:none}\n    .option{background:var(--card2);border:1px solid var(--line);border-radius:13px;padding:12px 13px;font-size:15px;line-height:1.33;color:var(--txt);cursor:pointer;transition:.18s}\n    .option.selected{border:2px solid #2563eb;box-shadow:0 0 0 3px rgba(37,99,235,.14)}\n    .option.correct{background:#16a34a;border-color:#15803d;color:#fff}\n    .option.wrong{background:#dc2626;border-color:#b91c1c;color:#fff}\n    .question-actions{display:grid;grid-template-columns:52px 1fr;gap:12px;margin-top:2px}\n    .question-actions.one{grid-template-columns:1fr}\n    .question-actions.two{grid-template-columns:52px 1fr}\n    .question-actions .wide{grid-column:1/-1}\n    .fav-btn,.star{background:var(--card2);border:1px solid var(--line);color:#fbbf24;border-radius:12px;min-width:42px;min-height:39px;font-size:19px;cursor:pointer}\n    .star.active,.fav-btn.active{background:#d97706;color:white;border-color:#f59e0b}\n    .finish-small{background:var(--card2);color:var(--txt);border:1px solid var(--line);border-radius:12px;padding:10px 12px;font-weight:1000;font-size:13px;cursor:pointer}\n    /* Real exam */\n    .real-head{position:sticky;top:0;z-index:40;margin:-14px -14px 12px;padding:12px 14px 10px;background:linear-gradient(180deg,var(--card),rgba(255,255,255,.88));border-bottom:1px solid rgba(148,163,184,.22);backdrop-filter:blur(12px);border-radius:24px 24px 0 0}\n    body:not(.light) .real-head{background:linear-gradient(180deg,rgba(17,24,39,.98),rgba(17,24,39,.84))}\n    .real-top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:8px}\n    .real-title{font-size:18px;font-weight:1000}\n    .real-time{font-size:16px;font-weight:1000;color:#16a34a;white-space:nowrap}\n    .real-line{height:8px;background:rgba(34,197,94,.18);border-radius:999px;overflow:hidden}\n    .real-line-fill{height:100%;width:100%;background:linear-gradient(90deg,#22c55e,#16a34a);border-radius:999px;transition:width 1s linear}\n    .real-meta{margin-top:7px;font-size:12px;color:var(--muted);font-weight:900}\n    .real-list{display:grid;gap:12px}\n    .real-q{background:var(--card2);border:1px solid var(--line);border-radius:17px;padding:12px}\n    .real-q-title{font-size:15px;font-weight:1000;line-height:1.35;margin-bottom:10px}\n    .real-options{display:grid;gap:7px}\n    .real-option{display:flex;gap:9px;align-items:flex-start;background:var(--card);border:1px solid var(--line);border-radius:13px;padding:10px;cursor:pointer;font-weight:850;line-height:1.3}\n    .real-option input{margin-top:2px;accent-color:#6366f1}\n    .real-option.selected{border-color:#6366f1;box-shadow:0 0 0 3px rgba(99,102,241,.15)}\n    .real-option.correct{background:rgba(22,163,74,.18);border-color:rgba(22,163,74,.65);color:#22c55e}\n    .real-option.wrong{background:rgba(220,38,38,.14);border-color:rgba(220,38,38,.55);color:#ef4444}\n    .real-answer-note{margin-top:9px;font-size:13px;font-weight:1000;color:#22c55e}\n    .real-no-answer{margin-top:9px;font-size:13px;font-weight:1000;color:#f59e0b}\n    .real-actions{position:sticky;bottom:0;margin:12px -14px -14px;padding:10px 14px 14px;background:linear-gradient(0deg,var(--card),rgba(255,255,255,.82));border-top:1px solid rgba(148,163,184,.22);border-radius:0 0 24px 24px;backdrop-filter:blur(12px)}\n    body:not(.light) .real-actions{background:linear-gradient(0deg,rgba(17,24,39,.98),rgba(17,24,39,.82))}\n    /* Real result modal */\n    .real-result-modal{position:fixed;inset:0;z-index:100000;background:rgba(15,23,42,.55);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:18px}\n    .real-result-box{width:min(390px,100%);background:var(--card);border:1px solid var(--line);border-radius:24px;box-shadow:0 24px 70px rgba(0,0,0,.35);padding:18px;text-align:center}\n    .real-result-title{font-size:22px;font-weight:1000;margin-bottom:12px}\n    .real-result-stats{display:grid;gap:9px;margin:12px 0}\n    .real-result-row{display:flex;align-items:center;justify-content:space-between;gap:12px;background:var(--card2);border:1px solid var(--line);border-radius:16px;padding:12px 13px;font-weight:1000}\n    .real-result-row.good span:last-child{color:#22c55e}\n    .real-result-row.bad span:last-child{color:#ef4444}\n    .real-result-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:13px}\n    /* List screen */\n    #list-screen{position:relative;overflow:visible;padding-top:0}\n    .sticky-list-head{position:sticky;top:8px;z-index:70;background:var(--card);border:1px solid var(--line);border-radius:24px;padding:14px;margin:0 0 14px;box-shadow:0 14px 34px rgba(15,23,42,.18);backdrop-filter:blur(10px)}\n    body:not(.light) .sticky-list-head{background:rgba(17,24,39,.97)}\n    .list-title-row{display:flex;align-items:center;gap:10px;margin:0 0 10px;padding:0}\n    .list-title-row h2{flex:1;margin:0;font-size:18px;font-weight:1000}\n    .list-title-row .btn{margin-left:auto;min-width:92px;white-space:nowrap}\n    .search{display:block;width:100%;height:46px;border:1px solid var(--line);background:var(--card);color:var(--txt);border-radius:16px;padding:0 14px;font-size:15px;font-weight:900;outline:0;margin:0 0 8px}\n    .study-toggle{width:100%;margin:0;border-radius:16px;display:flex;align-items:center;gap:8px;background:var(--card);border:1px solid var(--line);padding:9px 11px;color:var(--txt);font-weight:900;font-size:13px}\n    .study-toggle input{width:18px;height:18px;accent-color:#38bdf8}\n    /* Items */\n    .item{background:var(--card);border:1px solid var(--line);border-radius:22px;overflow:hidden;padding:12px;margin-bottom:9px}\n    .item-q{font-weight:1000;line-height:1.34;margin-bottom:8px}\n    .answer{color:#22c55e;font-weight:1000;font-size:14px;line-height:1.34}\n    .item-top{display:flex;gap:8px;align-items:flex-start}\n    .item-top .item-q{flex:1}\n    .empty{text-align:center;color:var(--muted);font-weight:900;padding:28px 12px}\n    .pill{background:var(--card2);border:1px solid var(--line);border-radius:999px;padding:7px 9px;color:var(--muted);font-size:12px;font-weight:900;text-align:center}\n    .history-meta{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:9px 0}\n    /* Result */\n    .result-score{font-size:39px;text-align:center;color:var(--cyan);font-weight:1000;margin:14px 0 3px}\n    .percent{font-size:16px;text-align:center;color:#22c55e;font-weight:1000;margin-bottom:13px}\n    .result-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px}\n    .study-options{margin-top:9px;display:grid;gap:7px}\n    .study-opt{background:var(--card2);border:1px solid var(--line);border-radius:11px;padding:9px 10px;color:var(--txt);font-weight:800;line-height:1.34}\n    .study-opt.right{border-color:rgba(34,197,94,.65);background:rgba(22,163,74,.16);color:#22c55e}\n    .badge-generated{display:inline-flex;align-items:center;gap:5px;margin:0 0 8px;padding:6px 9px;border-radius:999px;border:1px solid rgba(245,158,11,.58);background:rgba(245,158,11,.14);color:#f59e0b;font-size:10.5px;font-weight:1000;text-transform:uppercase;letter-spacing:.6px}\n    /* Drawer */\n    .drawer-backdrop{position:fixed;inset:0;background:rgba(15,23,42,.42);backdrop-filter:blur(4px);z-index:90;opacity:0;pointer-events:none;transition:.2s}\n    .drawer-backdrop.open{opacity:1;pointer-events:auto}\n    .side-drawer{position:fixed;top:0;left:0;height:100%;width:min(320px,86vw);background:rgba(255,255,255,.96);border-right:1px solid rgba(226,232,240,.9);box-shadow:0 20px 60px rgba(15,23,42,.22);z-index:91;transform:translateX(-102%);transition:.22s;padding:18px 14px}\n    body:not(.light) .side-drawer{background:rgba(15,23,42,.96);border-color:rgba(71,85,105,.55)}\n    .side-drawer.open{transform:translateX(0)}\n    .drawer-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:14px}\n    .drawer-title{font-size:18px;font-weight:1000}\n    .drawer-sub{font-size:12px;color:var(--muted);font-weight:900;margin-top:3px}\n    .drawer-close{width:40px;height:40px;border-radius:12px;border:1px solid var(--line);background:transparent;color:var(--txt);font-size:24px;cursor:pointer}\n    .drawer-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0 12px}\n    .drawer-stat{display:flex;align-items:center;justify-content:center;gap:6px;min-height:42px;border-radius:15px;background:rgba(99,102,241,.12);border:1px solid rgba(129,140,248,.25);font-size:13px;font-weight:1000;color:var(--txt)}\n    .drawer-stat span{color:var(--muted);font-size:11px;font-weight:900}\n    .drawer-list{display:grid;gap:10px}\n    .drawer-item{width:100%;border:1px solid rgba(203,213,225,.9);background:#f8fafc;color:#111827;border-radius:16px;padding:14px;font-size:15px;font-weight:1000;display:flex;align-items:center;gap:10px;cursor:pointer;text-align:left}\n    body:not(.light) .drawer-item{background:rgba(30,41,59,.9);border-color:rgba(71,85,105,.55);color:#f8fafc}\n    /* Daily usage note */\n    #usage-limit-note{margin:8px 0 4px;border-radius:14px;font-size:13px;font-weight:900;text-align:center;padding:9px 12px}\n    #usage-limit-note.limit-free{background:rgba(99,102,241,.10);border:1px solid rgba(129,140,248,.28);color:var(--txt)}\n    #usage-limit-note.limit-warn{background:rgba(245,158,11,.12);border:1px solid rgba(245,158,11,.38);color:#f59e0b}\n    #usage-limit-note.limit-locked{background:rgba(220,38,38,.12);border:1px solid rgba(248,113,113,.4);color:#fca5a5}\n    #usage-limit-note.limit-premium{background:rgba(22,163,74,.10);border:1px solid rgba(34,197,94,.28);color:#4ade80}\n    /* Toast */\n    .toast-upgrade{position:fixed;bottom:84px;left:50%;transform:translateX(-50%) translateY(20px);background:#1e293b;color:#f8fafc;border:1px solid #334155;border-radius:14px;padding:10px 18px;font-size:14px;font-weight:1000;z-index:200000;opacity:0;pointer-events:none;transition:.22s;white-space:nowrap;max-width:calc(100vw - 28px)}\n    .toast-upgrade.show{opacity:1;transform:translateX(-50%) translateY(0)}\n    /* Scroll to top */\n    .scroll-top-upgrade{position:fixed;bottom:22px;right:14px;width:42px;height:42px;border-radius:14px;background:#1e293b;border:1px solid #334155;color:#94a3b8;font-size:18px;font-weight:1000;cursor:pointer;z-index:500;opacity:0;pointer-events:none;transition:.22s;display:flex;align-items:center;justify-content:center;box-shadow:0 8px 20px rgba(0,0,0,.24)}\n    .scroll-top-upgrade.show{opacity:1;pointer-events:auto}\n    /* Search tools */\n    .search-tools{display:flex;align-items:center;gap:8px;margin-top:8px}\n    .search-counter{flex:1;font-size:12px;font-weight:900;color:var(--muted)}\n    .clear-search{border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:9px;padding:5px 10px;font-size:12px;font-weight:1000;cursor:pointer}\n    /* Section label */\n    .section-label{font-size:10px;text-transform:uppercase;letter-spacing:1.3px;color:var(--muted);font-weight:1000;margin-bottom:7px}\n    /* Animations */\n    .shake{animation:shake .3s ease}\n    .btn-click{animation:btnPop .18s ease}\n    .soft-enter{animation:fadeUp .28s ease both}\n    @keyframes fadeUp{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n    @keyframes pop{0%{opacity:0;transform:scale(.9) translateY(12px)}100%{opacity:1;transform:none}}\n    @keyframes spin{to{transform:rotate(360deg)}}\n    @keyframes btnPop{50%{transform:scale(.97)}}\n    @keyframes shake{25%{transform:translateX(-3px)}50%{transform:translateX(3px)}75%{transform:translateX(-2px)}}\n    /* Mobile tweaks */\n    @media(max-width:420px){\n      .mode-tab{font-size:12px}.simple-input{font-size:14px;height:44px;border-radius:15px}\n      .simple-label{font-size:13px}.menu-main-btn{min-height:52px}.card{padding:13px}\n      .title{font-size:22px}.real-head{margin:-13px -13px 10px;padding:11px 13px 9px}\n      .real-q{padding:11px}.real-option{padding:9px;font-size:14px}\n      .real-result-actions{grid-template-columns:1fr}.list-title-row .btn{min-width:86px}\n    }\n  </style>\n  <link rel=\"stylesheet\" href=\"./eco-upgrade.css?v=3\"/>\n  <link rel=\"stylesheet\" href=\"./eco-final-patch.css?v=14\"/>\n</head>\n<body>\n<script>\n// Safety fallback: show menu within 1.4s no matter what\nsetTimeout(function(){\n  try{\n    var s=document.getElementById('splash');\n    if(s){s.classList.add('hide');setTimeout(function(){s&&s.remove&&s.remove()},450)}\n    var l=document.getElementById('auth-loading');if(l)l.classList.add('hidden');\n    var m=document.getElementById('start-screen');if(m)m.classList.remove('hidden');\n  }catch(e){}\n},1400);\n</script>\n\n<div id=\"splash\" class=\"splash\"><div class=\"splash-logo\"><div class=\"splash-mark\">📈</div><div class=\"splash-title\">Economy Pro</div><div class=\"splash-sub\">Макроэкономика</div></div></div>\n<div id=\"auth-loading\" class=\"loading-screen hidden\"><div class=\"loader-card\"><div class=\"spinner\"></div><div id=\"auth-loading-text\" style=\"font-weight:1000\">Загрузка...</div><div class=\"muted\" style=\"font-size:12px;margin-top:6px;font-weight:900\">Подготавливаем сайт</div></div></div>\n\n<!-- ═══════════════ PAYWALL (активация только администратором) ═══════════════ -->\n<div id=\"paywall\" class=\"paywall hidden\">\n  <div class=\"paybox\">\n    <button id=\"pay-close-btn\" class=\"pay-close\" type=\"button\" onclick=\"hidePaywall()\">×</button>\n    <div id=\"pay-icon\" class=\"pay-icon\">🔐</div>\n    <div id=\"pay-title\" class=\"pay-title\">Премиум-доступ</div>\n    <p id=\"pay-sub\" class=\"pay-sub\">Чтобы получить доступ к тестам без ограничений, оплатите подписку и отправьте данные администратору.</p>\n\n    <div class=\"pay-card\">\n      <div class=\"pay-label\">Ваш Telegram ID</div>\n      <div class=\"row\">\n        <div id=\"pay-user-id\" class=\"pay-value\" style=\"flex:1\">Определяется...</div>\n        <button class=\"copy\" onclick=\"copyUserId()\">📋</button>\n      </div>\n    </div>\n\n    <div class=\"pay-card\">\n      <div class=\"pay-label\">ID устройства</div>\n      <div class=\"row\">\n        <div id=\"pay-device-id\" class=\"pay-value\" style=\"flex:1\">Определяется...</div>\n        <button class=\"copy\" onclick=\"copyDeviceId()\">📋</button>\n      </div>\n    </div>\n\n    <div class=\"pay-card pay-card-payment\">\n      <div class=\"pay-label\">Оплата подписки</div>\n      <div class=\"pay-price-box\">\n        <div class=\"pay-price-title\">Стоимость доступа</div>\n        <div class=\"pay-price\">30 000 сум</div>\n      </div>\n      <div class=\"pay-transfer-text\">Переведите оплату на карту:</div>\n      <div class=\"pay-card-number-row\">\n        <div id=\"pay-card-number\" class=\"pay-card-number\">5614 6805 7717 0398</div>\n        <button class=\"copy copy-card\" onclick=\"copyCardNumber()\">📋</button>\n      </div>\n      <button class=\"btn btn-amber btn-full\" onclick=\"copyCardNumber()\" style=\"margin-top:10px\">💳 Скопировать номер карты</button>\n      <div class=\"pay-after-text\">После оплаты отправьте чек администратору вместе с Telegram ID и ID устройства.</div>\n      <button class=\"btn btn-primary btn-full\" onclick=\"copySubscriptionData()\" style=\"margin-top:10px\">📋 Скопировать данные для активации</button>\n      <a class=\"btn btn-green btn-full\" href=\"https://t.me/nurislombekm\" target=\"_blank\" style=\"text-decoration:none;margin-top:8px\">💬 Отправить чек @nurislombekm</a>\n    </div>\n\n    <div id=\"pay-error\" class=\"pay-error\"></div>\n    <div id=\"pay-success-msg\" class=\"pay-success hidden\"></div>\n    <div id=\"pay-danger-note\" class=\"danger-note\">Доступ активируется вручную после проверки оплаты. Когда администратор подтвердит оплату, обновите сайт — статус станет «Премиум пользователь».</div>\n  </div>\n</div>\n\n<div class=\"app\">\n  <div class=\"topbar\">\n    <button id=\"menu-toggle\" class=\"menu-toggle\" onclick=\"toggleDrawer()\">☰</button>\n    <div class=\"subject-switch-wrap\">\n      <select id=\"subject-select\" class=\"subject-select\" onchange=\"switchSubject(this.value)\">\n        <option value=\"macro\">📚 Маркетинг</option>\n      </select>\n    </div>\n    <div class=\"top-right\">\n      <span id=\"premium-badge\" class=\"premium-badge hidden\"></span>\n      <button class=\"icon-btn\" onclick=\"toggleTheme()\" id=\"theme-btn\">🌙</button>\n    </div>\n  </div>\n\n  <!-- ═══ START SCREEN ═══ -->\n  <section id=\"start-screen\" class=\"screen card hidden\">\n    <div class=\"center\">\n      <a class=\"profile-link\" href=\"https://t.me/nurislombekm\" target=\"_blank\">@nurislombekm</a>\n      <h1 class=\"title\">Добро пожаловать</h1>\n      <div class=\"welcome-subject\">Макроэкономика</div>\n      <div id=\"user-badge\" class=\"user-badge\"></div>\n    </div>\n\n    <!-- Resume card -->\n    <div id=\"resume-card\" class=\"panel resume hidden\">\n      <div class=\"resume-title\">Продолжить предыдущий тест?</div>\n      <div id=\"resume-text\" class=\"resume-text\">У вас есть незавершённая попытка.</div>\n      <div class=\"quick two\" style=\"margin-top:9px\">\n        <button onclick=\"continueSavedSession()\">Продолжить</button>\n        <button onclick=\"discardSavedSession()\">Сбросить</button>\n      </div>\n    </div>\n\n    <!-- Usage limit note inserted here by JS -->\n\n    <!-- Config -->\n    <div class=\"simple-config\">\n      <div class=\"mode-tabs\">\n        <button id=\"mode-normal\" class=\"mode-tab active\" onclick=\"setRunMode('normal')\">Обычный</button>\n        <button id=\"mode-no-time\" class=\"mode-tab\" onclick=\"setRunMode('notime')\">Без времени</button>\n        <button id=\"mode-real\" class=\"mode-tab\" onclick=\"setRunMode('real')\">Реальный тест</button>\n      </div>\n\n      <div class=\"simple-group\">\n        <div class=\"seg\">\n          <button id=\"order-random\" class=\"active\" onclick=\"setOrderMode('random')\">Случайно</button>\n          <button id=\"order-seq\" onclick=\"setOrderMode('sequential')\">По порядку</button>\n        </div>\n      </div>\n\n      <div class=\"settings-grid\">\n        <div class=\"setting-card\" id=\"time-group\">\n          <div class=\"simple-label\">⏱ Время теста (в секундах)</div>\n          <input id=\"time-custom\" class=\"simple-input\" type=\"number\" min=\"1\" inputmode=\"numeric\" value=\"600\" placeholder=\"600\">\n        </div>\n\n        <div class=\"setting-card\" id=\"count-group\">\n          <div class=\"simple-label\">📝 Вопросы</div>\n          <div class=\"select-wrap\"><select id=\"count-select\" class=\"simple-input simple-select\">\n            <option value=\"all\" selected>Все вопросы</option>\n            <option value=\"20\">20 вопросов</option><option value=\"25\">25 вопросов</option>\n            <option value=\"30\">30 вопросов</option><option value=\"40\">40 вопросов</option>\n            <option value=\"favorites\">Избранные</option><option value=\"mistakes\">Режим ошибки</option>\n          </select></div>\n          <input id=\"count-custom\" class=\"simple-input\" type=\"number\" min=\"1\" inputmode=\"numeric\" placeholder=\"своё\">\n        </div>\n\n        <div class=\"setting-card range-card\">\n          <div class=\"simple-label\">🔢 Диапазон</div>\n          <div class=\"range-inputs\">\n            <input id=\"range-from\" class=\"simple-input\" type=\"number\" min=\"1\" inputmode=\"numeric\" placeholder=\"от\">\n            <input id=\"range-to\" class=\"simple-input\" type=\"number\" min=\"1\" inputmode=\"numeric\" placeholder=\"до\">\n          </div>\n        </div>\n      </div>\n\n      <div class=\"mini-note compact-total\">Всего в базе: <span id=\"total-count\">—</span></div>\n      <button class=\"btn btn-primary btn-full menu-main-btn\" onclick=\"guardedStart()\">Начать тест</button>\n    </div>\n    <div id=\"config-error\" class=\"config-error hidden\"></div>\n  </section>\n\n  <!-- ═══ TEST SCREEN ═══ -->\n  <section id=\"test-screen\" class=\"screen card hidden\">\n    <div class=\"screen-head\">\n      <div>\n        <div id=\"timer-display\" class=\"timer\">20:00</div>\n        <div id=\"test-meta\" class=\"muted\" style=\"font-size:12px;font-weight:900\">Макроэкономика</div>\n      </div>\n      <div class=\"top-actions\">\n        <button id=\"fav-current\" class=\"fav-btn\" onclick=\"toggleCurrentFavorite()\">☆</button>\n        <button class=\"finish-small\" onclick=\"confirmFinish()\">Завершить</button>\n      </div>\n    </div>\n    <div id=\"gen-badge-test\"></div>\n    <div id=\"q-index\" class=\"q-index\"></div>\n    <div id=\"question\" class=\"question\"></div>\n    <ul id=\"options\" class=\"options\"></ul>\n    <button id=\"accept-btn\" class=\"btn btn-green btn-full\" onclick=\"acceptAnswer()\">Подтвердить ответ</button>\n    <div class=\"question-actions\">\n      <button id=\"prev-btn\" class=\"btn btn-gray\" onclick=\"prevQuestion()\">←</button>\n      <button id=\"next-btn\" class=\"btn btn-primary\" onclick=\"nextQuestion()\">Дальше</button>\n      <button id=\"skip-btn\" class=\"btn btn-gray\" onclick=\"nextQuestion()\">Пропустить</button>\n      <button id=\"finish-btn\" class=\"btn btn-green\" onclick=\"finishTest()\">Показать результат</button>\n    </div>\n  </section>\n\n  <!-- ═══ REAL EXAM SCREEN ═══ -->\n  <section id=\"real-exam-screen\" class=\"screen card hidden\">\n    <div class=\"real-head\">\n      <div class=\"real-top\">\n        <div class=\"real-title\">Реальный тест</div>\n        <div id=\"real-timer\" class=\"real-time\">30:00</div>\n      </div>\n      <div class=\"real-line\"><div id=\"real-line-fill\" class=\"real-line-fill\"></div></div>\n      <div id=\"real-meta\" class=\"real-meta\">25 вопросов · 30 минут · ответы после завершения</div>\n    </div>\n    <div id=\"real-list\" class=\"real-list\"></div>\n    <div class=\"real-actions\">\n      <button id=\"real-finish-btn\" class=\"btn btn-green btn-full\" onclick=\"confirmFinishRealExam()\">Завершить реальный тест</button>\n      <button id=\"real-back-btn\" class=\"btn btn-primary btn-full hidden\" onclick=\"backToMenu()\" style=\"margin-top:8px\">Вернуться в меню</button>\n    </div>\n  </section>\n\n  <!-- ═══ LIST SCREEN ═══ -->\n  <section id=\"list-screen\" class=\"screen hidden\">\n    <div class=\"sticky-list-head\">\n      <div class=\"list-title-row\">\n        <h2 id=\"list-title\">Список</h2>\n        <button class=\"btn btn-gray btn-small\" onclick=\"backToMenu()\">Назад</button>\n      </div>\n      <input id=\"search-box\" class=\"search\" placeholder=\"Поиск по вопросам...\" oninput=\"filterList()\">\n      <label id=\"study-options-row\" class=\"study-toggle hidden\">\n        <input id=\"study-show-options\" type=\"checkbox\" onchange=\"renderDataList(currentDataView)\">Показать все варианты ответов\n      </label>\n    </div>\n    <div id=\"list-content\"></div>\n  </section>\n\n  <!-- ═══ RESULT SCREEN ═══ -->\n  <section id=\"result-screen\" class=\"screen card hidden\">\n    <h2 class=\"center\">Результат</h2>\n    <div id=\"final-score\" class=\"result-score\">0 / 0</div>\n    <div id=\"final-percent\" class=\"percent\">0%</div>\n    <div class=\"result-actions\">\n      <button class=\"btn btn-primary\" onclick=\"backToMenu()\">В меню</button>\n      <button class=\"btn btn-gray\" onclick=\"toggleReview()\">Разбор</button>\n    </div>\n    <div id=\"review-container\" class=\"hidden\"></div>\n  </section>\n</div>\n\n<!-- Drawer backdrop -->\n<div id=\"drawer-backdrop\" class=\"drawer-backdrop\" onclick=\"closeDrawer()\"></div>\n\n<!-- Side drawer -->\n<aside id=\"side-drawer\" class=\"side-drawer\">\n  <div class=\"drawer-head\">\n    <div><div class=\"drawer-title\">Меню</div><div class=\"drawer-sub\">Дополнительные разделы</div></div>\n    <button class=\"drawer-close\" onclick=\"closeDrawer()\">×</button>\n  </div>\n  <div class=\"drawer-list\">\n    <button class=\"drawer-item\" onclick=\"closeDrawer();guardedAction(initStudy)\">📖 Изучить тесты</button>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();guardedAction(showFavorites)\">⭐ Избранные вопросы</button>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();guardedAction(showHistory)\">🕘 История результатов</button>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();guardedAction(()=>showMistakeList())\">❗ Изучить ошибки</button>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();ecoQuickStart('mistakes')\">🎯 Быстрый тест по ошибкам</button>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();ecoResetFilters()\">🧹 Сбросить настройки</button>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();openActivationPanel()\">🔑 Активация подписки</button>\n  </div>\n</aside>\n\n<!-- Real exam result modal -->\n<div id=\"real-result-modal\" class=\"real-result-modal hidden\">\n  <div class=\"real-result-box\">\n    <div class=\"real-result-title\">Результат реального теста</div>\n    <div class=\"real-result-stats\">\n      <div class=\"real-result-row good\"><span>Правильные ответы:</span><span id=\"real-correct-count\">0</span></div>\n      <div class=\"real-result-row bad\"><span>Неправильные:</span><span id=\"real-wrong-count\">0</span></div>\n    </div>\n    <div class=\"real-result-actions\">\n      <button class=\"btn btn-primary\" onclick=\"closeRealResultToMenu()\">В главное меню</button>\n      <button class=\"btn btn-green\" onclick=\"viewRealAnswers()\">Просмотреть ответы</button>\n    </div>\n  </div>\n</div>\n\n<script>\n/* ════════════════════════════════════════════════\n   CORE GLOBALS\n════════════════════════════════════════════════ */\nlet tgUserId='',tgUser='Гость';\nlet subjects={},database=[],unlocked=false;\nlet orderMode='random',noTime=false,runMode='normal',perQuestionTime=30;\nlet blockedReportSent=false;\nlet sessionQuestions=[],currentIdx=0,userAnswers=[],confirmed=[],timeLeft=0;\nlet timerInterval=null,currentTestMeta={},currentDataView=[],lastReviewVisible=false;\nvar accessLists={premium:null,banned:null,devices:null};\nwindow.accessLists=accessLists;\nlet realExamQuestions=[],realExamAnswers=[],realExamFinished=false,realExamTimeLeft=0,realExamTimer=null,realExamTotalSeconds=1800;\n\n/* ════════════════════════════════════════════════\n   DEVICE FINGERPRINT\n════════════════════════════════════════════════ */\nfunction cleanUserId(v){return String(v||'').trim().replace(/\\D/g,'')}\nfunction getDeviceInfo(){\n  const ua=navigator.userAgent||'';\n  let device='Unknown';\n  if(/iPhone/i.test(ua)) device='iPhone';\n  else if(/iPad/i.test(ua)) device='iPad';\n  else if(/Android/i.test(ua)) device='Android';\n  else if(/Windows/i.test(ua)) device='Windows';\n  else if(/Macintosh/i.test(ua)) device='Mac';\n  return{device,ua,platform:navigator.platform||'-',lang:navigator.language||'-',screen:`${screen.width}x${screen.height}`,ratio:String(window.devicePixelRatio||'-'),tz:Intl.DateTimeFormat().resolvedOptions().timeZone||'-',memory:navigator.deviceMemory||'-',cores:navigator.hardwareConcurrency||'-'};\n}\nfunction simpleHash(str){\n  let h=2166136261;\n  for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h+=(h<<1)+(h<<4)+(h<<7)+(h<<8)+(h<<24);}\n  return ('00000000'+(h>>>0).toString(16)).slice(-8).toUpperCase();\n}\nfunction getDeviceFingerprint(){const d=getDeviceInfo();return simpleHash([d.device,d.ua,d.platform,d.lang,d.screen,d.ratio,d.tz,d.memory,d.cores].join('|'))}\nfunction getDeviceSummary(){const d=getDeviceInfo();return `${d.device} · ${d.platform} · ${d.screen} · ${d.lang} · ${d.tz} · FP:${getDeviceFingerprint()}`}\n\n/* ════════════════════════════════════════════════\n   JSON CACHE / FETCH\n════════════════════════════════════════════════ */\nconst jsonCache={};\nasync function fetchJsonSafe(url,fallback,timeout=5000,ttl=30000){\n  const now=Date.now(),cached=jsonCache[url];\n  if(cached&&now-cached.time<ttl)return cached.data;\n  const ctrl=new AbortController();\n  const t=setTimeout(()=>ctrl.abort(),timeout);\n  try{\n    const sep=url.includes('?')?'&':'?';\n    const opts={cache:'no-store',signal:ctrl.signal};\n    try{\n      if(String(url).includes('/api/')){\n        const initData=telegramInitData?.()||'';\n        opts.headers=initData?{'X-Telegram-Init-Data':initData}:{};\n      }\n    }catch(e){}\n    const r=await fetch(url+sep+'v='+now,opts);\n    if(!r.ok)return cached?cached.data:fallback;\n    const data=await r.json();\n    jsonCache[url]={time:now,data};\n    return data;\n  }catch(e){return cached?cached.data:fallback;}\n  finally{clearTimeout(t);}\n}\nfunction getBackendBase(){\n  const env=window.__APP_ENV||{};\n  return String(env.BACKEND_URL||env.REPORT_PROXY_URL||'').replace(/\\/+$/,'');\n}\nfunction apiUrl(path){\n  if(/^https?:\\/\\//i.test(path))return path;\n  const base=getBackendBase();\n  if(!base)return path;\n  return base+'/'+String(path||'').replace(/^\\/+/,'');\n}\nfunction telegramInitData(){\n  try{return window.Telegram?.WebApp?.initData||'';}catch(e){return '';}\n}\nasync function loadLists(){\n  const fb={users:{}};\n  const id=cleanUserId(tgUserId);\n  try{\n    const res=await fetch(apiUrl('/api/access'),{\n      method:'POST',\n      cache:'no-store',\n      headers:{'Content-Type':'application/json'},\n      body:JSON.stringify({\n        telegram_id:id,\n        fingerprint:(typeof getDeviceFingerprint==='function'?getDeviceFingerprint():''),\n        initData:telegramInitData()\n      })\n    });\n    if(!res.ok)throw new Error('access api '+res.status);\n    const data=await res.json();\n    const premiumUsers={},bannedUsers={},deviceUsers={};\n    if(id&&data.isPremium){\n      premiumUsers[id]={active:true,user_id:id,uid:id,expires:data.expires||'',fingerprint:data.fingerprint||''};\n    }\n    if(id&&data.isBlocked){\n      bannedUsers[id]={active:true,reason:data.blockReason||'Доступ заблокирован.',type:data.blockType||'permanent',until:data.until||''};\n    }\n    if(id&&data.deviceBlocked){\n      deviceUsers[id]={active:true,fingerprint:'BACKEND_LOCK',reason:data.deviceReason||'Вход с нового устройства заблокирован.'};\n    }\n    accessLists.premium={users:premiumUsers};\n    accessLists.banned={users:bannedUsers};\n    accessLists.devices={users:deviceUsers};\n  }catch(e){\n    console.warn('Backend access API недоступен:',e);\n    accessLists.premium=fb;accessLists.banned=fb;accessLists.devices=fb;\n  }\n  window.accessLists=accessLists;\n  return accessLists;\n}\n\n/* ════════════════════════════════════════════════\n   ACCESS HELPERS\n════════════════════════════════════════════════ */\nfunction userRecord(list,id){\n  if(!list)return null;id=cleanUserId(id);\n  const sources=[list.users,list.premium_users,list.premium,list];\n  for(const u of sources){\n    if(!u)continue;\n    if(Array.isArray(u)){const found=u.find(x=>cleanUserId(typeof x==='object'?(x.id||x.user_id||x.telegram_id):x)===id);if(found)return typeof found==='object'?found:true}\n    if(typeof u==='object'){if(u[id]!==undefined||u[String(id)]!==undefined)return u[id]??u[String(id)];const e=Object.entries(u).find(([k])=>cleanUserId(k)===id);if(e)return e[1]}\n  }\n  return null;\n}\nfunction isActiveRecord(rec){\n  if(!rec)return false;if(rec===true)return true;\n  if(typeof rec==='object'){\n    if(rec.active===false)return false;\n    const until=rec.until||rec.exp||rec.expires;\n    if(until&&Date.now()>new Date(until).getTime())return false;\n    return rec.active===true||!('active'in rec);\n  }\n  return false;\n}\nfunction banReason(id){const rec=userRecord(accessLists.banned,id);if(isActiveRecord(rec))return typeof rec==='object'?(rec.reason||'Доступ заблокирован.'):'Доступ заблокирован.';return ''}\nfunction getBanInfo(id){id=cleanUserId(id);const u=accessLists.banned?.users?.[id];if(!u||!u.active)return null;if(u.type==='temporary'&&u.until&&new Date(u.until)<new Date())return null;return u}\nfunction reportBlockedVisitOnce(){const info=getBanInfo(tgUserId);if(info&&!blockedReportSent){blockedReportSent=true;if(window.sendBlockedVisitReport)window.sendBlockedVisitReport(tgUser,tgUserId,{reason:info.reason||'Заблокирован',type:info.type||'permanent',until:info.until||'-'});}}\nfunction sendSiteOpenReportOnce(isPremium,isBlocked=false,blockReason=''){\n  try{\n    const u=window.Telegram?.WebApp?.initDataUnsafe?.user||null;\n    const realId=String((u&&u.id)||tgUserId||'').replace(/\\D+/g,'');\n    if(!u || !realId)return; // Не отправляем фейковые отчёты без Telegram ID\n    if(window.sendVisitNotification){\n      window.sendVisitNotification(tgUser,realId,{\n        isPremium:!!isPremium,\n        isBlocked:!!isBlocked,\n        blockReason:blockReason||'',\n        telegramUsername:u.username||'',\n        firstName:u.first_name||'',\n        lastName:u.last_name||''\n      });\n    }\n  }catch(e){}\n}\nfunction hasPremium(id){return isActiveRecord(userRecord(accessLists.premium,id))}\nfunction getDeviceLock(id){const rec=userRecord(accessLists.devices,id);if(!rec||rec===true)return null;if(typeof rec==='object'&&rec.active!==false)return rec;return null;}\nfunction deviceLockReason(id){\n  const lock=getDeviceLock(id);if(!lock)return '';\n  const expected=String(lock.fingerprint||lock.fp||'').trim().toUpperCase();if(!expected)return '';\n  const current=getDeviceFingerprint();\n  if(expected!==current)return lock.reason||`Вход с нового устройства заблокирован. FP: ${current}`;\n  return '';\n}\n\n/* ═══ Two-device detection ══════════════════════════════ */\nconst LAST_FP_KEY='eco_last_fp_v1';\nfunction checkTwoDevices(){\n  const storedFp=localStorage.getItem(LAST_FP_KEY)||'';\n  const currentFp=getDeviceFingerprint();\n  if(storedFp && storedFp!==currentFp){\n    // Different fingerprint than last time — potential two-device use\n    if(window.sendTwoDeviceAlert) window.sendTwoDeviceAlert(tgUser,tgUserId,storedFp,currentFp);\n    if(window.sendDeviceControlReport) window.sendDeviceControlReport(tgUser,tgUserId,{\n      status:'two_devices',reason:'Вход с нового устройства (предыдущий FP отличается)',fingerprint:currentFp\n    });\n  }\n  localStorage.setItem(LAST_FP_KEY,currentFp);\n}\n\n/* ════════════════════════════════════════════════\n   ADMIN/TERMUX ACTIVATION (no key input on site)\n════════════════════════════════════════════════ */\nfunction clearKey(){try{localStorage.removeItem('eco_access_key_v1')}catch(e){}}\nasync function checkLocalKey(){return false}\nfunction activateKeyCode(){openActivationPanel()}\n\n/* ════════════════════════════════════════════════\n   PREMIUM BADGE\n════════════════════════════════════════════════ */\nfunction updatePremiumBadge(isPremium){\n  const el=document.getElementById('premium-badge');if(!el)return;\n  el.classList.remove('hidden','ordinary');\n  el.classList.toggle('ordinary',!isPremium);\n  el.textContent=isPremium?'PRO':'Free';\n  el.setAttribute('aria-label',isPremium?'Премиум пользователь':'Обычный пользователь');\n  el.title=isPremium?'Premium активен':'Бесплатный доступ';\n}\nasync function refreshPremiumBadge(){\n  try{await loadLists();}catch(e){}\n  const id=cleanUserId(tgUserId);\n  const fromFile=id&&hasPremium(id)&&!banReason(id);\n  updatePremiumBadge(!!fromFile);\n  return !!fromFile;\n}\n\n/* ════════════════════════════════════════════════\n   ACCESS CHECK\n════════════════════════════════════════════════ */\nasync function checkAccess(showMsg=true){\n  await loadLists();\n  const id=cleanUserId(tgUserId);\n  if(!id){\n    if(showMsg)showPaywall('Откройте сайт через Telegram Mini App, чтобы получить Telegram ID.');\n    return false;\n  }\n  const reason=banReason(id);\n  if(reason){clearKey();showBlockedPaywall(reason);return false;}\n  const devReason=deviceLockReason(id);\n  if(devReason){\n    if(window.sendDeviceControlReport) window.sendDeviceControlReport(tgUser,tgUserId,{status:'blocked_new_device',reason:devReason,fingerprint:getDeviceFingerprint()});\n    showPaywall(devReason);return false;\n  }\n  if(hasPremium(id)){unlocked=true;updatePremiumBadge(true);hidePaywall();return true;}\n  unlocked=false;\n  if(showMsg)showPaywall('Подписка не найдена для ID '+id+'. Оплатите 30 000 сум на карту 5614 6805 7717 0398 и отправьте чек @nurislombekm.');\n  return false;\n}\n\n/* ════════════════════════════════════════════════\n   DAILY LIMIT (Free users: 3 tests/day)\n════════════════════════════════════════════════ */\nconst USAGE_KEY='macro_daily_limit_v2';\nconst DAY=86400000,LIMIT=3;\nfunction usageRecords(){\n  let a=[];try{a=JSON.parse(localStorage.getItem(USAGE_KEY)||'[]')}catch(e){}\n  const now=Date.now();\n  a=(Array.isArray(a)?a:[]).map(Number).filter(x=>Number.isFinite(x)&&now-x<DAY).sort((a,b)=>a-b);\n  try{localStorage.setItem(USAGE_KEY,JSON.stringify(a))}catch(e){}\n  return a;\n}\nfunction setUsage(a){try{localStorage.setItem(USAGE_KEY,JSON.stringify(a))}catch(e){}}\nfunction isPremiumUser(){\n  const id=cleanUserId(tgUserId);\n  if(id&&hasPremium(id)&&!banReason(id))return true;\n  return false;\n}\nfunction limitInfo(){\n  const p=isPremiumUser();\n  const records=p?[]:usageRecords();\n  const used=records.length,left=p?Infinity:Math.max(0,LIMIT-used);\n  return{premium:p,used,left,locked:!p&&left<=0,resetAt:records[0]?records[0]+DAY:null};\n}\nfunction ensureLimitNote(){\n  let n=document.getElementById('usage-limit-note');\n  if(n)return n;\n  n=document.createElement('div');n.id='usage-limit-note';\n  const anchor=document.getElementById('resume-card');\n  if(anchor)anchor.insertAdjacentElement('afterend',n);\n  return n;\n}\nfunction limitWord(n){\n  n=Math.abs(Number(n)||0)%100;\n  const n1=n%10;\n  if(n>10&&n<20)return 'лимитов';\n  if(n1===1)return 'лимит';\n  if(n1>=2&&n1<=4)return 'лимита';\n  return 'лимитов';\n}\nfunction updateMainLimitBadge(info){\n  const ub=document.getElementById('user-badge');\n  if(!ub)return;\n  if(!info)info=limitInfo();\n  if(info.premium){\n    ub.innerHTML='';\n    ub.classList.add('hidden');\n    return;\n  }\n  ub.classList.remove('hidden');\n  const left=Math.max(0,info.left||0);\n  if(left>0){\n    ub.innerHTML=`<span class=\"limit-badge-main\">Осталось ${left} ${limitWord(left)}</span>`;\n  }else{\n    ub.innerHTML=`<span class=\"limit-badge-main\">Осталось 0 лимитов · активируйте подписку, чтобы решать без лимита</span>`;\n  }\n}\nfunction renderLimit(){\n  const info=limitInfo();\n  const n=document.getElementById('usage-limit-note');\n  if(n){n.style.display='none';n.innerHTML='';}\n  updateMainLimitBadge(info);\n  return info;\n}\nfunction recordUsage(){const a=usageRecords();a.push(Date.now());setUsage(a);}\nfunction consumeUsage(){\n  const info=limitInfo();\n  if(info.premium)return true;\n  if(info.locked)return false;\n  recordUsage();\n  return true;\n}\n\n/* ════════════════════════════════════════════════\n   GUARDED ACTIONS (checks access OR limit)\n════════════════════════════════════════════════ */\nasync function withOneSecondLoader(task,text='Загрузка...'){\n  showAccessLoader(text);\n  const minDelay=sleep(700);\n  let result=false;\n  try{result=await task();}catch(e){console.warn(e);result=false;}\n  await minDelay;hideAccessLoader();\n  return result;\n}\nasync function guardedAction(fn){\n  buttonPop(event);\n  const ok=await withOneSecondLoader(()=>checkAccess(true));\n  if(ok)fn();\n}\nasync function guardedStart(){\n  buttonPop(event);\n  const info=limitInfo();\n  if(!info.premium && info.locked){\n    const reset=info.resetAt?new Date(info.resetAt).toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'}):'позже';\n    showConfigError(`Лимит бесплатных тестов исчерпан (${LIMIT}/${LIMIT}). Сброс в ${reset}. Активируйте подписку, чтобы решать без лимита.`);\n    if(typeof openSubscriptionModal==='function')openSubscriptionModal();\n    return;\n  }\n  startTest();\n  if(!info.premium) recordUsage();\n  renderLimit();\n}\n\n/* ════════════════════════════════════════════════\n   PAYWALL HELPERS\n════════════════════════════════════════════════ */\nfunction resetPaywallMode(){\n  const p=document.getElementById('paywall');\n  if(p)p.classList.remove('blocked-mode');\n  const icon=document.getElementById('pay-icon');if(icon)icon.textContent='🔐';\n  const title=document.getElementById('pay-title');if(title)title.textContent='Премиум-доступ';\n  const sub=document.getElementById('pay-sub');if(sub)sub.textContent='Чтобы получить доступ к тестам без ограничений, оплатите подписку и отправьте данные администратору.';\n  const note=document.getElementById('pay-danger-note');if(note)note.textContent='Доступ активируется вручную после проверки оплаты. Когда администратор подтвердит оплату, обновите сайт — статус станет «Премиум пользователь».';\n  const blocked=document.getElementById('blocked-contact-card');if(blocked)blocked.remove();\n  const e=document.getElementById('pay-error');if(e)e.style.color='';\n}\nfunction showPaywall(msg=''){\n  resetPaywallMode();\n  const uid=document.getElementById('pay-user-id');\n  if(uid)uid.innerText=tgUserId||'Откройте через Telegram Mini App';\n  document.getElementById('paywall').classList.remove('hidden');\n  if(msg)showPayError(msg);\n}\nfunction showBlockedPaywall(reason=''){\n  const uid=document.getElementById('pay-user-id');\n  if(uid)uid.innerText=tgUserId||'Откройте через Telegram Mini App';\n  const p=document.getElementById('paywall');\n  if(p){p.classList.remove('hidden');p.classList.add('blocked-mode');}\n  const icon=document.getElementById('pay-icon');if(icon)icon.textContent='🚫';\n  const title=document.getElementById('pay-title');if(title)title.textContent='Доступ заблокирован';\n  const sub=document.getElementById('pay-sub');if(sub)sub.textContent='Ваш аккаунт был заблокирован администрацией сайта.';\n  const note=document.getElementById('pay-danger-note');if(note)note.textContent='Если вы считаете, что блокировка произошла по ошибке, свяжитесь с администратором.';\n  if(!document.getElementById('blocked-contact-card')){\n    const deviceCard=document.getElementById('pay-device-id')?.closest?.('.pay-card');\n    const card=document.createElement('div');\n    card.id='blocked-contact-card';\n    card.className='pay-card blocked-card';\n    card.innerHTML=`<div class=\"blocked-main-text\">Вы были заблокированы администрацией.</div><div class=\"blocked-small-text\">Прохождение тестов и премиум-доступ для этого аккаунта временно недоступны.</div><a class=\"btn btn-red btn-full\" href=\"https://t.me/nurislombekm\" target=\"_blank\" style=\"text-decoration:none\">💬 Написать администратору</a>`;\n    if(deviceCard)deviceCard.insertAdjacentElement('afterend',card);\n  }\n  const e=document.getElementById('pay-error');\n  if(e){e.textContent=reason||'Причина: нарушение правил использования сайта.';e.style.color='#fca5a5';}\n}\nfunction hidePaywall(){document.getElementById('paywall').classList.add('hidden')}\nfunction clearPayMessages(){\n  const e=document.getElementById('pay-error'),s=document.getElementById('pay-success-msg');\n  if(e){e.textContent='';e.style.color='';}\n  if(s){s.textContent='';s.classList.add('hidden');}\n}\nfunction showPayError(msg){const e=document.getElementById('pay-error');if(e)e.textContent=msg||'';}\nfunction openActivationPanel(){showPaywall('Для активации оплатите 30 000 сум на карту 5614 6805 7717 0398, затем отправьте чек, Telegram ID и ID устройства @nurislombekm.');}\nfunction copyUserId(){navigator.clipboard?.writeText(String(tgUserId||''))}\nfunction copyDeviceId(){navigator.clipboard?.writeText(String(getDeviceFingerprint()))}\nfunction copyCardNumber(){\n  navigator.clipboard?.writeText('5614 6805 7717 0398');\n  const e=document.getElementById('pay-error');if(e){e.textContent='Номер карты скопирован: 5614 6805 7717 0398';e.style.color='#38bdf8';}\n}\nfunction copySubscriptionData(){\n  const text=`Здравствуйте! Хочу активировать подписку.\\nСумма оплаты: 30 000 сум\\nКарта: 5614 6805 7717 0398\\nTelegram ID: ${cleanUserId(tgUserId)||'-'}\\nID устройства: ${getDeviceFingerprint()}\\n${getDeviceSummary()}`;\n  navigator.clipboard?.writeText(text);\n  const e=document.getElementById('pay-error');if(e){e.textContent='Данные скопированы. Отправьте их вместе с чеком @nurislombekm.';e.style.color='#38bdf8';}\n}\n\n\n/* ════════════════════════════════════════════════\n   LOADER\n════════════════════════════════════════════════ */\nfunction sleep(ms){return new Promise(r=>setTimeout(r,ms))}\nfunction showAccessLoader(t='Загрузка...'){document.getElementById('auth-loading-text').innerText=t;document.getElementById('auth-loading').classList.remove('hidden')}\nfunction hideAccessLoader(){document.getElementById('auth-loading').classList.add('hidden')}\n\n/* ════════════════════════════════════════════════\n   TEST LOGIC\n════════════════════════════════════════════════ */\nfunction cleanSubjectKey(key){return String(key||'macro').replace(/[^a-zA-Z0-9а-яА-ЯёЁ_-]/g,'_')||'macro'}\nfunction getSubjectEntries(data){\n  const subs=(data?.subjects)||subjects||{};\n  const entries=Object.entries(subs).filter(([,sub])=>sub&&typeof sub==='object');\n  if(entries.length)return entries;\n  return [['macro',{title:'Маркетинг',short:'Маркетинг',emoji:'📚',tests:Array.isArray(data)?data:[]}]];\n}\nfunction getSavedSubjectKey(){return localStorage.getItem('quizbot_subject_key_v1')||''}\nfunction getPrimarySubjectEntry(data){\n  const entries=getSubjectEntries(data);\n  const saved=getSavedSubjectKey();\n  if(saved){const found=entries.find(([k])=>String(k)===String(saved));if(found)return found;}\n  const current=window.currentSubjectKey;\n  if(current){const found=entries.find(([k])=>String(k)===String(current));if(found)return found;}\n  return entries.find(([k])=>k==='macro')||entries[0];\n}\nfunction getSubjectTitle(){return window.currentSubjectTitle||'Маркетинг'}\nfunction getSubjectShort(){return window.currentSubjectShort||getSubjectTitle()}\nfunction getSubjectEmoji(){return window.currentSubjectEmoji||'📚'}\nfunction fillSubjectSelect(){\n  const sel=document.getElementById('subject-select');if(!sel)return;\n  const entries=getSubjectEntries({subjects});\n  sel.innerHTML=entries.map(([key,sub])=>{\n    const title=sub?.short||sub?.title||sub?.name||key;\n    const emoji=sub?.emoji||'📚';\n    return `<option value=\"${escapeHtml(key)}\">${escapeHtml(emoji+' '+title)}</option>`;\n  }).join('');\n  sel.value=window.currentSubjectKey||entries[0]?.[0]||'macro';\n  sel.disabled=entries.length<2;\n}\nfunction setCurrentSubject(key,opts={}){\n  const entries=getSubjectEntries({subjects});\n  let pair=entries.find(([k])=>String(k)===String(key));\n  if(!pair)pair=entries.find(([k])=>k==='macro')||entries[0]||['macro',{title:'Маркетинг',short:'Маркетинг',emoji:'📚',tests:[]}];\n  const [realKey,sub]=pair;\n  const title=sub?.title||sub?.name||realKey||'Маркетинг';\n  const short=sub?.short||title;\n  const emoji=sub?.emoji||'📚';\n  window.currentSubjectKey=realKey;window.currentSubjectTitle=title;window.currentSubjectShort=short;window.currentSubjectEmoji=emoji;\n  localStorage.setItem('quizbot_subject_key_v1',realKey);\n  database=normalizeTests({subjects});\n  document.title='QuizBot · '+title;\n  document.querySelectorAll('.splash-sub').forEach(el=>el.textContent=title);\n  document.querySelectorAll('.welcome-subject').forEach(el=>el.textContent=title);\n  const meta=document.getElementById('test-meta');if(meta)meta.textContent=title;\n  const total=document.getElementById('total-count');if(total)total.innerText=database.length;\n  fillSubjectSelect();\n  updateProgressUI?.();\n  if(!opts.keepSession){clearActiveSession?.();document.getElementById('resume-card')?.classList.add('hidden');}\n}\nfunction switchSubject(key){\n  if(String(key)===String(window.currentSubjectKey))return;\n  setCurrentSubject(key,{keepSession:false});\n  showConfigError('Предмет изменён: '+getSubjectTitle()+'. Можно начинать тест.');\n  setTimeout(hideConfigError,1800);\n}\nfunction applySubjectMeta(data){\n  subjects=data?.subjects||subjects||{};\n  const [key]=getPrimarySubjectEntry({subjects});\n  setCurrentSubject(key,{keepSession:true});\n}\nfunction normalizeTests(data){\n  let tests=[];\n  if(Array.isArray(data))tests=data;\n  else{\n    const subs=data?.subjects||subjects||{};\n    const key=window.currentSubjectKey || getPrimarySubjectEntry({subjects:subs})?.[0] || 'macro';\n    const sub=subs[key] || getPrimarySubjectEntry({subjects:subs})?.[1] || {};\n    tests=Array.isArray(sub?.tests)?sub.tests:[];\n  }\n  const sk=cleanSubjectKey(window.currentSubjectKey||'macro');\n  return tests.map((q,i)=>({...q,num:i+1,id:q.id||`${sk}-q-${i+1}`,answer:Number(q.answer)||0,generated:!!q.generated,options:q.options||[]}));\n}\nasync function loadTests(){\n  const data=await fetchJsonSafe(apiUrl('/api/tests'),null,5000,60000);\n  if(!data)throw new Error('База вопросов не загрузилась из backend API');\n  subjects=data.subjects||{};applySubjectMeta(data);\n  document.getElementById('total-count').innerText=database.length;\n  updateProgressUI();\n}\nfunction setOrderMode(m){orderMode=m;document.getElementById('order-random').classList.toggle('active',m==='random');document.getElementById('order-seq').classList.toggle('active',m==='sequential')}\nfunction setRunMode(mode){\n  runMode=(mode==='notime'||mode==='real')?mode:'normal';\n  noTime=runMode==='notime';\n  ['normal','no-time','real'].forEach(m=>document.getElementById('mode-'+m)?.classList.toggle('active',runMode===(m==='no-time'?'notime':m)));\n  const lockReal=runMode==='real';\n  const tg=document.getElementById('time-group');if(tg)tg.classList.toggle('disabled-look',noTime||lockReal);\n  const cg=document.getElementById('count-group');if(cg)cg.classList.toggle('disabled-look',lockReal);\n  if(lockReal){\n    const tc=document.getElementById('time-custom');\n    const cs=document.getElementById('count-select'),cc=document.getElementById('count-custom');\n    if(tc){tc.value='';tc.placeholder='30 минут';tc.disabled=true}\n    if(cs){cs.value='25';cs.disabled=true}if(cc){cc.value='';cc.placeholder='25';cc.disabled=true}\n  }else{\n    ['time-custom','count-select','count-custom'].forEach(id=>{const el=document.getElementById(id);if(el)el.disabled=false});\n    const tc=document.getElementById('time-custom'),cc=document.getElementById('count-custom');\n    if(tc){tc.disabled=noTime;tc.placeholder='600';if(!noTime && !tc.value)tc.value='600';}\n    if(cc)cc.placeholder='своё';\n  }\n}\nfunction onTimeSelectChange(){return true}\nfunction getChosenSeconds(){if(noTime)return 0;const custom=parseInt(document.getElementById('time-custom')?.value||'600',10);return custom>0?custom:600}\nfunction getChosenPool(){\n  const type=(document.getElementById('count-select')?.value||'all');\n  let pool=[...database],sourceLabel='Все вопросы';\n  if(type==='favorites'){const fav=getFavorites();pool=database.filter(q=>fav.some(f=>getQuestionId(f)===getQuestionId(q)));sourceLabel='Избранные вопросы'}\n  else if(type==='mistakes'){const ids=getMistakes();pool=database.filter(q=>ids.includes(getQuestionId(q)));sourceLabel='Работа над ошибками'}\n  const from=Math.max(1,parseInt(document.getElementById('range-from')?.value||'1',10)||1);\n  let to=parseInt(document.getElementById('range-to')?.value||String(database.length),10);\n  if(!to||to<from)to=database.length;\n  pool=pool.filter(q=>{const n=parseInt(q.num||0,10);return !n||(n>=from&&n<=to)});\n  return{type,pool,sourceLabel,from,to};\n}\nfunction getChosenCount(poolLength,type){\n  const custom=parseInt(document.getElementById('count-custom')?.value||'',10);if(custom>0)return clamp(custom,1,poolLength);\n  if(['20','25','30','40'].includes(type))return clamp(parseInt(type,10),1,poolLength);\n  return poolLength;\n}\nfunction getQuestionId(q){return String(q.id||q.num||q.question)}\nfunction shuffle(a){const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}\nfunction shuffleQuestionOptions(q){\n  const opts=Array.isArray(q.options)?q.options:[];\n  const answerIndex=Number.isFinite(Number(q.answer))?Number(q.answer):0;\n  if(opts.length<2)return {...q,options:[...opts],answer:answerIndex};\n  const mixed=shuffle(opts.map((text,i)=>({text,i})));\n  const newAnswer=mixed.findIndex(x=>x.i===answerIndex);\n  return {...q,options:mixed.map(x=>x.text),answer:newAnswer>=0?newAnswer:answerIndex,answerText:opts[answerIndex]||q.answerText||''};\n}\nfunction clamp(n,min,max){return Math.max(min,Math.min(max,n))}\n\nfunction startTest(){\n  hideConfigError();\n  if(runMode==='real'){startRealExam();return}\n  const{type,pool,sourceLabel,from,to}=getChosenPool();\n  if(!pool.length){showConfigError(type==='mistakes'?'Ошибок пока нет.':type==='favorites'?'В избранном нет вопросов.':'В диапазоне нет вопросов.');return}\n  const count=getChosenCount(pool.length,type);\n  let selected=orderMode==='random'?shuffle(pool).slice(0,count):pool.slice(0,count);\n  selected=selected.map(shuffleQuestionOptions);\n  if(!selected.length){showConfigError('Не удалось собрать тест.');return}\n  const totalSeconds=getChosenSeconds();\n  if(!noTime && totalSeconds<=0){showConfigError('Укажите время теста в секундах. Например: 600');return}\n  sessionQuestions=selected;currentIdx=0;\n  userAnswers=Array(selected.length).fill(null);confirmed=Array(selected.length).fill(false);\n  perQuestionTime=totalSeconds;\n  timeLeft=noTime?0:totalSeconds;\n  const modeTitle=runMode==='notime'?'Тест без времени':'Обычный тест';\n  currentTestMeta={date:new Date().toLocaleString(),subject:getSubjectTitle(),mode:sourceLabel==='Все вопросы'?modeTitle:`${modeTitle} · ${sourceLabel}`,range:`${from}-${to}`,order:orderMode==='random'?'Случайный':'По порядку',noTime,timeLimitSeconds:perQuestionTime};\n  showScreen('test-screen');document.getElementById('test-meta').innerText=`${sourceLabel} · ${currentTestMeta.order}`;\n  renderQuestion();\n  if(noTime){clearInterval(timerInterval);document.getElementById('timer-display').innerText='Без времени'}else startTimer();\n  saveActiveSession();\n}\nfunction renderQuestion(){\n  const q=sessionQuestions[currentIdx];if(!q)return;\n  document.getElementById('gen-badge-test').innerHTML=q.generated?'<div class=\"badge-generated\">Ответ сгенерирован</div>':'';\n  document.getElementById('q-index').innerText=`Вопрос ${currentIdx+1} из ${sessionQuestions.length}`;\n  document.getElementById('question').innerText=q.question;\n  const favBtn=document.getElementById('fav-current');favBtn.innerText=isFav(q)?'★':'☆';favBtn.classList.toggle('active',isFav(q));\n  const list=document.getElementById('options');list.innerHTML='';\n  q.options.forEach((opt,i)=>{\n    const li=document.createElement('li');li.className='option';li.innerText=opt;\n    if(userAnswers[currentIdx]===i)li.classList.add('selected');\n    if(confirmed[currentIdx]){if(i===q.answer)li.classList.add('correct');else if(i===userAnswers[currentIdx])li.classList.add('wrong')}\n    li.onclick=()=>{if(confirmed[currentIdx])return;userAnswers[currentIdx]=i;saveActiveSession();renderQuestion()};\n    list.appendChild(li);\n  });\n  const isLast=currentIdx===sessionQuestions.length-1;\n  const prev=document.getElementById('prev-btn'),next=document.getElementById('next-btn'),skip=document.getElementById('skip-btn'),finish=document.getElementById('finish-btn'),actions=document.querySelector('.question-actions');\n  [prev,next,skip,finish].forEach(b=>{b.classList.remove('wide');b.classList.add('hidden')});\n  actions.classList.remove('one','two');\n  document.getElementById('accept-btn').classList.toggle('hidden',confirmed[currentIdx]||userAnswers[currentIdx]===null);\n  if(!confirmed[currentIdx]){\n    if(currentIdx===0){actions.classList.add('one');skip.classList.remove('hidden');skip.classList.add('wide')}\n    else{actions.classList.add('two');prev.classList.remove('hidden');skip.classList.remove('hidden')}\n  }else if(isLast){\n    if(currentIdx===0){actions.classList.add('one');finish.classList.remove('hidden');finish.classList.add('wide')}\n    else{actions.classList.add('two');prev.classList.remove('hidden');finish.classList.remove('hidden')}\n  }else{\n    if(currentIdx===0){actions.classList.add('one');next.classList.remove('hidden');next.classList.add('wide')}\n    else{actions.classList.add('two');prev.classList.remove('hidden');next.classList.remove('hidden')}\n  }\n  saveActiveSession();\n}\nfunction acceptAnswer(){if(userAnswers[currentIdx]===null)return;confirmed[currentIdx]=true;saveActiveSession();renderQuestion()}\nfunction nextQuestion(){if(currentIdx<sessionQuestions.length-1){currentIdx++;saveActiveSession();renderQuestion()}else finishTest()}\nfunction prevQuestion(){if(currentIdx>0){currentIdx--;saveActiveSession();renderQuestion()}}\nfunction startTimer(){\n  clearInterval(timerInterval);let lastSaved=0;\n  const tick=()=>{\n    let m=Math.floor(timeLeft/60),s=timeLeft%60;\n    document.getElementById('timer-display').innerText=`${m}:${s<10?'0'+s:s}`;\n    const now=Date.now();if(now-lastSaved>8000){lastSaved=now;saveActiveSession()}\n    if(timeLeft<=0){finishTest();return}timeLeft--;\n  };\n  tick();timerInterval=setInterval(tick,1000);\n}\nfunction confirmFinish(){\n  const answered=confirmed.filter(Boolean).length;\n  if(!answered){if(confirm('Вы ещё не подтвердили ни одного ответа. Завершить тест без результата?')){clearActiveSession();backToMenu()}return}\n  if(confirm(`Завершить тест досрочно? Засчитано подтверждённых: ${answered}.`))finishTest();\n}\nfunction finishTest(){\n  clearInterval(timerInterval);if(!sessionQuestions.length)return;\n  const answeredIdx=confirmed.map((v,i)=>v?i:null).filter(i=>i!==null);\n  if(!answeredIdx.length){clearActiveSession();showScreen('start-screen');showConfigError('Тест не сохранён: нет подтверждённых ответов.');return}\n  let correct=0;answeredIdx.forEach(i=>{if(userAnswers[i]===sessionQuestions[i].answer)correct++});\n  const total=answeredIdx.length,percent=Math.round(correct*100/total);\n  let solved=getSolved();answeredIdx.forEach(i=>solved.push(getQuestionId(sessionQuestions[i])));setSolved(solved);\n  let mistakeIds=getMistakes();\n  answeredIdx.forEach(i=>{const q=sessionQuestions[i],id=getQuestionId(q),ok=userAnswers[i]===q.answer;if(ok)mistakeIds=mistakeIds.filter(x=>x!==id);else mistakeIds.push(id)});\n  setMistakes(mistakeIds);updateProgressUI();\n  const entry={...currentTestMeta,score:`${correct} / ${total}`,correct,total,plannedTotal:sessionQuestions.length,percent,details:answeredIdx.map((i,n)=>{const q=sessionQuestions[i];return{num:n+1,id:q.id,q:q.question,generated:!!q.generated,user:userAnswers[i]===null?'Пропущено':q.options[userAnswers[i]],correct:q.options[q.answer],isOk:userAnswers[i]===q.answer}})};\n  const hist=getHistory();hist.push(entry);setHistory(hist);clearActiveSession();\n  if(window.sendSecureReport) window.sendSecureReport(tgUser,correct,total,tgUserId,{subject:entry.subject,mode:entry.mode,range:entry.range,start:1,end:entry.plannedTotal,order:entry.order,details:entry.details,isPremium:isPremiumUser(),isBlocked:!!banReason(cleanUserId(tgUserId))});\n  document.getElementById('final-score').innerText=entry.score;\n  document.getElementById('final-percent').innerText=`${percent}% правильных · засчитано ${total} из ${sessionQuestions.length}`;\n  lastReviewVisible=false;document.getElementById('review-container').classList.add('hidden');\n  showScreen('result-screen');renderReview(entry.details);\n}\nfunction renderReview(details){document.getElementById('review-container').innerHTML=details.map(d=>`<div class=\"item\" style=\"border-left:5px solid ${d.isOk?'#16a34a':'#dc2626'}\">${d.generated?'<div class=\"badge-generated\">Ответ сгенерирован</div>':''}<div class=\"item-q\">${d.num}. ${escapeHtml(d.q)}</div><div class=\"answer\">✓ ${escapeHtml(d.correct)}</div>${!d.isOk?`<div style=\"color:#f87171;font-weight:1000;font-size:14px;margin-top:6px\">✗ ${escapeHtml(d.user)}</div>`:''}</div>`).join('')}\nfunction toggleReview(){lastReviewVisible=!lastReviewVisible;document.getElementById('review-container').classList.toggle('hidden',!lastReviewVisible)}\n\n/* ════════════════════════════════════════════════\n   FAVORITES / STORAGE\n════════════════════════════════════════════════ */\nfunction isFav(q){return getFavorites().some(f=>getQuestionId(f)===getQuestionId(q))}\nfunction toggleFav(q){let fav=getFavorites();if(isFav(q))fav=fav.filter(f=>getQuestionId(f)!==getQuestionId(q));else fav.push(q);setFavorites(fav)}\nfunction toggleCurrentFavorite(){if(sessionQuestions[currentIdx]){toggleFav(sessionQuestions[currentIdx]);renderQuestion()}}\nfunction storageSubjectKey(){return cleanSubjectKey(window.currentSubjectKey||'macro')}function favKey(){return 'fav_questions_v10_'+storageSubjectKey()}function histKey(){return 'test_history_v10_'+storageSubjectKey()}function solvedKey(){return 'solved_questions_v10_'+storageSubjectKey()}function mistakesKey(){return 'mistake_questions_v10_'+storageSubjectKey()}function activeSessionKey(){return 'active_session_v10_'+storageSubjectKey()}\nfunction getArr(k){try{return JSON.parse(localStorage.getItem(k)||'[]')}catch(e){return[]}}function setArr(k,v){localStorage.setItem(k,JSON.stringify([...new Set(v)]))}\nfunction getFavorites(){return getArr(favKey())}function setFavorites(v){localStorage.setItem(favKey(),JSON.stringify(v))}\nfunction getHistory(){return getArr(histKey())}function setHistory(v){localStorage.setItem(histKey(),JSON.stringify(v))}\nfunction getSolved(){return getArr(solvedKey())}function setSolved(v){setArr(solvedKey(),v)}\nfunction getMistakes(){return getArr(mistakesKey())}function setMistakes(v){setArr(mistakesKey(),v)}\nfunction clearActiveSession(){localStorage.removeItem(activeSessionKey())}\n\n/* ════════════════════════════════════════════════\n   REAL EXAM\n════════════════════════════════════════════════ */\nfunction showRealResultModal(correct,total){\n  const wrong=total-correct;\n  document.getElementById('real-correct-count').innerText=correct;\n  document.getElementById('real-wrong-count').innerText=wrong;\n  document.getElementById('real-result-modal').classList.remove('hidden');\n}\nfunction closeRealResultToMenu(){document.getElementById('real-result-modal').classList.add('hidden');backToMenu();}\nfunction viewRealAnswers(){document.getElementById('real-result-modal').classList.add('hidden');renderRealExam();setTimeout(()=>window.scrollTo({top:0,behavior:'smooth'}),50);}\nfunction startRealExam(){\n  let pool=[...database];\n  const from=Math.max(1,parseInt(document.getElementById('range-from')?.value||'1',10)||1);\n  let to=parseInt(document.getElementById('range-to')?.value||String(database.length),10);\n  if(!to||to<from)to=database.length;\n  pool=pool.filter(q=>{const n=parseInt(q.num||0,10);return !n||(n>=from&&n<=to)});\n  if(!pool.length){showConfigError('В диапазоне нет вопросов.');return}\n  realExamQuestions=(orderMode==='random'?shuffle(pool):pool).slice(0,25).map(shuffleQuestionOptions);\n  if(realExamQuestions.length<25){showConfigError(`Только ${realExamQuestions.length} вопросов. Нужно минимум 25.`);return}\n  realExamAnswers=Array(realExamQuestions.length).fill(null);\n  realExamFinished=false;realExamTotalSeconds=1800;realExamTimeLeft=1800;\n  currentTestMeta={date:new Date().toLocaleString(),subject:getSubjectTitle(),mode:'Реальный тест',range:`${from}-${to}`,order:orderMode==='random'?'Случайный':'По порядку',noTime:false,timeLimit:'30 минут'};\n  showScreen('real-exam-screen');\n  document.getElementById('real-back-btn').classList.add('hidden');document.getElementById('real-finish-btn').classList.remove('hidden');\n  renderRealExam();startRealExamTimer();\n}\nfunction renderRealExam(){\n  const cont=document.getElementById('real-list');\n  cont.innerHTML=realExamQuestions.map((q,qi)=>{\n    const selected=realExamAnswers[qi];\n    const opts=q.options.map((opt,oi)=>{\n      let cls='real-option';if(selected===oi)cls+=' selected';\n      if(realExamFinished){if(oi===q.answer)cls+=' correct';else if(selected===oi&&selected!==q.answer)cls+=' wrong';}\n      return `<label class=\"${cls}\"><input type=\"radio\" name=\"real-q-${qi}\" ${selected===oi?'checked':''} ${realExamFinished?'disabled':''} onchange=\"selectRealAnswer(${qi},${oi})\"><span>${String.fromCharCode(65+oi)}) ${escapeHtml(opt)}</span></label>`;\n    }).join('');\n    let note='';\n    if(realExamFinished){\n      if(selected===null)note=`<div class=\"real-no-answer\">Нет ответа. Правильный: ${escapeHtml(q.options[q.answer])}</div>`;\n      else note=`<div class=\"real-answer-note\">Правильный ответ: ${escapeHtml(q.options[q.answer])}</div>`;\n    }\n    return `<div class=\"real-q\">${q.generated?'<div class=\"badge-generated\">Ответ сгенерирован</div>':''}<div class=\"real-q-title\">${qi+1}. ${escapeHtml(q.question)}</div><div class=\"real-options\">${opts}</div>${note}</div>`;\n  }).join('');\n  const answered=realExamAnswers.filter(x=>x!==null).length;\n  document.getElementById('real-meta').innerText=realExamFinished?`Завершено · отвечено ${answered} из ${realExamQuestions.length}`:`${realExamQuestions.length} вопросов · отвечено ${answered} · ответы после завершения`;\n}\nfunction selectRealAnswer(qi,oi){if(realExamFinished)return;realExamAnswers[qi]=oi;renderRealExam()}\nfunction startRealExamTimer(){\n  clearInterval(realExamTimer);\n  const tick=()=>{\n    if(realExamFinished){clearInterval(realExamTimer);return}\n    const m=Math.floor(realExamTimeLeft/60),s=realExamTimeLeft%60;\n    const timeText=`${m}:${s<10?'0'+s:s}`;\n    const mainTimer=document.getElementById('real-timer');\n    if(mainTimer)mainTimer.innerText=timeText;\n    const pct=Math.max(0,realExamTimeLeft/realExamTotalSeconds*100);\n    const mainFill=document.getElementById('real-line-fill');\n    if(mainFill)mainFill.style.width=pct+'%';\n    const fixedTimer=document.getElementById('real-fixed-time');\n    if(fixedTimer)fixedTimer.innerText=timeText;\n    const fixedFill=document.getElementById('real-fixed-fill');\n    if(fixedFill)fixedFill.style.width=pct+'%';\n    if(realExamTimeLeft<=0){finishRealExam(true);return}\n    realExamTimeLeft--;\n  };\n  tick();\n  realExamTimer=setInterval(tick,1000);\n}\nfunction confirmFinishRealExam(){if(realExamFinished)return;const answered=realExamAnswers.filter(x=>x!==null).length;if(confirm(`Завершить реальный тест? Отвечено ${answered} из ${realExamQuestions.length}.`))finishRealExam(false)}\nfunction finishRealExam(auto=false){\n  if(realExamFinished)return;clearInterval(realExamTimer);realExamFinished=true;\n  let correct=0;realExamQuestions.forEach((q,i)=>{if(realExamAnswers[i]===q.answer)correct++});\n  const total=realExamQuestions.length,percent=Math.round(correct*100/total);\n  let solved=getSolved();realExamQuestions.forEach(q=>solved.push(getQuestionId(q)));setSolved(solved);\n  let mistakeIds=getMistakes();\n  realExamQuestions.forEach((q,i)=>{const id=getQuestionId(q),ok=realExamAnswers[i]===q.answer;if(ok)mistakeIds=mistakeIds.filter(x=>x!==id);else mistakeIds.push(id)});\n  setMistakes(mistakeIds);updateProgressUI();\n  const entry={...currentTestMeta,mode:auto?'Реальный тест · время вышло':'Реальный тест',score:`${correct} / ${total}`,correct,total,plannedTotal:total,percent,details:realExamQuestions.map((q,i)=>({num:i+1,id:q.id,q:q.question,generated:!!q.generated,user:realExamAnswers[i]===null?'Нет ответа':q.options[realExamAnswers[i]],correct:q.options[q.answer],isOk:realExamAnswers[i]===q.answer}))};\n  const hist=getHistory();hist.push(entry);setHistory(hist);\n  if(window.sendSecureReport) window.sendSecureReport(tgUser,correct,total,tgUserId,{subject:entry.subject,mode:entry.mode,range:entry.range,order:entry.order,details:entry.details,isPremium:isPremiumUser(),isBlocked:!!banReason(cleanUserId(tgUserId))});\n  document.getElementById('real-finish-btn').classList.add('hidden');document.getElementById('real-back-btn').classList.remove('hidden');\n  document.getElementById('real-line-fill').style.width='0%';\n  document.getElementById('real-timer').innerText=auto?'Время вышло':'Завершено';\n  renderRealExam();showRealResultModal(correct,total);\n}\n\n/* ════════════════════════════════════════════════\n   LIST / STUDY / HISTORY\n════════════════════════════════════════════════ */\nfunction initStudy(){showListScreen('Изучить тесты · '+getSubjectTitle(),database,true)}\nfunction showFavorites(){showListScreen('Избранное · '+getSubjectTitle(),getFavorites(),true)}\nfunction showMistakeList(){const ids=getMistakes();showListScreen('Ошибки · '+getSubjectTitle(),database.filter(q=>ids.includes(getQuestionId(q))),true)}\nfunction showHistory(){\n  showScreen('list-screen');document.getElementById('list-title').innerText='История · '+getSubjectTitle();\n  document.getElementById('search-box').classList.add('hidden');document.getElementById('study-options-row').classList.add('hidden');\n  const cont=document.getElementById('list-content'),hist=getHistory();\n  if(!hist.length){cont.innerHTML='<div class=\"card empty\">История пока пуста</div>';return}\n  cont.innerHTML=hist.slice().reverse().map((h,ri)=>{const idx=hist.length-1-ri;return `<div class=\"item\"><div style=\"display:flex;justify-content:space-between;gap:10px;align-items:center\"><strong>${h.score}</strong><strong style=\"color:#22c55e\">${h.percent}%</strong></div><div class=\"history-meta\"><div class=\"pill\">📚 ${escapeHtml(h.subject||'')}</div><div class=\"pill\">📅 ${escapeHtml(h.date)}</div><div class=\"pill\">🧩 ${escapeHtml(h.mode)}</div><div class=\"pill\"># ${escapeHtml(h.range||'')}</div></div><button class=\"btn btn-gray btn-full btn-small\" onclick=\"viewHistoryDetail(${idx})\">Разбор попытки</button></div>`}).join('');\n}\nfunction viewHistoryDetail(index){const h=getHistory()[index];showScreen('result-screen');document.getElementById('final-score').innerText=h.score;document.getElementById('final-percent').innerText=`${h.percent}% · ${h.date}`;renderReview(h.details||[]);document.getElementById('review-container').classList.remove('hidden');lastReviewVisible=true}\nfunction showListScreen(title,data,withSearch){showScreen('list-screen');document.getElementById('list-title').innerText=title;document.getElementById('search-box').classList.toggle('hidden',!withSearch);document.getElementById('search-box').value='';const row=document.getElementById('study-options-row');row.classList.toggle('hidden',!title.startsWith('Изучить тесты'));currentDataView=data;renderDataList(data)}\nfunction renderDataList(data){\n  const cont=document.getElementById('list-content');\n  const showOptions=Boolean(document.getElementById('study-show-options')?.checked)&&document.getElementById('list-title').innerText.startsWith('Изучить тесты');\n  if(!data.length){cont.innerHTML='<div class=\"card empty\">Ничего не найдено</div>';return}\n  cont.innerHTML=data.map(q=>{\n    const safeId=String(getQuestionId(q)).replace(/'/g,\"\\\\'\");\n    let body='';\n    if(document.getElementById('list-title').innerText.startsWith('Изучить тесты')){\n      body=showOptions?`<div class=\"study-options\">${q.options.map((o,i)=>`<div class=\"study-opt ${i===q.answer?'right':''}\">${String.fromCharCode(65+i)}) ${escapeHtml(o)}</div>`).join('')}</div>`:`<div class=\"answer\">Ответ: ${escapeHtml(q.options[q.answer])}</div>`;\n    }else{body=`<div class=\"answer\">Ответ: ${escapeHtml(q.options[q.answer])}</div>`;}\n    return `<div class=\"item\">${q.generated?'<div class=\"badge-generated\">Ответ сгенерирован</div>':''}<div class=\"item-top\"><div class=\"item-q\">${q.num||''}. ${escapeHtml(q.question)}</div><button class=\"star ${isFav(q)?'active':''}\" onclick=\"toggleFavFromList('${safeId}')\">${isFav(q)?'★':'☆'}</button></div>${body}</div>`;\n  }).join('');\n}\nfunction toggleFavFromList(id){const q=database.find(x=>String(getQuestionId(x))===String(id))||getFavorites().find(x=>String(getQuestionId(x))===String(id));if(q){toggleFav(q);const title=document.getElementById('list-title').innerText;renderDataList(title.startsWith('Избранное')?getFavorites():currentDataView)}}\nfunction filterList(){const val=document.getElementById('search-box').value.toLowerCase().trim();const filtered=currentDataView.filter(q=>String(q.num||q.id).includes(val)||q.question.toLowerCase().includes(val)||q.options.join(' ').toLowerCase().includes(val));renderDataList(filtered)}\n\n/* ════════════════════════════════════════════════\n   PROGRESS / UI\n════════════════════════════════════════════════ */\nfunction updateProgressUI(){ /* Removed the unused mistake/progress counters from the UI. */ }\nfunction showConfigError(msg){const e=document.getElementById('config-error');e.innerText=msg;e.classList.remove('hidden');e.classList.add('shake');setTimeout(()=>e.classList.remove('shake'),350)}\nfunction hideConfigError(){document.getElementById('config-error').classList.add('hidden')}\nfunction escapeHtml(s){return String(s??'').replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[m]||m))}\nfunction showScreen(id){['start-screen','test-screen','real-exam-screen','list-screen','result-screen','admin-screen'].forEach(x=>document.getElementById(x)?.classList.add('hidden'));document.getElementById(id)?.classList.remove('hidden');closeDrawer();try{window.scrollTo({top:0,behavior:'auto'})}catch(e){window.scrollTo(0,0)}if(id==='start-screen'){updateProgressUI();renderLimit();}}\nfunction backToMenu(){clearInterval(timerInterval);clearInterval(realExamTimer);document.getElementById('real-result-modal')?.classList.add('hidden');closeDrawer();showScreen('start-screen')}\n\n/* ════════════════════════════════════════════════\n   SESSION SAVE / RESTORE\n════════════════════════════════════════════════ */\nlet lastSessionSaveAt=0;\nfunction saveActiveSession(force=false){\n  if(!sessionQuestions.length)return;\n  const now=Date.now();if(!force&&now-lastSessionSaveAt<2500)return;\n  lastSessionSaveAt=now;\n  const questionIds=sessionQuestions.map(q=>getQuestionId(q));\n  localStorage.setItem(activeSessionKey(),JSON.stringify({questionIds,currentIdx,userAnswers,confirmed,timeLeft,currentTestMeta,createdAt:now,noTime}));\n}\nfunction getActiveSession(){try{return JSON.parse(localStorage.getItem(activeSessionKey())||'null')}catch(e){return null}}\nfunction restoreQuestionsFromSession(s){\n  if(Array.isArray(s?.sessionQuestions))return s.sessionQuestions;\n  if(Array.isArray(s?.questionIds))return s.questionIds.map(id=>database.find(q=>String(getQuestionId(q))===String(id))).filter(Boolean);\n  return[];\n}\nfunction showResumeIfAny(){\n  const s=getActiveSession();const qs=restoreQuestionsFromSession(s);\n  const confirmedCount=s?.confirmed?.filter(Boolean).length||0;\n  if(s&&qs.length){document.getElementById('resume-card').classList.remove('hidden');document.getElementById('resume-text').innerText=`Сохранено: вопрос ${(s.currentIdx||0)+1} из ${qs.length}. Подтверждено: ${confirmedCount}.`}\n}\nfunction continueSavedSession(){\n  const s=getActiveSession();if(!s)return;\n  sessionQuestions=restoreQuestionsFromSession(s);\n  if(!sessionQuestions.length){discardSavedSession();showConfigError('Сохранённая попытка устарела. Начните заново.');return}\n  currentIdx=s.currentIdx||0;userAnswers=s.userAnswers||Array(sessionQuestions.length).fill(null);\n  confirmed=s.confirmed||Array(sessionQuestions.length).fill(false);timeLeft=s.timeLeft||0;\n  currentTestMeta=s.currentTestMeta||{};noTime=!!s.noTime;\n  showScreen('test-screen');document.getElementById('test-meta').innerText=`${currentTestMeta.mode||'Тест'} · ${currentTestMeta.order||''}`;\n  renderQuestion();\n  if(noTime){document.getElementById('timer-display').innerText='Без времени'}else startTimer();\n}\nfunction discardSavedSession(){clearActiveSession();document.getElementById('resume-card').classList.add('hidden')}\n\n/* ════════════════════════════════════════════════\n   THEME / DRAWER / MISC\n════════════════════════════════════════════════ */\nfunction toggleTheme(){const light=!document.body.classList.contains('light');document.body.classList.toggle('light',light);localStorage.setItem('eco_theme',light?'light':'dark');document.getElementById('theme-btn').innerText=light?'☀️':'🌙'}\nfunction applyTheme(){const t=localStorage.getItem('eco_theme')||'light';document.body.classList.toggle('light',t==='light');document.getElementById('theme-btn').innerText=t==='light'?'☀️':'🌙'}\nfunction toggleDrawer(){document.getElementById('side-drawer').classList.toggle('open');document.getElementById('drawer-backdrop').classList.toggle('open')}\nfunction closeDrawer(){document.getElementById('side-drawer')?.classList.remove('open');document.getElementById('drawer-backdrop')?.classList.remove('open')}\nfunction buttonPop(e){const b=(e?.target||window.event?.target)?.closest?.('button');if(b){b.classList.remove('btn-click');void b.offsetWidth;b.classList.add('btn-click')}}\ndocument.addEventListener('click',e=>{if(e.target.closest('button'))buttonPop(e)});\n\n/* ════════════════════════════════════════════════\n   INIT\n════════════════════════════════════════════════ */\nfunction waitForTelegram(maxMs=700){\n  return new Promise(resolve=>{\n    const start=Date.now();\n    const tick=()=>{if(window.Telegram?.WebApp||Date.now()-start>=maxMs)return resolve(window.Telegram?.WebApp||null);setTimeout(tick,50);};\n    tick();\n  });\n}\n\n(async function init(){\n  let splashEl=document.getElementById('splash');\n  setTimeout(()=>{if(splashEl){splashEl.classList.add('hide');setTimeout(()=>splashEl?.remove(),450);}},1000);\n  try{\n    applyTheme();\n    setRunMode('normal');onTimeSelectChange();\n    const twa=await waitForTelegram(700);\n    if(twa){\n      twa.expand?.();\n      const u=twa.initDataUnsafe?.user;\n      if(u){tgUserId=String(u.id||'');tgUser=`${u.first_name||'Пользователь'} (@${u.username||'id'+u.id})`;}\n    }\n    const ubInit=document.getElementById('user-badge');\n    if(ubInit){ubInit.innerHTML='';ubInit.classList.add('hidden');}\n    document.getElementById('pay-user-id').innerText=tgUserId||'Откройте через Telegram Mini App';\n\n    showScreen('start-screen');\n\n    // Load tests silently\n    loadTests().then(()=>{\n      hideConfigError();updateProgressUI();showResumeIfAny();renderLimit();\n    }).catch(err=>{\n      showConfigError('Не загрузилась база вопросов. Проверьте BACKEND_URL в env.js и Cloudflare Worker.');\n    });\n\n    // Load access lists and check\n    loadLists().then(async()=>{\n      const id=cleanUserId(tgUserId);\n      const blockReason=id?banReason(id):'';\n      if(blockReason){clearKey();showBlockedPaywall(blockReason);}\n      const fromFile=id&&hasPremium(id)&&!blockReason;\n      updatePremiumBadge(!!fromFile);\n      renderLimit();\n      sendSiteOpenReportOnce(!!fromFile,!!blockReason,blockReason);\n      // Two-device check for premium users only (no reason to alert free users)\n      if(fromFile&&tgUserId) checkTwoDevices();\n    }).catch(()=>{});\n\n  }catch(e){\n    showScreen('start-screen');\n    showConfigError('Ошибка запуска: '+(e.message||e));\n  }finally{\n    hideAccessLoader();\n  }\n})();\n</script>\n<script src=\"./eco-upgrade.js?v=30\" defer></script>\n<script src=\"./eco-final-patch.js?v=30\" defer></script>\n<script src=\"./admin-embed.js?v=7\" defer></script>\n<script src=\"./activity-tracker.js?v=1\" defer></script>\n</body>\n</html>\n","/tele-secure.js":"(function () {\n  \"use strict\";\n\n  function safe(value) {\n    return String(value ?? \"\")\n      .replace(/[<>&]/g, \"\")\n      .trim();\n  }\n\n  function getEnv() {\n    return window.__APP_ENV || {};\n  }\n\n  function apiUrl(path) {\n    const env = getEnv();\n    const base = String(env.BACKEND_URL || env.REPORT_PROXY_URL || '').replace(/\\/+$/, '');\n    if (/^https?:\\/\\//i.test(path)) return path;\n    return base ? base + '/' + String(path || '').replace(/^\\/+/,'') : path;\n  }\n\n  function telegramInitData() {\n    try { return window.Telegram?.WebApp?.initData || ''; } catch (e) { return ''; }\n  }\n\n  async function sendReport(text) {\n    const env = getEnv();\n\n    const reportUrl = env.REPORT_URL || apiUrl('/api/report');\n    if (!reportUrl) {\n      console.warn(\"BACKEND_URL не указан в env.js\");\n      return false;\n    }\n\n    try {\n      const res = await fetch(reportUrl, {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\"\n        },\n        body: JSON.stringify({\n          text: String(text || \"\").slice(0, 3900),\n          initData: telegramInitData()\n        })\n      });\n\n      if (!res.ok) {\n        console.warn(\"Report proxy error:\", res.status, await res.text());\n        return false;\n      }\n\n      return true;\n    } catch (e) {\n      console.warn(\"Report send failed:\", e);\n      return false;\n    }\n  }\n\n  function getTgUser() {\n    try {\n      return window.Telegram?.WebApp?.initDataUnsafe?.user || null;\n    } catch (e) {\n      return null;\n    }\n  }\n\n  function getRealTelegramId(userId) {\n    const tgUser = getTgUser();\n    const id = String(userId || tgUser?.id || \"\").replace(/\\D+/g, \"\");\n    return id || \"\";\n  }\n\n  function nowText() {\n    const d = new Date();\n    const p = (n) => String(n).padStart(2, \"0\");\n\n    return (\n      p(d.getDate()) +\n      \".\" +\n      p(d.getMonth() + 1) +\n      \".\" +\n      d.getFullYear() +\n      \", \" +\n      p(d.getHours()) +\n      \":\" +\n      p(d.getMinutes()) +\n      \":\" +\n      p(d.getSeconds())\n    );\n  }\n\n  function getUserInfo(userProfile, userId, meta) {\n    const tgUser = getTgUser() || {};\n\n    const firstName = meta?.firstName || tgUser.first_name || \"\";\n    const lastName = meta?.lastName || tgUser.last_name || \"\";\n\n    let name = [firstName, lastName].filter(Boolean).join(\" \").trim();\n\n    if (!name && userProfile) {\n      name = String(userProfile)\n        .replace(/\\s*\\(@[^)]*\\)\\s*/g, \"\")\n        .trim();\n    }\n\n    if (!name) name = \"Гость\";\n\n    const usernameRaw = meta?.telegramUsername || tgUser.username || \"\";\n    const username = usernameRaw\n      ? \"@\" + String(usernameRaw).replace(/^@/, \"\")\n      : \"-\";\n\n    const id = getRealTelegramId(userId) || \"-\";\n\n    return {\n      name,\n      username,\n      id\n    };\n  }\n\n  function getOSInfo() {\n    const ua = navigator.userAgent || \"\";\n    let os = \"Неизвестно\";\n    let version = \"\";\n\n    const ios =\n      ua.match(/(?:CPU iPhone OS|CPU OS|iPhone OS|OS)\\s+([0-9_]+(?:_[0-9_]+)?)/i) ||\n      ua.match(/Version\\/([0-9.]+)/i);\n\n    const android = ua.match(/Android\\s+([0-9.]+)/i);\n    const windows = ua.match(/Windows NT\\s+([0-9.]+)/i);\n    const mac = ua.match(/Mac OS X\\s+([0-9_]+)/i);\n\n    if (/iPhone|iPad|iPod/i.test(ua)) {\n      os = \"iOS\";\n      if (ios) version = ios[1].replace(/_/g, \".\");\n    } else if (/Android/i.test(ua)) {\n      os = \"Android\";\n      if (android) version = android[1];\n    } else if (/Windows/i.test(ua)) {\n      os = \"Windows\";\n      if (windows) version = windows[1];\n    } else if (/Mac OS X/i.test(ua)) {\n      os = \"macOS\";\n      if (mac) version = mac[1].replace(/_/g, \".\");\n    } else if (/Linux/i.test(ua)) {\n      os = \"Linux\";\n    }\n\n    return version ? `${os} ${version}` : os;\n  }\n\n  function getDeviceInfo() {\n    let timezone = \"Неизвестно\";\n\n    try {\n      timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || \"Неизвестно\";\n    } catch (e) {}\n\n    return {\n      os: getOSInfo(),\n      screen: `${window.screen?.width || \"-\"}x${window.screen?.height || \"-\"}`,\n      language: (navigator.language || \"Неизвестно\").split(\"-\")[0],\n      timezone\n    };\n  }\n\n  async function makeFingerprint() {\n    try {\n      if (typeof window.getDeviceFingerprint === \"function\") {\n        return String(window.getDeviceFingerprint() || \"UNKNOWN\").toUpperCase();\n      }\n\n      const raw = [\n        navigator.userAgent || \"\",\n        navigator.language || \"\",\n        screen.width || \"\",\n        screen.height || \"\",\n        screen.colorDepth || \"\",\n        Intl.DateTimeFormat().resolvedOptions().timeZone || \"\"\n      ].join(\"|\");\n\n      const buf = await crypto.subtle.digest(\n        \"SHA-256\",\n        new TextEncoder().encode(raw)\n      );\n\n      return Array.from(new Uint8Array(buf))\n        .map((b) => b.toString(16).padStart(2, \"0\"))\n        .join(\"\")\n        .slice(0, 10)\n        .toUpperCase();\n    } catch (e) {\n      return \"UNKNOWN\";\n    }\n  }\n\n  function detectStatus(meta) {\n    if (meta?.isBlocked) return \"🚫 Заблокированный пользователь\";\n    if (meta?.isPremium) return \"Премиум пользователь\";\n\n    try {\n      const badge = document.getElementById(\"premium-badge\");\n      const text = badge?.textContent || \"\";\n\n      if (/заблок/i.test(text)) return \"🚫 Заблокированный пользователь\";\n      if (/премиум/i.test(text)) return \"Премиум пользователь\";\n    } catch (e) {}\n\n    return \"Обычный пользователь\";\n  }\n\n  async function baseInfo(userProfile, userId, meta) {\n    const user = getUserInfo(userProfile, userId, meta || {});\n    const device = getDeviceInfo();\n    const fingerprint = await makeFingerprint();\n\n    return {\n      user,\n      device,\n      fingerprint\n    };\n  }\n\n  window.sendVisitNotification = async function (userProfile, userId, meta) {\n    const tgUser = getTgUser();\n    const realId = getRealTelegramId(userId);\n\n    if (!tgUser || !realId) return;\n\n    if (window.__ecoVisitReportSent) return;\n    window.__ecoVisitReportSent = true;\n\n    const data = await baseInfo(userProfile, realId, meta || {});\n    const status = detectStatus(meta || {});\n\n    const text =\n`👁️ ВХОД НА САЙТ\n\n📅 Дата/время: ${nowText()}\n👤 Пользователь: ${safe(data.user.name)}\n🔗 Username: ${safe(data.user.username)}\n🆔 Telegram ID: ${safe(data.user.id)}\n⭐ Статус: ${safe(status)}\n\n📱 ОС: ${safe(data.device.os)}\n🖥️ Экран: ${safe(data.device.screen)}\n🌐 Язык: ${safe(data.device.language)}\n📍 Часовой пояс: ${safe(data.device.timezone)}\n🔑 Fingerprint: ${safe(data.fingerprint)}`;\n\n    await sendReport(text);\n  };\n\n  window.sendSecureReport = async function (\n    userProfile,\n    correct,\n    total,\n    userId,\n    meta\n  ) {\n    const tgUser = getTgUser();\n    const realId = getRealTelegramId(userId);\n\n    if (!tgUser || !realId) return;\n\n    const data = await baseInfo(userProfile, realId, meta || {});\n    const status = detectStatus(meta || {});\n\n    const percent =\n      total > 0 ? Math.round((Number(correct || 0) / Number(total || 1)) * 100) : 0;\n\n    const subject = meta?.subject || \"Тест\";\n    const mode = meta?.mode || \"Обычный тест\";\n    const range = meta?.range || \"-\";\n    const order = meta?.order || \"-\";\n\n    const text =\n`✅ ТЕСТ ЗАВЕРШЁН\n\n📅 Дата/время: ${nowText()}\n👤 Пользователь: ${safe(data.user.name)}\n🔗 Username: ${safe(data.user.username)}\n🆔 Telegram ID: ${safe(data.user.id)}\n⭐ Статус: ${safe(status)}\n\n📚 Предмет: ${safe(subject)}\n🧩 Режим: ${safe(mode)}\n🔢 Диапазон: ${safe(range)}\n🔀 Порядок: ${safe(order)}\n\n📊 Результат: ${correct}/${total}\n📈 Процент: ${percent}%\n\n📱 ОС: ${safe(data.device.os)}\n🖥️ Экран: ${safe(data.device.screen)}\n🌐 Язык: ${safe(data.device.language)}\n📍 Часовой пояс: ${safe(data.device.timezone)}\n🔑 Fingerprint: ${safe(data.fingerprint)}`;\n\n    await sendReport(text);\n  };\n\n  window.sendDeviceControlReport = async function (userProfile, userId, meta) {\n    const tgUser = getTgUser();\n    const realId = getRealTelegramId(userId);\n\n    if (!tgUser || !realId) return;\n\n    const data = await baseInfo(userProfile, realId, meta || {});\n    const status = detectStatus(meta || {});\n\n    const text =\n`⚠️ КОНТРОЛЬ УСТРОЙСТВА\n\n📅 Дата/время: ${nowText()}\n👤 Пользователь: ${safe(data.user.name)}\n🔗 Username: ${safe(data.user.username)}\n🆔 Telegram ID: ${safe(data.user.id)}\n⭐ Статус: ${safe(status)}\n\n📌 Событие: ${safe(meta?.status || \"Подозрительная активность\")}\n📝 Причина: ${safe(meta?.reason || \"-\")}\n\n📱 ОС: ${safe(data.device.os)}\n🖥️ Экран: ${safe(data.device.screen)}\n🌐 Язык: ${safe(data.device.language)}\n📍 Часовой пояс: ${safe(data.device.timezone)}\n🔑 Fingerprint: ${safe(data.fingerprint)}`;\n\n    await sendReport(text);\n  };\n\n  window.sendReportToTelegram = sendReport;\n})();\n","/admin/compact.css":"/* QuizBot owner admin: compact 4-tab interface inside Telegram Mini App */\nbody.admin-embedded .wrap{max-width:760px;padding:7px 8px 18px}\nbody.admin-embedded h1{font-size:19px;letter-spacing:-.3px}\nbody.admin-embedded h2{font-size:16px;margin:0 0 10px}\nbody.admin-embedded .sub{font-size:11px}\nbody.admin-embedded .top{display:flex;align-items:center;gap:12px;margin:0 0 8px}\nbody.admin-embedded .status{padding:6px 8px;font-size:10px;max-width:125px;overflow:hidden;text-overflow:ellipsis;flex-shrink:0}\nbody.admin-embedded .tabs{position:sticky;top:0;z-index:12;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px;background:#08101f;margin:0 0 12px;padding:6px 0 8px;border-bottom:1px solid var(--line);overflow:visible}\nbody.admin-embedded .tab{min-width:0;padding:8px 2px;font-size:11px;line-height:1.25;border-radius:12px;border:1px solid #243653;display:flex;flex-direction:column;align-items:center;gap:4px;color:#bdc9db}\nbody.admin-embedded .tab.active{color:#fff;background:#1748b1;border-color:#5687ee}\nbody.admin-embedded .tab-icon{font-size:17px}\nbody.admin-embedded .card{padding:12px;margin:9px 0;border-radius:14px;box-shadow:none}\nbody.admin-embedded .grid2{gap:10px}\nbody.admin-embedded .btn{padding:10px 12px;border-radius:10px;font-size:13px}\nbody.admin-embedded .btn.compact{padding:7px 11px;background:#1d304c;font-size:12px}\nbody.admin-embedded label{margin:8px 0 4px;font-size:11px}\nbody.admin-embedded input:not([type=checkbox]),body.admin-embedded textarea,body.admin-embedded select{padding:10px;font-size:14px;border-radius:10px}\nbody.admin-embedded .mini{font-size:11px;line-height:1.45}\nbody.admin-embedded .statgrid{gap:7px}\nbody.admin-embedded .stat{padding:9px 8px;border-radius:11px}\nbody.admin-embedded .stat b{font-size:20px}\nbody.admin-embedded .stat span{font-size:10px}\nbody.admin-embedded .section-intro{display:flex;align-items:center;justify-content:space-between;gap:10px}\nbody.admin-embedded .section-intro h2{margin:0}\nbody.admin-embedded .activity-note{margin:10px 0 12px;color:#90a4c3}\nbody.admin-embedded .people-stats{grid-template-columns:repeat(3,minmax(0,1fr))}\nbody.admin-embedded .people-toolbar{display:grid;grid-template-columns:1fr;gap:7px;margin:11px 0}\nbody.admin-embedded .people-list{display:grid;gap:8px}\nbody.admin-embedded .person{border:1px solid #273959;background:#0e1b32;border-radius:14px;padding:11px}\nbody.admin-embedded .person-head{display:flex;justify-content:space-between;align-items:flex-start;gap:8px}\nbody.admin-embedded .person-name{font-size:14px;font-weight:800;color:#edf5ff;word-break:break-word}\nbody.admin-embedded .person-handle{color:#8dccfb;font-size:12px;margin-top:3px;overflow-wrap:anywhere}\nbody.admin-embedded .person-id{color:#b3c4db;font-size:11px;margin-top:7px;font-variant-numeric:tabular-nums}\nbody.admin-embedded .person-time{font-size:11px;color:#a7b7d1;margin-top:5px;line-height:1.4}\nbody.admin-embedded .person-foot{display:flex;align-items:center;justify-content:space-between;gap:7px;margin-top:8px}\nbody.admin-embedded .person-status{font-size:11px;color:#acb9cd}\nbody.admin-embedded .status-recent{color:#81ecc7}\nbody.admin-embedded .status-premium{color:#f9d36d}\nbody.admin-embedded .status-banned{color:#ff9ca6}\nbody.admin-embedded .fold{border:1px solid #26395b;background:#111c30;border-radius:14px;margin:10px 0;padding:0 11px}\nbody.admin-embedded .fold>summary{padding:13px 4px;font-size:13px;font-weight:800;cursor:pointer;list-style:none}\nbody.admin-embedded .fold>summary::-webkit-details-marker{display:none}\nbody.admin-embedded .fold>summary:after{content:'⌄';float:right;font-size:17px;color:#9eb8dd}\nbody.admin-embedded .fold[open]>summary:after{content:'⌃'}\nbody.admin-embedded .fold-hint{display:block;font-size:11px;font-weight:400;margin:4px 0 0;color:#93a6c0}\nbody.admin-embedded .fold>.card,body.admin-embedded .fold>div>.card{border-color:#26395b}\nbody.admin-embedded .fold.dangerous{border-color:rgba(251,77,101,.35)}\nbody.admin-embedded .settings-note{margin:8px 0 16px}\nbody.admin-embedded .settings-heading{margin:0}\nbody.admin-embedded #userCountNote{margin:11px 3px}\nbody.admin-embedded #usersMore{margin:12px 0}\n@media(min-width:520px){\n body.admin-embedded .people-toolbar{grid-template-columns:minmax(0,2fr) minmax(0,1fr)}\n body.admin-embedded .people-list{grid-template-columns:repeat(2,minmax(0,1fr))}\n}\n\nbody.admin-embedded #questions .fold-stack{display:block}\nbody.admin-embedded #questions .question-fold>.card>h2:first-child{display:none}\nbody.admin-embedded .fold-inline{padding:0 8px;margin:10px 0}\nbody.admin-embedded .fold-inline>summary{padding:9px 3px;font-size:12px}\nbody.admin-embedded #banReason{min-height:70px}\n","/admin/compact.js":"/* Compact owner admin — people who used this QuizBot Mini App only.\n   No Telegram online/last-seen data is requested or inferred. */\n'use strict';\nlet visitedUsers=[];\nlet usersVisibleCount=60;\nlet usersRequest=null;\n\nfunction activityTime(d){\n  const n=Date.parse(d||'');\n  return Number.isFinite(n)?new Date(n).toLocaleString('ru-RU',{\n    day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'\n  }):'—';\n}\nfunction activityAge(d){\n  const diff=Date.now()-Date.parse(d||'');\n  if(!Number.isFinite(diff)||diff<0)return 'Неизвестно';\n  if(diff<60000)return 'Только что';\n  if(diff<3600000)return Math.floor(diff/60000)+' мин назад';\n  if(diff<86400000)return Math.floor(diff/3600000)+' ч назад';\n  return Math.floor(diff/86400000)+' дн назад';\n}\nfunction recentlyInApp(user){\n  const age=Date.now()-Date.parse(user?.last_seen||'');\n  return Number.isFinite(age)&&age>=0&&age<=120000;\n}\nasync function refreshUsers(){\n  const target=document.getElementById('userList');\n  if(!target)return;\n  if(usersRequest)return usersRequest;\n  const initData=ownerInitData();\n  if(!initData){\n    target.innerHTML='<div class=\"empty\">Откройте админку внутри QuizBot</div>';\n    return;\n  }\n  if(!visitedUsers.length)target.innerHTML='<div class=\"empty\">Загрузка активности…</div>';\n  usersRequest=(async()=>{\n    try{\n      const res=await fetch('/api/admin/users',{\n        headers:{'X-Telegram-Init-Data':initData},\n        cache:'no-store',credentials:'same-origin'\n      });\n      const data=await res.json().catch(()=>({}));\n      if(!res.ok||!data?.ok)throw new Error(data.error||'Ошибка '+res.status);\n      visitedUsers=Array.isArray(data.users)?data.users:[];\n      const stats=document.getElementById('userStats');\n      if(stats)stats.innerHTML=\n        '<div class=\"stat\"><b>'+visitedUsers.length+'</b><span>Посетили</span></div>'+\n        '<div class=\"stat\"><b>'+(Number(data.stats?.today)||0)+'</b><span>За 24 часа</span></div>'+\n        '<div class=\"stat\"><b>'+(Number(data.stats?.recent)||0)+'</b><span>Недавно</span></div>';\n      renderUsers();\n    }catch(e){\n      target.innerHTML='<div class=\"empty\">Не удалось загрузить: '+escapeHtml(e.message||e)+'</div>';\n      const note=document.getElementById('userCountNote');\n      if(note)note.textContent='Повтори загрузку кнопкой «Обновить».';\n    }finally{\n      usersRequest=null;\n    }\n  })();\n  return usersRequest;\n}\nfunction renderUsers(){\n  const root=document.getElementById('userList');\n  const note=document.getElementById('userCountNote');\n  const more=document.getElementById('usersMore');\n  if(!root||!note||!more)return;\n  const search=String(document.getElementById('userSearch')?.value||'')\n    .toLowerCase().trim().replace(/^@/,'');\n  const filter=document.getElementById('userFilter')?.value||'all';\n  const filtered=visitedUsers.filter(u=>{\n    const query=[u.id,u.username,u.first_name,u.last_name].join(' ').toLowerCase();\n    if(search&&!query.includes(search))return false;\n    const age=Date.now()-Date.parse(u.last_seen||'');\n    if(filter==='recent')return recentlyInApp(u);\n    if(filter==='today')return Number.isFinite(age)&&age>=0&&age<86400000;\n    if(filter==='premium')return !!u.premium;\n    if(filter==='banned')return !!u.banned;\n    return true;\n  });\n  const visible=filtered.slice(0,usersVisibleCount);\n  if(!visible.length){\n    root.innerHTML='<div class=\"empty\">'+(visitedUsers.length?\n      'По этому запросу никого нет':\n      'Пока нет посещений. Пользователи появятся после открытия QuizBot.')+'</div>';\n  }else{\n    root.innerHTML=visible.map(u=>{\n      const name=escapeHtml([u.first_name,u.last_name].filter(Boolean).join(' ')||'Пользователь');\n      const handle=u.username?'@'+escapeHtml(u.username):'Без username';\n      const status=u.banned?\n        '<span class=\"status-banned\">🚫 Бан</span>':\n        u.premium?'<span class=\"status-premium\">💎 Premium</span>':'Обычный';\n      const recent=recentlyInApp(u)?\n        '<span class=\"status-recent\">● Недавно в QuizBot</span>':\n        'Был в QuizBot: '+escapeHtml(activityAge(u.last_seen));\n      return '<div class=\"person\"><div class=\"person-head\"><div><div class=\"person-name\">'+name+\n        '</div><div class=\"person-handle\">'+handle+'</div></div><span class=\"person-status\">'+status+'</span></div>'+\n        '<div class=\"person-id\">Telegram ID: '+escapeHtml(u.id)+'</div>'+\n        '<div class=\"person-time\">'+recent+'<div>Последний вход: '+escapeHtml(activityTime(u.last_opened||u.first_seen))+'</div><div>Последняя активность: '+escapeHtml(activityTime(u.last_seen))+'</div></div>'+\n        '<div class=\"person-controls\">'+\n        '<button type=\"button\" class=\"btn btn-user-premium\" data-user-action=\"'+(u.premium?'remove':'premium')+'\" data-user-id=\"'+escapeHtml(u.id)+'\">'+(u.premium?'Снять 💎':'💎 +30 дней')+'</button>'+\n        '<button type=\"button\" class=\"btn '+(u.banned?'btn-user-unban':'btn-user-ban')+'\" data-user-action=\"'+(u.banned?'unban':'ban')+'\" data-user-id=\"'+escapeHtml(u.id)+'\">'+(u.banned?'Разбанить':'🚫 Бан')+'</button></div>'+\n        '<div class=\"person-foot\"><span class=\"person-status\">Открытий: '+Math.max(0,Number(u.opens)||0)+'</span>'+\n        '<button type=\"button\" class=\"btn compact\" data-manage-user=\"'+escapeHtml(u.id)+'\">Ещё ↗</button></div></div>';\n    }).join('');\n  }\n  root.querySelectorAll('[data-manage-user]').forEach(button=>{\n    button.addEventListener('click',()=>manageUser(button.dataset.manageUser));\n  });\n  more.classList.toggle('hidden',filtered.length<=usersVisibleCount);\n  note.textContent='Показано '+Math.min(filtered.length,usersVisibleCount)+' из '+filtered.length+\n    '. Время — по часовому поясу устройства. «Недавно» означает отметку за 2 минуты, а не Telegram онлайн.';\n}\nfunction showMoreUsers(){\n  usersVisibleCount+=60;\n  renderUsers();\n}\nfunction manageUser(id){\n  const safe=cleanId(id);\n  if(!safe)return;\n  document.getElementById('premId').value=safe;\n  document.getElementById('banId').value=safe;\n  const quick=document.getElementById('quickUserId');\n  if(quick)quick.value=safe;\n  showPane('access');\n  window.scrollTo({top:0,behavior:'smooth'});\n  toast('Пользователь '+safe+' выбран для управления');\n}\n\n/* Keep advanced question import/export available without a long screen. */\nfunction compactQuestionControls(){\n  const controls=document.querySelector('#questions > .grid2');\n  if(!controls||controls.dataset.compactDone==='1')return;\n  controls.dataset.compactDone='1';\n  controls.classList.add('fold-stack');\n  const labels=[\n    ['📥 Импорт вопросов','Добавить вопросы из JSON'],\n    ['📤 Скачать вопросы','Экспортировать базу']\n  ];\n  Array.from(controls.children).forEach((card,index)=>{\n    const item=document.createElement('details');\n    item.className='fold question-fold';\n    const label=document.createElement('summary');\n    const hint=document.createElement('span');\n    hint.className='fold-hint';\n    label.textContent=labels[index]?.[0]||'Дополнительные действия';\n    hint.textContent=labels[index]?.[1]||'';\n    label.appendChild(hint);\n    item.appendChild(label);\n    item.appendChild(card);\n    controls.appendChild(item);\n  });\n}\nif(document.readyState==='loading'){\n  document.addEventListener('DOMContentLoaded',compactQuestionControls,{once:true});\n}else compactQuestionControls();\n","/admin/index.html":"<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\"/>\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"/>\n<title>QuizBot Admin</title>\n<script>\n  // Standalone admin is retired: controls now appear only in the owner's Mini App.\n  const EMBEDDED_ADMIN = new URLSearchParams(location.search).get('embedded') === '1';\n  if (!EMBEDDED_ADMIN) location.replace('/');\n  document.documentElement.classList.add('admin-embed-pending');\n</script>\n<style>\n:root{--bg:#08101f;--card:#111a2f;--card2:#0d1527;--line:#293a5b;--txt:#f8fafc;--muted:#9fb1d0;--blue:#2563eb;--green:#22c55e;--red:#fb4d65;--yellow:#fbbf24;--purple:#7c3aed;--cyan:#06b6d4}*{box-sizing:border-box}body{margin:0;background:linear-gradient(145deg,#08101f,#121d37 60%,#07101d);color:var(--txt);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Arial,sans-serif}.wrap{max-width:1020px;margin:0 auto;padding:16px 12px 46px}h1{font-size:25px;margin:0 0 4px}h2{font-size:18px;margin:0 0 12px}.sub,.mini{color:var(--muted);font-size:13px;line-height:1.45}.top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:12px}.status{padding:9px 12px;border:1px solid var(--line);border-radius:999px;background:#0f182b;color:#c8d7ef;white-space:nowrap;font-size:13px}.card{background:rgba(17,26,47,.96);border:1px solid var(--line);border-radius:18px;padding:15px;margin:12px 0;box-shadow:0 14px 36px rgba(0,0,0,.22)}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}@media(max-width:780px){.grid2,.grid3{grid-template-columns:1fr}.top{display:block}.status{display:inline-block;margin-top:10px}}label{display:block;font-size:12px;color:#bdd0ed;margin:10px 0 6px}input,textarea,select{width:100%;border:1px solid #344765;background:#0c1427;color:var(--txt);border-radius:12px;padding:12px;font-size:15px;outline:0}textarea{min-height:110px;resize:vertical;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:13px}.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.btn{border:0;border-radius:12px;padding:12px 14px;font-weight:900;color:#fff;background:#33415f;cursor:pointer}.btn:active{transform:scale(.98)}.btn.green{background:var(--green);color:#052e16}.btn.red{background:var(--red)}.btn.blue{background:var(--blue)}.btn.yellow{background:var(--yellow);color:#2a1600}.btn.purple{background:var(--purple)}.btn.cyan{background:var(--cyan);color:#022a33}.btn.full{width:100%}.danger{background:linear-gradient(135deg,rgba(251,77,101,.15),rgba(17,26,47,.96))}.hidden{display:none}.result{white-space:pre-wrap;background:#071020;border:1px solid #283855;border-radius:14px;padding:12px;min-height:90px;max-height:280px;overflow:auto;color:#dbe7ff;font-size:13px}.tabs{display:flex;gap:8px;overflow:auto;padding-bottom:2px;margin:12px 0}.tab{border:1px solid var(--line);background:#10182a;color:#dfeaff;border-radius:999px;padding:10px 14px;font-weight:900;white-space:nowrap}.tab.active{background:#2563eb;border-color:#60a5fa}.pane{display:none}.pane.active{display:block}.list{max-height:330px;overflow:auto;display:grid;gap:8px}.item{background:#0d1527;border:1px solid #263653;border-radius:13px;padding:10px}.item b{font-size:14px}.item div{font-size:12px;color:#aab8d2;margin-top:4px;line-height:1.35}.empty{border:1px dashed #344461;color:#93a5c4;border-radius:12px;padding:12px;text-align:center}.ok{color:#86efac}.bad{color:#fecaca}.filebox{background:#0d1527;border:1px dashed #3b4c6f;border-radius:14px;padding:13px}.split-title{display:flex;justify-content:space-between;gap:8px;align-items:center}.statgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stat{background:#0d1527;border:1px solid #263653;border-radius:14px;padding:12px}.stat b{display:block;font-size:22px}.stat span{font-size:12px;color:#9fb0d0}.toast{position:fixed;left:12px;right:12px;bottom:12px;background:#0c1427;border:1px solid #344461;border-radius:14px;padding:12px;color:#fff;box-shadow:0 10px 30px rgba(0,0,0,.3);display:none;z-index:20}.toast.show{display:block}.mutedbtn{font-size:12px;color:#9fb0d0;background:transparent;border:0;text-decoration:underline;padding:8px;cursor:pointer}.advanced{border-top:1px solid #263653;margin-top:12px;padding-top:12px}.pill{display:inline-flex;padding:6px 9px;border-radius:999px;background:#0d1527;border:1px solid var(--line);color:#cbd5e1;font-size:12px;font-weight:800;margin:3px 4px 3px 0}.notice{border:1px solid rgba(56,189,248,.35);background:rgba(14,165,233,.08);border-radius:14px;padding:12px;color:#dff7ff;font-size:13px;line-height:1.45}\n.admin-embed-pending body{visibility:hidden}\nbody.admin-embedded{background:#08101f}\nbody.admin-embedded .wrap{padding:9px 7px 25px}\nbody.admin-embedded #admin-login-card{display:none!important}\nbody.admin-embedded .top{margin-bottom:10px}\nbody.admin-embedded .card{margin:9px 0}\n</style>\n<link rel=\"stylesheet\" href=\"./compact.css?v=1\">\n<link rel=\"stylesheet\" href=\"./quick-actions.css?v=1\">\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"top\">\n    <div><h1>Управление</h1><div class=\"sub\">QuizBot · только для владельца</div></div>\n    <div class=\"status\" id=\"status\"><span class=\"bad\">●</span> не подключено</div>\n  </div>\n\n  <div class=\"card\" id=\"admin-login-card\">\n    <h2>🔐 Вход</h2>\n    <div class=\"grid2\">\n      <div><label>Backend URL</label><input id=\"backend\" placeholder=\"https://your-site.netlify.app\"></div>\n      <div><label>ADMIN_SECRET</label><input id=\"secret\" type=\"password\" placeholder=\"Пароль админки\"></div>\n    </div>\n    <div class=\"row\" style=\"margin-top:12px\">\n      <button class=\"btn blue\" onclick=\"saveSettings(true)\">Сохранить и подключиться</button>\n      <button class=\"btn\" onclick=\"refreshAll()\">Обновить данные</button>\n    </div>\n    <div class=\"mini\">Один раз вводишь ссылку и пароль. Потом браузер запомнит.</div>\n    <button class=\"mutedbtn\" onclick=\"toggleAdvanced()\">Показать редкие кнопки</button>\n    <div id=\"advanced\" class=\"advanced hidden\"><div class=\"row\"><button class=\"btn\" onclick=\"health()\">Проверить backend</button><button class=\"btn yellow\" onclick=\"initAccess()\">Подготовить базу</button></div></div>\n  </div>\n\n  <nav class=\"tabs\" aria-label=\"Разделы панели\">\n    <button type=\"button\" class=\"tab active\" data-pane=\"users\" onclick=\"showPane('users',this)\"><span class=\"tab-icon\">👥</span>Люди</button>\n    <button type=\"button\" class=\"tab\" data-pane=\"access\" onclick=\"showPane('access',this)\"><span class=\"tab-icon\">💎</span>Доступ</button>\n    <button type=\"button\" class=\"tab\" data-pane=\"questions\" onclick=\"showPane('questions',this)\"><span class=\"tab-icon\">📚</span>Вопросы</button>\n    <button type=\"button\" class=\"tab\" data-pane=\"settings\" onclick=\"showPane('settings',this)\"><span class=\"tab-icon\">⚙️</span>Ещё</button>\n  </nav>\n\n  <section id=\"users\" class=\"pane active\" aria-label=\"Пользователи QuizBot\">\n    <div class=\"section-intro\">\n      <h2>👥 Пользователи QuizBot</h2>\n      <button type=\"button\" class=\"btn compact\" onclick=\"refreshUsers()\">↻ Обновить</button>\n    </div>\n    <div class=\"mini activity-note\">Активность только в этом мини-приложении. Данные появляются с момента включения учёта; время Telegram «в сети» не отслеживается.</div>\n    <div class=\"statgrid people-stats\" id=\"userStats\">\n      <div class=\"stat\"><b>—</b><span>Посетили</span></div>\n      <div class=\"stat\"><b>—</b><span>За 24 часа</span></div>\n      <div class=\"stat\"><b>—</b><span>Недавно</span></div>\n    </div>\n    <div class=\"people-toolbar\">\n      <input type=\"search\" id=\"userSearch\" placeholder=\"Поиск по ID, имени, @username\" autocomplete=\"off\" oninput=\"renderUsers()\">\n      <select id=\"userFilter\" aria-label=\"Фильтр пользователей\" onchange=\"renderUsers()\">\n        <option value=\"all\">Все пользователи</option>\n        <option value=\"recent\">Недавно активные</option>\n        <option value=\"today\">За последние 24 часа</option>\n        <option value=\"premium\">С Premium</option>\n        <option value=\"banned\">Заблокированные</option>\n      </select>\n    </div>\n    <div id=\"userList\" class=\"people-list\"><div class=\"empty\">Загрузка пользователей…</div></div>\n    <button type=\"button\" class=\"btn compact full hidden\" id=\"usersMore\" onclick=\"showMoreUsers()\">Показать ещё</button>\n    <div id=\"userCountNote\" class=\"mini\" aria-live=\"polite\"></div>\n  </section>\n\n  <div id=\"access\" class=\"pane\">\n    <div class=\"card quick-access-card\">\n      <div class=\"quick-header\">\n        <h2>⚡ Быстрые действия</h2>\n        <p class=\"mini\">Один Telegram ID — все основные действия.</p>\n      </div>\n      <label for=\"quickUserId\">Telegram ID пользователя</label>\n      <input id=\"quickUserId\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Вставь Telegram ID\">\n      <div class=\"quick-duration\">\n        <label for=\"quickDays\">Срок Premium</label>\n        <select id=\"quickDays\">\n          <option value=\"7\">7 дней</option>\n          <option value=\"30\" selected>30 дней</option>\n          <option value=\"90\">90 дней</option>\n          <option value=\"365\">1 год</option>\n          <option value=\"0\">Без срока</option>\n        </select>\n      </div>\n      <div class=\"quick-actions\">\n        <button type=\"button\" class=\"btn green\" data-quick-main=\"premium\" onclick=\"quickUserAction('premium')\">💎 Выдать Premium</button>\n        <button type=\"button\" class=\"btn\" data-quick-main=\"remove\" onclick=\"quickUserAction('remove')\">Снять Premium</button>\n        <button type=\"button\" class=\"btn red\" data-quick-main=\"ban\" onclick=\"quickUserAction('ban')\">🚫 Забанить</button>\n        <button type=\"button\" class=\"btn\" data-quick-main=\"unban\" onclick=\"quickUserAction('unban')\">Разбанить</button>\n      </div>\n      <div class=\"mini quick-note\">Можно выбрать пользователя во вкладке «Люди» — ID подставится автоматически.</div>\n    </div>\n    <details class=\"fold\" id=\"accessAdvanced\">\n      <summary>⚙️ Дополнительные параметры <span class=\"fold-hint\">Особые сроки, причины бана, привязка к устройству</span></summary>\n    <div class=\"grid2\">\n      <div class=\"card\">\n        <h2>💎 Выдать Premium</h2>\n        <label>Telegram ID</label><input id=\"premId\" inputmode=\"numeric\" placeholder=\"5305261101\">\n        <div class=\"grid2\"><div><label>Дней</label><input id=\"premDays\" type=\"number\" min=\"0\" value=\"30\"></div><div><label>Дата окончания, необязательно</label><input id=\"premExpires\" type=\"date\"></div></div>\n        <details class=\"fold fold-inline\"><summary>Дополнительно: устройство и заметка</summary>\n        <label>Fingerprint, необязательно</label><input id=\"premFp\" placeholder=\"45A2C438\">\n        <label>Заметка для себя</label><input id=\"premNote\" value=\"Выдано вручную\">\n        </details>\n        <div class=\"row\" style=\"margin-top:12px\"><button class=\"btn green\" onclick=\"givePremium()\">Выдать премиум</button><button class=\"btn red\" onclick=\"removePremium()\">Убрать</button><button class=\"btn\" onclick=\"checkUserFromPremium()\">Проверить</button></div>\n        <div class=\"mini\">Если fingerprint пустой — премиум работает на любом устройстве. Если заполнен — только на этом устройстве.</div>\n      </div>\n      <div class=\"card danger\">\n        <h2>🚫 Заблокировать</h2>\n        <label>Telegram ID</label><input id=\"banId\" inputmode=\"numeric\" placeholder=\"5305261101\">\n        <label>Описание для пользователя</label><textarea id=\"banReason\">Вы использовали читы</textarea>\n        <label>До даты, необязательно</label><input id=\"banUntil\" type=\"date\">\n        <div class=\"row\" style=\"margin-top:12px\"><button class=\"btn red\" onclick=\"banUser()\">Забанить</button><button class=\"btn green\" onclick=\"unbanUser()\">Разбанить</button></div>\n      </div>\n    </div>\n    </details>\n    <details class=\"fold dangerous\"><summary>⚠️ Массовые действия</summary><div class=\"card danger\">\n      <h2>🧹 Убрать премиум у всех</h2>\n      <div class=\"mini\">Баны не удаляются.</div>\n      <button class=\"btn red\" onclick=\"clearAllPremium()\">Убрать премиум у всех</button>\n    </div></details>\n  </div>\n\n  <div id=\"questions\" class=\"pane\">\n    <div class=\"card quick-question-card\">\n      <div class=\"quick-header\">\n        <h2>➕ Добавить вопрос</h2>\n        <p class=\"mini\">Без JSON. Старые вопросы сохраняются.</p>\n      </div>\n      <form id=\"quickQuestionForm\" onsubmit=\"quickAddQuestion(event)\">\n        <label for=\"quickSubject\">Предмет</label>\n        <select id=\"quickSubject\" required aria-label=\"Выбрать предмет\"></select>\n        <label for=\"quickQuestion\">Вопрос</label>\n        <textarea id=\"quickQuestion\" rows=\"2\" required maxlength=\"2000\" placeholder=\"Например: Что такое инфляция?\"></textarea>\n        <div class=\"quick-option-grid\">\n          <div><label for=\"quickOption0\">Ответ 1</label><input id=\"quickOption0\" required maxlength=\"1000\" placeholder=\"Первый вариант\"></div>\n          <div><label for=\"quickOption1\">Ответ 2</label><input id=\"quickOption1\" required maxlength=\"1000\" placeholder=\"Второй вариант\"></div>\n          <div><label for=\"quickOption2\">Ответ 3</label><input id=\"quickOption2\" required maxlength=\"1000\" placeholder=\"Третий вариант\"></div>\n          <div><label for=\"quickOption3\">Ответ 4</label><input id=\"quickOption3\" required maxlength=\"1000\" placeholder=\"Четвёртый вариант\"></div>\n        </div>\n        <label for=\"quickCorrect\">Правильный ответ</label>\n        <select id=\"quickCorrect\" required>\n          <option value=\"0\">Ответ 1</option><option value=\"1\">Ответ 2</option>\n          <option value=\"2\">Ответ 3</option><option value=\"3\">Ответ 4</option>\n        </select>\n        <button id=\"quickQuestionSave\" type=\"submit\" class=\"btn green full quick-save\">✓ Сохранить вопрос</button>\n      </form>\n    </div>\n    <div class=\"card\">\n      <div class=\"split-title\"><h2>📝 Вопросы</h2><button class=\"btn\" onclick=\"questionsInfo()\">Количество</button></div>\n      <div class=\"statgrid\" id=\"qStats\"><div class=\"stat\"><b>—</b><span>вопросов</span></div><div class=\"stat\"><b>—</b><span>предметов</span></div><div class=\"stat\"><b>—</b><span>версия</span></div></div>\n    </div>\n    <div class=\"grid2\">\n      <div class=\"card\">\n        <h2>Загрузить вопросы</h2>\n        <label>Куда загрузить</label><select id=\"importSubject\"></select>\n        <div class=\"row\" style=\"margin-top:8px\"><label style=\"display:flex;gap:8px;align-items:center;margin:0\"><input id=\"importFull\" type=\"checkbox\" style=\"width:auto\"> Импортировать весь JSON со всеми предметами</label></div>\n        <div class=\"filebox\" style=\"margin-top:10px\"><input type=\"file\" id=\"testsFile\" accept=\".json,application/json\" onchange=\"readTestsFile()\"></div>\n        <textarea id=\"testsJson\" placeholder=\"Или вставь JSON сюда\"></textarea>\n        <div class=\"row\" style=\"margin-top:12px\"><button class=\"btn green\" onclick=\"importQuestions()\">Сохранить вопросы</button><button class=\"btn red\" onclick=\"clearQuestionsBox()\">Очистить поле</button></div>\n        <div class=\"mini\">Если файл обычный массив вопросов — он загрузится в выбранный предмет. Если файл с subjects и включена галочка — заменит всю базу предметов.</div>\n      </div>\n      <div class=\"card\">\n        <h2>Экспорт</h2>\n        <button class=\"btn blue full\" onclick=\"exportQuestions()\">Получить текущие вопросы</button>\n        <div style=\"height:10px\"></div>\n        <button class=\"btn purple full\" onclick=\"downloadLastQuestions()\">Скачать JSON</button>\n      </div>\n    </div>\n    <details class=\"fold\" id=\"subjectFold\"><summary>📚 Управление предметами <span class=\"fold-hint\">Добавить, изменить или удалить</span></summary>\n  <div id=\"subjectsPane\">\n    <div class=\"card\">\n      <div class=\"split-title\"><h2>📚 Предметы</h2><button class=\"btn\" onclick=\"questionsInfo()\">Обновить</button></div>\n      <div id=\"subjectsList\" class=\"mini\">Список появится после подключения.</div>\n    </div>\n    <div class=\"card\">\n      <h2>➕ Добавить / изменить предмет</h2>\n      <div class=\"grid3\">\n        <div><label>Ключ предмета</label><input id=\"subjectKey\" placeholder=\"marketing\"></div>\n        <div><label>Полное название</label><input id=\"subjectTitle\" placeholder=\"Маркетинг\"></div>\n        <div><label>Короткое название</label><input id=\"subjectShort\" placeholder=\"Маркетинг\"></div>\n      </div>\n      <label>Эмодзи</label><input id=\"subjectEmoji\" placeholder=\"📚\" maxlength=\"4\">\n      <div class=\"row\" style=\"margin-top:12px\"><button class=\"btn green\" onclick=\"saveSubjectName()\">Сохранить предмет</button><button class=\"btn red\" onclick=\"deleteSubject()\">Удалить предмет</button></div>\n      <div class=\"mini\">Ключ лучше латиницей: marketing, macro, micro, finance. Его видно только в базе.</div>\n    </div>\n  </div>\n\n    </details>\n  </div>\n\n  <section id=\"settings\" class=\"pane\" aria-label=\"Дополнительные настройки\">\n    <h2 class=\"settings-heading\">⚙️ Дополнительно</h2>\n    <p class=\"mini settings-note\">Здесь редкие операции. Основные действия — во вкладках выше.</p>\n    <details class=\"fold\"><summary>📨 Отчёты бота <span class=\"fold-hint\">Настроить уведомления</span></summary>\n  <div id=\"reports\">\n    <div class=\"card\">\n      <h2>📨 Отчёты</h2>\n      <div class=\"grid2\"><div><label>Bot token для отчётов</label><input id=\"reportToken\" placeholder=\"123456:ABC...\"></div><div><label>Telegram ID / Chat ID получателя</label><input id=\"reportChatId\" placeholder=\"5305261101\"></div></div>\n      <div class=\"mini\" id=\"reportTokenInfo\">Сохранённый токен: —</div>\n      <label>Текст тестового отчёта</label><textarea id=\"reportTestText\">✅ Тестовый отчёт от QuizBot</textarea>\n      <div class=\"row\" style=\"margin-top:12px\"><button class=\"btn green\" onclick=\"saveReportSettings()\">Сохранить отчёты</button><button class=\"btn blue\" onclick=\"testReport()\">Отправить тест</button><button class=\"btn\" onclick=\"loadReportSettings()\">Обновить</button></div>\n    </div>\n  </div>\n\n    </details>\n    <details class=\"fold\"><summary>📋 Списки и технический ответ <span class=\"fold-hint\">Premium, блокировки и данные сервера</span></summary>\n  <div id=\"lists\">\n    <div class=\"grid2\">\n      <div class=\"card\"><h2>⭐ Премиум</h2><div id=\"premiumList\" class=\"list\"><div class=\"empty\">Пусто</div></div></div>\n      <div class=\"card\"><h2>🚫 Бан</h2><div id=\"banList\" class=\"list\"><div class=\"empty\">Пусто</div></div></div>\n    </div>\n    <div class=\"card\"><h2>Ответ backend</h2><div class=\"row\"><button class=\"btn\" onclick=\"copyResult()\">Копировать</button></div><div class=\"result\" id=\"result\">Ответы будут здесь.</div></div>\n  </div>    </details>\n  </section>\n\n</div>\n<div class=\"toast\" id=\"toast\"></div>\n<script src=\"./compact.js?v=1\"></script>\n<script>\nconst $=id=>document.getElementById(id);let lastExport=null;let subjectsMeta=[];\nfunction apiBase(){return location.origin}function secret(){return ''}function ownerInitData(){\n  try{\n    if(window.parent === window)return '';\n    return String(window.parent.Telegram?.WebApp?.initData||'');\n  }catch(e){return ''}\n}function cleanId(v){return String(v||'').replace(/\\D+/g,'')}function slug(v){return String(v||'').trim().toLowerCase().replace(/[^a-z0-9а-яё_-]+/gi,'-').replace(/^-+|-+$/g,'')}\nfunction toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}function setStatus(t,ok){$('status').innerHTML=`<span class=\"${ok?'ok':'bad'}\">●</span> ${t}`}function out(d){$('result').textContent=typeof d==='string'?d:JSON.stringify(d,null,2)}function toggleAdvanced(){$('advanced').classList.toggle('hidden')}\nfunction showPane(id,btn){document.querySelectorAll('.pane').forEach(p=>p.classList.remove('active'));document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));$(id)?.classList.add('active');(btn||document.querySelector('.tab[data-pane=\"'+id+'\"]'))?.classList.add('active');if(id==='users'&&window.refreshUsers)refreshUsers()}\nfunction loadSettings(){$('backend').value=localStorage.getItem('ep_admin_backend')||location.origin;$('secret').value=localStorage.getItem('ep_admin_secret')||''}async function saveSettings(auto){localStorage.setItem('ep_admin_backend',apiBase());localStorage.setItem('ep_admin_secret',secret());toast('Сохранено');if(auto){await health().catch(()=>{});await refreshAll().catch(()=>{})}}\nasync function req(path,method='GET',body=null){if(!apiBase())throw new Error('Backend URL пустой');const initData=ownerInitData();if(!initData)throw new Error('Откройте админку из Telegram Mini App');const opt={method,headers:{'X-Telegram-Init-Data':initData}};if(body){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(body)}const r=await fetch(apiBase()+path,opt);const text=await r.text();let data;try{data=JSON.parse(text)}catch(e){data={raw:text}}setStatus(r.status+' '+(r.ok?'OK':'ERROR'),r.ok);out(data);if(!r.ok){toast(data.error||'Ошибка');throw new Error(data.error||text||r.statusText)}toast('Готово');return data}\nasync function health(){const r=await fetch(apiBase()+'/api/health');const data=await r.json().catch(()=>({status:r.status}));setStatus(r.status+' '+(r.ok?'OK':'ERROR'),r.ok);out(data);return data}async function initAccess(){await req('/api/admin/init','POST',{force:false});await refreshLists(false)}async function refreshAll(){await questionsInfo().catch(()=>{});await loadReportSettings().catch(()=>{});await refreshLists(false).catch(()=>{})}\nasync function givePremium(){const user_id=cleanId($('premId').value);if(!user_id)return alert('Впиши Telegram ID');const body={user_id,note:$('premNote').value.trim()||'Выдано вручную'};const expires=$('premExpires').value;const days=Number($('premDays').value||0);const fp=$('premFp').value.trim().toUpperCase();if(expires)body.expires=expires;else if(days>0)body.days=days;if(fp)body.fingerprint=fp;await req('/api/admin/premium','POST',body);await refreshLists(false)}async function removePremium(){const user_id=cleanId($('premId').value);if(!user_id)return alert('Впиши Telegram ID');await req('/api/admin/premium/remove','POST',{user_id});await refreshLists(false)}async function clearAllPremium(){if(!confirm('Точно убрать премиум у ВСЕХ?'))return;const typed=prompt('Для подтверждения напиши: УБРАТЬ');if(typed!=='УБРАТЬ')return alert('Отменено');await req('/api/admin/premium/clear','POST',{confirm:'CLEAR_PREMIUM'});await refreshLists(false)}\nasync function banUser(){const user_id=cleanId($('banId').value);if(!user_id)return alert('Впиши Telegram ID');const body={user_id,reason:$('banReason').value.trim()||'Доступ заблокирован.'};if($('banUntil').value){body.until=$('banUntil').value;body.type='temporary'}else body.type='permanent';await req('/api/admin/ban','POST',body);await refreshLists(false)}async function unbanUser(){const user_id=cleanId($('banId').value);if(!user_id)return alert('Впиши Telegram ID');await req('/api/admin/unban','POST',{user_id});await refreshLists(false)}async function checkUserFromPremium(){const user_id=cleanId($('premId').value);if(!user_id)return alert('Впиши Telegram ID');const fingerprint=$('premFp').value.trim().toUpperCase();await req('/api/admin/check','POST',{user_id,fingerprint})}\nfunction escapeHtml(s){return String(s||'').replace(/[&<>\\\"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[ch]))}function renderObj(target,obj,type){const el=$(target);const users=(obj&&obj.users)||{};const entries=Object.entries(users);if(!entries.length){el.innerHTML='<div class=\"empty\">Пусто</div>';return}el.innerHTML=entries.map(([id,u])=>{const active=u&&u.active!==false?'активен':'выключен';const main=type==='premium'?`${u.expires?'до '+u.expires:'без срока'} ${u.fingerprint?' · FP '+u.fingerprint:''}`:`${u.reason||'без причины'} ${u.until?' · до '+u.until:''}`;return `<div class=\"item\"><b>${id}</b><div>${active}<br>${escapeHtml(main)}<br>${escapeHtml(u.note||'')}</div></div>`}).join('')}async function refreshLists(show=true){const data=await req('/api/admin/list','GET');renderObj('premiumList',data.premium_users,'premium');renderObj('banList',data.banned_users,'ban');if(!show)out({ok:true,counts:data.counts||{}})}function copyResult(){navigator.clipboard?.writeText($('result').textContent);toast('Скопировано')}\nfunction renderSubjects(list){subjectsMeta=list||[];if(!subjectsMeta.length){$('subjectsList').innerHTML='<div class=\"empty\">Предметов пока нет</div>';$('importSubject').innerHTML='<option value=\"marketing\">marketing</option>';return} $('subjectsList').innerHTML=subjectsMeta.map(s=>`<span class=\"pill\">${escapeHtml(s.emoji||'📚')} ${escapeHtml(s.title||s.key)} · ${escapeHtml(s.key)} · ${s.count||0}</span>`).join('');$('importSubject').innerHTML=subjectsMeta.map(s=>`<option value=\"${escapeHtml(s.key)}\">${escapeHtml((s.emoji||'📚')+' '+(s.title||s.key))} · ${s.count||0}</option>`).join('');const first=subjectsMeta[0];if(first&&!$('subjectKey').value){fillSubjectForm(first)}}\nfunction fillSubjectForm(s){$('subjectKey').value=s.key||'';$('subjectTitle').value=s.title||'';$('subjectShort').value=s.short||s.title||'';$('subjectEmoji').value=s.emoji||'📚'}\nfunction updateQStats(data){const total=data.total??'—';const version=data.data_version||'—';const list=data.subjects_list||[];renderSubjects(list);$('qStats').innerHTML=`<div class=\"stat\"><b>${total}</b><span>всего вопросов</span></div><div class=\"stat\"><b>${list.length}</b><span>предметов</span></div><div class=\"stat\"><b>${escapeHtml(version||'—')}</b><span>версия базы</span></div>`}\nasync function questionsInfo(){const data=await req('/api/admin/tests/info','GET');updateQStats(data)}async function saveSubjectName(){const key=slug($('subjectKey').value||$('subjectTitle').value);const title=$('subjectTitle').value.trim();const short=$('subjectShort').value.trim()||title;const emoji=$('subjectEmoji').value.trim()||'📚';if(!key)return alert('Напиши ключ предмета');if(!title)return alert('Напиши название предмета');const data=await req('/api/admin/tests/subject','POST',{key,title,short,emoji});updateQStats(data.counts||data)}async function deleteSubject(){const key=slug($('subjectKey').value);if(!key)return alert('Впиши ключ предмета');if(!confirm('Удалить предмет '+key+' вместе с вопросами?'))return;const data=await req('/api/admin/tests/subject/delete','POST',{key});updateQStats(data.counts||data)}\nasync function readTestsFile(){const f=$('testsFile').files[0];if(!f)return;const text=await f.text();$('testsJson').value=text;try{const data=JSON.parse(text);out({ok:true,file:f.name,preview_counts:countLocalTests(data)})}catch(e){out({ok:false,error:'Файл не похож на JSON: '+e.message})}}function countLocalTests(data){let d=data;if(Array.isArray(d))return {total:d.length,format:'array'};if(d.data&&d.data.subjects)d=d.data;if(d.tests&&Array.isArray(d.tests))return {total:d.tests.length,format:'tests'};if(d.subjects){let total=0,per={};for(const [k,s] of Object.entries(d.subjects)){const n=Array.isArray(s.tests)?s.tests.length:0;per[k]=n;total+=n}return {total,per_subject:per,data_version:d.data_version||''}}return {total:0,warning:'не найден subjects/tests'}}async function importQuestions(){const raw=$('testsJson').value.trim();if(!raw)return alert('Выбери tests.json или вставь JSON');let data;try{data=JSON.parse(raw)}catch(e){return alert('Ошибка JSON: '+e.message)}const full=$('importFull').checked;if(!confirm(full?'Заменить всю базу этим JSON?':'Сохранить вопросы в выбранный предмет?'))return;const body=full?data:{subject_key:$('importSubject').value||$('subjectKey').value||'marketing',title:$('subjectTitle').value.trim()||undefined,short:$('subjectShort').value.trim()||undefined,emoji:$('subjectEmoji').value.trim()||undefined,tests_data:data};const res=await req('/api/admin/tests/import','POST',body);updateQStats(res.counts||res.meta||res)}async function exportQuestions(){const data=await req('/api/admin/tests/export','GET');lastExport=data.tests_data;$('testsJson').value=JSON.stringify(data.tests_data,null,2);updateQStats(data)}function downloadLastQuestions(){if(!lastExport){try{lastExport=JSON.parse($('testsJson').value)}catch(e){return alert('Сначала нажми Получить текущие вопросы')}}const blob=new Blob([JSON.stringify(lastExport,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='tests.json';a.click();URL.revokeObjectURL(a.href)}function clearQuestionsBox(){$('testsJson').value=''}\nasync function loadReportSettings(){const data=await req('/api/admin/report-settings','GET');$('reportChatId').value=data.chat_id||'';$('reportTokenInfo').textContent='Сохранённый токен: '+(data.token_mask||'—')+(data.updated?' · обновлён '+data.updated:'');$('reportToken').value='';return data}async function saveReportSettings(){const bot_token=$('reportToken').value.trim();const chat_id=$('reportChatId').value.trim();if(!chat_id)return alert('Впиши Telegram ID / Chat ID');const body={chat_id};if(bot_token)body.bot_token=bot_token;const data=await req('/api/admin/report-settings','POST',body);$('reportTokenInfo').textContent='Сохранённый токен: '+(data.token_mask||'—')+(data.updated?' · обновлён '+data.updated:'');$('reportToken').value=''}async function testReport(){const text=$('reportTestText').value.trim()||'✅ Тестовый отчёт от QuizBot';await req('/api/admin/report-test','POST',{text})}\nasync function initializeEmbeddedAdmin(){\n  function deny(text){\n    document.body.replaceChildren();\n    const box=document.createElement('div');\n    box.className='wrap';\n    box.style.paddingTop='24px';\n    const title=document.createElement('h2');\n    title.textContent='🔒 Только владелец';\n    const message=document.createElement('p');\n    message.className='mini';\n    message.textContent=text;\n    box.append(title,message);\n    document.body.append(box);\n    document.documentElement.classList.remove('admin-embed-pending');\n  }\n  if(!EMBEDDED_ADMIN){deny('Откройте Mini App из Telegram-бота.');return;}\n  const initData=ownerInitData();\n  if(!initData){deny('Авторизация Telegram отсутствует. Вернитесь в бота и откройте приложение заново.');return;}\n  try{\n    const response=await fetch('/api/admin/me',{\n      headers:{'X-Telegram-Init-Data':initData},cache:'no-store',credentials:'same-origin'\n    });\n    const result=await response.json().catch(()=>({}));\n    if(!response.ok){\n      const code=String(result.code||'');\n      const messages={\n        TELEGRAM_BOT_NOT_CONFIGURED:'На Netlify не настроен токен Mini App. Проверьте переменную APP_BOT_TOKEN.',\n        TELEGRAM_SIGNATURE_INVALID:'Токен Mini App на Netlify не соответствует боту или Telegram-сессия устарела. Проверьте APP_BOT_TOKEN и откройте приложение заново.',\n        TELEGRAM_SESSION_MISSING:'Telegram не передал данные входа. Откройте Mini App из бота.',\n        NOT_ADMIN_OWNER:'Этот Telegram-аккаунт не является владельцем.'\n      };\n      deny(messages[code]||'Не удалось подтвердить вход в Netlify (HTTP '+response.status+').');\n      return;\n    }\n    if(!result?.admin){deny('Сервер не подтвердил доступ.');return;}\n    document.body.classList.add('admin-embedded');\n    document.documentElement.classList.remove('admin-embed-pending');\n    await Promise.all([refreshAll(),window.refreshUsers?refreshUsers():Promise.resolve()]);\n  }catch(error){\n    deny('Ошибка проверки доступа. Проверьте подключение и откройте страницу заново.');\n  }\n}\ninitializeEmbeddedAdmin();\n</script>\n<script src=\"./quick-actions.js?v=1\"></script>\n</body>\n</html>\n","/admin/quick-actions.css":"/* Two-minute tasks instead of the old full admin forms */\nbody.admin-embedded .quick-access-card,\nbody.admin-embedded .quick-question-card{border:1px solid #294869;background:#102139}\nbody.admin-embedded .quick-header h2{font-size:17px;margin:0 0 3px}\nbody.admin-embedded .quick-header .mini{margin:0 0 12px}\nbody.admin-embedded .quick-access-card label,\nbody.admin-embedded .quick-question-card label{display:block;margin:10px 0 5px;font-weight:650;color:#cbdaf0}\nbody.admin-embedded .quick-access-card #quickUserId{font-size:16px;font-weight:700;letter-spacing:.3px}\nbody.admin-embedded .quick-duration{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:9px 0}\nbody.admin-embedded .quick-duration label{margin:0}\nbody.admin-embedded .quick-duration select{width:150px;max-width:52%}\nbody.admin-embedded .quick-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:8px}\nbody.admin-embedded .quick-actions .btn{min-width:0;padding:12px 6px;min-height:44px;line-height:1.3;white-space:normal;font-size:12px}\nbody.admin-embedded .quick-note{margin:10px 0 0;color:#8ea9c9}\nbody.admin-embedded #accessAdvanced{margin-top:10px}\nbody.admin-embedded #accessAdvanced>.grid2{display:grid;grid-template-columns:1fr;gap:8px}\nbody.admin-embedded #accessAdvanced .card{margin:0 0 9px}\nbody.admin-embedded .quick-option-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px 10px}\nbody.admin-embedded .quick-option-grid input{min-width:0}\nbody.admin-embedded .quick-save{margin:14px 0 0;min-height:46px;font-size:14px}\nbody.admin-embedded .person-controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:10px}\nbody.admin-embedded .person-controls .btn{font-size:12px;min-height:36px;padding:8px 4px;white-space:normal;line-height:1.25}\nbody.admin-embedded .person-controls .btn.btn-user-premium{background:#275e48;color:#e2fff0}\nbody.admin-embedded .person-controls .btn.btn-user-ban{background:#65303d;color:#fff0f3}\nbody.admin-embedded .person-controls .btn.btn-user-unban{background:#25534e;color:#d1fff7}\nbody.admin-embedded .quick-actions .btn:disabled,\nbody.admin-embedded .quick-save:disabled,\nbody.admin-embedded .person-controls .btn:disabled{opacity:.55;cursor:wait}\n@media(max-width:360px){\n body.admin-embedded .quick-option-grid{grid-template-columns:1fr}\n body.admin-embedded .quick-actions .btn{font-size:11px}\n}\n","/admin/quick-actions.js":"/* One-step administration, only inside the already authenticated owner iframe.\n   All mutations continue to use the existing signed /api/admin/* routes. */\n'use strict';\nlet quickUserBusy=false;\nlet quickQuestionBusy=false;\n\nfunction quickValidId(value){\n  const raw=String(value||'').trim();\n  return /^[1-9]\\d{4,18}$/.test(raw)?raw:'';\n}\n\nasync function quickUserAction(action, userId){\n  if(quickUserBusy)return;\n  const id=quickValidId(userId||document.getElementById('quickUserId')?.value);\n  if(!id){\n    alert('Укажи Telegram ID пользователя.');\n    document.getElementById('quickUserId')?.focus();\n    return;\n  }\n  const paths={\n    premium:'/api/admin/premium',\n    remove:'/api/admin/premium/remove',\n    ban:'/api/admin/ban',\n    unban:'/api/admin/unban'\n  };\n  if(!paths[action])return;\n  if(action==='ban'&&!confirm('Заблокировать пользователя '+id+' в QuizBot?'))return;\n  if(action==='remove'&&!confirm('Убрать Premium у пользователя '+id+'?'))return;\n  const days=Number(document.getElementById('quickDays')?.value||30);\n  const payload={user_id:id};\n  if(action==='premium'){\n    if(!Number.isInteger(days)||days<0||days>36500)return alert('Выбери срок подписки.');\n    payload.note='Выдано через быструю панель';\n    if(days>0)payload.days=days;\n  }\n  if(action==='ban'){\n    payload.reason='Доступ заблокирован администратором.';\n    payload.type='permanent';\n  }\n  quickUserBusy=true;\n  document.querySelectorAll('[data-quick-main],[data-user-action]').forEach(button=>{button.disabled=true});\n  try{\n    await req(paths[action],'POST',payload);\n    const idInput=document.getElementById('quickUserId');\n    if(idInput)idInput.value=id;\n    const premiumInput=document.getElementById('premId');\n    if(premiumInput)premiumInput.value=id;\n    const banInput=document.getElementById('banId');\n    if(banInput)banInput.value=id;\n    const record=Array.isArray(visitedUsers)?visitedUsers.find(u=>String(u.id)===id):null;\n    if(record){\n      if(action==='premium')record.premium=true;\n      if(action==='remove')record.premium=false;\n      if(action==='ban'){record.banned=true;record.premium=false;}\n      if(action==='unban')record.banned=false;\n    }\n    if(typeof renderUsers==='function')renderUsers();\n    // Reload from the source of truth, without blocking the successful action.\n    await Promise.allSettled([\n      typeof refreshLists==='function'?refreshLists(false):Promise.resolve(),\n      typeof refreshUsers==='function'?refreshUsers():Promise.resolve()\n    ]);\n    const label={premium:'💎 Premium выдан',remove:'Premium снят',ban:'Пользователь заблокирован',unban:'Пользователь разблокирован'}[action];\n    toast(label+' · '+id);\n  }catch(error){\n    // req() already shows the detailed backend error.\n    console.warn('Quick action failed:',String(error?.message||error));\n  }finally{\n    quickUserBusy=false;\n    document.querySelectorAll('[data-quick-main],[data-user-action]').forEach(button=>{button.disabled=false});\n  }\n}\n\nfunction quickSubjectSync(){\n  const original=document.getElementById('importSubject');\n  const select=document.getElementById('quickSubject');\n  if(!original||!select)return;\n  const previouslySelected=select.value;\n  const options=Array.from(original.options).filter(o=>o.value);\n  if(options.length===0){\n    select.innerHTML='<option value=\"\">Загрузка предметов…</option>';\n    select.disabled=true;\n    return;\n  }\n  select.replaceChildren(...options.map(option=>option.cloneNode(true)));\n  if(options.some(option=>option.value===previouslySelected))select.value=previouslySelected;\n  select.disabled=false;\n}\n\nasync function quickAddQuestion(event){\n  event?.preventDefault?.();\n  if(quickQuestionBusy)return false;\n  quickSubjectSync();\n  const subjectKey=document.getElementById('quickSubject')?.value||'';\n  const question=String(document.getElementById('quickQuestion')?.value||'').trim();\n  const options=[0,1,2,3].map(i=>String(document.getElementById('quickOption'+i)?.value||'').trim());\n  const answer=Number(document.getElementById('quickCorrect')?.value);\n  if(!subjectKey)return alert('Выбери предмет.'),false;\n  if(!question)return alert('Напиши текст вопроса.'),false;\n  if(options.some(option=>!option))return alert('Заполни все четыре варианта ответа.'),false;\n  if(!Number.isInteger(answer)||answer<0||answer>3)return alert('Выбери правильный ответ.'),false;\n  const uid=typeof crypto!=='undefined'&&typeof crypto.randomUUID==='function'\n    ?crypto.randomUUID()\n    :Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,11);\n  const questionData={id:'manual-'+uid,question,options,answer,generated:false,source:'manual'};\n  const submit=document.getElementById('quickQuestionSave');\n  quickQuestionBusy=true;\n  if(submit){submit.disabled=true;submit.textContent='Сохранение…'}\n  try{\n    // Important: append instead of replacing any existing questions or subjects.\n    await req('/api/admin/tests/import','POST',{\n      subject_key:subjectKey,\n      mode:'append',\n      tests_data:[questionData]\n    });\n    const original=document.getElementById('quickQuestion');\n    if(original)original.value='';\n    for(let i=0;i<4;i++)document.getElementById('quickOption'+i).value='';\n    document.getElementById('quickCorrect').value='0';\n    await questionsInfo().catch(()=>{});\n    toast('✓ Вопрос добавлен, другие вопросы сохранены');\n    original?.focus();\n  }catch(error){\n    console.warn('Could not append question:',String(error?.message||error));\n  }finally{\n    quickQuestionBusy=false;\n    if(submit){submit.disabled=false;submit.textContent='✓ Сохранить вопрос'}\n  }\n  return false;\n}\n\nfunction initQuickActions(){\n  const source=document.getElementById('importSubject');\n  if(source&&typeof MutationObserver==='function'){\n    const observer=new MutationObserver(quickSubjectSync);\n    observer.observe(source,{childList:true,subtree:true});\n  }\n  quickSubjectSync();\n  const userList=document.getElementById('userList');\n  userList?.addEventListener('click',event=>{\n    const button=event.target.closest('[data-user-action]');\n    if(!button||!userList.contains(button))return;\n    quickUserAction(button.dataset.userAction,button.dataset.userId);\n  });\n  // Telegram may asynchronously populate subjects after the owner session is verified.\n  window.addEventListener('focus',quickSubjectSync);\n}\nif(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initQuickActions,{once:true});\nelse initQuickActions();\n"};
